I apologize for the error. Google Apps Script runs in a specialized environment that does not support the `export` keyword found in modern JavaScript/TypeScript modules.

Please replace the content of your **Google Apps Script** (the file in the script editor) with the code below. I have rewritten it to be fully compatible with the Google Apps Script runtime.

# Updated files:

## backend/Code.gs

```javascript
// Google Apps Script - Backend Code
// Copy this entire file into your Google Apps Script editor (Code.gs)

/**
 * Handle HTTP GET requests (Fetching Data)
 */
function doGet(e) {
  try {
    const sheet = getOrCreateSheet();
    const data = sheet.getDataRange().getValues();

    // If sheet is empty (only headers or nothing), return empty list
    if (data.length <= 1) {
       return createJSONOutput({ transactions: [] });
    }

    const headers = data[0];
    const rows = data.slice(1);

    // Map rows to Transaction objects
    const transactions = rows.map(function(row) {
      return {
        id: String(row[0]),
        date: formatDate(row[1]), // Ensure date is string
        employeeId: String(row[2]),
        employeeName: row[3],
        designation: row[4],
        department: row[5],
        typeOfEmployee: row[6],
        toolName: row[7],
        entryType: row[8],
        quantity: Number(row[9]),
        condition: row[10],
        remarks: row[11]
      };
    });

    return createJSONOutput({ transactions: transactions });

  } catch (error) {
    return createJSONOutput({ status: 'error', message: error.toString() });
  }
}

/**
 * Handle HTTP POST requests (Saving Data)
 */
function doPost(e) {
  // Lock to prevent concurrent editing race conditions
  const lock = LockService.getScriptLock();
  lock.tryLock(10000); // Wait up to 10 seconds

  try {
    const sheet = getOrCreateSheet();
    const requestData = JSON.parse(e.postData.contents);
    const p = requestData.payload;

    if (requestData.action === 'addTransaction') {
      // Append new row
      sheet.appendRow([
        p.id,
        p.date,
        p.employeeId || '',
        p.employeeName || '',
        p.designation || '',
        p.department || '',
        p.typeOfEmployee || '',
        p.toolName,
        p.entryType,
        p.quantity,
        p.condition,
        p.remarks || ''
      ]);

      return createJSONOutput({ status: 'success' });
    }

    return createJSONOutput({ status: 'error', message: 'Unknown action' });

  } catch (error) {
    return createJSONOutput({ status: 'error', message: error.toString() });
  } finally {
    lock.releaseLock();
  }
}

/**
 * Helper: Get or Create the "Transactions" sheet
 */
function getOrCreateSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName("Transactions");

  if (!sheet) {
    sheet = ss.insertSheet("Transactions");
    // Add Headers
    sheet.appendRow([
      "ID", 
      "Date", 
      "Employee ID", 
      "Employee Name", 
      "Designation", 
      "Department", 
      "Type of Employee", 
      "Tool Name", 
      "Entry Type", 
      "Quantity", 
      "Condition", 
      "Remarks"
    ]);
    // Freeze header row
    sheet.setFrozenRows(1);
  }
  return sheet;
}

/**
 * Helper: Create JSON Response
 */
function createJSONOutput(data) {
  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

/**
 * Helper: Simple date formatter
 */
function formatDate(date) {
  if (!date) return '';
  // If it's already a string, return it
  if (typeof date === 'string') return date;
  // If it's a GAS Date object, format it to YYYY-MM-DD
  try {
    return Utilities.formatDate(date, Session.getScriptTimeZone(), "yyyy-MM-dd");
  } catch (e) {
    return String(date);
  }
}
```

