## backend/Code.gs

Updated to read/write to the "Daily Entry" sheet and match your screenshot's column order exactly.

```javascript
// Google Apps Script - Backend Code
// Copy this entire file into your Google Apps Script editor (Code.gs)

/**
 * Handle HTTP GET requests (Fetching Data)
 */
function doGet(e) {
  try {
    const sheet = getOrCreateSheet();
    const data = sheet.getDataRange().getValues();

    // If sheet is empty (only headers or nothing), return empty list
    if (data.length <= 1) {
       return createJSONOutput({ transactions: [] });
    }

    // Slice starts at 1 to skip header row
    const rows = data.slice(1);

    // Map "Daily Entry" columns to App Transaction objects
    // Column Mapping based on your Screenshot:
    // 0: Updated Date
    // 1: ID (Employee ID)
    // 2: Name
    // 3: Designation
    // 4: Department
    // 5: Type of Employee
    // 6: Item Name
    // 7: Entry Type
    // 8: Quantity
    // 9: Given Tools Type (Condition)
    // 10: Remarks (Assuming it's the next column)

    const transactions = rows.map(function(row, index) {
      // Generate a unique ID based on row index since sheet doesn't have one
      const uniqueId = 'row-' + (index + 2); 

      return {
        id: uniqueId,
        date: formatDate(row[0]),
        employeeId: String(row[1] || ''),
        employeeName: row[2],
        designation: row[3],
        department: row[4],
        typeOfEmployee: row[5],
        toolName: row[6],
        entryType: row[7],
        quantity: Number(row[8] || 0),
        condition: row[9],
        remarks: row[10] || ''
      };
    });

    return createJSONOutput({ transactions: transactions });

  } catch (error) {
    return createJSONOutput({ status: 'error', message: error.toString() });
  }
}

/**
 * Handle HTTP POST requests (Saving Data)
 */
function doPost(e) {
  const lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    const sheet = getOrCreateSheet();
    const requestData = JSON.parse(e.postData.contents);
    const p = requestData.payload;

    if (requestData.action === 'addTransaction') {
      // Append new row matching "Daily Entry" structure
      sheet.appendRow([
        p.date,                    // Col A: Updated Date
        p.employeeId || '',        // Col B: ID
        p.employeeName || '',      // Col C: Name
        p.designation || '',       // Col D: Designation
        p.department || '',        // Col E: Department
        p.typeOfEmployee || '',    // Col F: Type
        p.toolName,                // Col G: Item Name
        p.entryType,               // Col H: Entry Type
        p.quantity,                // Col I: Quantity
        p.condition,               // Col J: Given Tools Type
        p.remarks || ''            // Col K: Remarks
      ]);

      return createJSONOutput({ status: 'success' });
    }

    return createJSONOutput({ status: 'error', message: 'Unknown action' });

  } catch (error) {
    return createJSONOutput({ status: 'error', message: error.toString() });
  } finally {
    lock.releaseLock();
  }
}

/**
 * Helper: Get "Daily Entry" sheet
 */
function getOrCreateSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  // TARGET THE EXISTING SHEET NAME FROM YOUR SCREENSHOT
  let sheet = ss.getSheetByName("Daily Entry");

  if (!sheet) {
    // Fallback if not found (should not happen if you have the sheet)
    sheet = ss.insertSheet("Daily Entry");
    sheet.appendRow([
      "Updated Date", "ID", "Name", "Designation", "Department", 
      "Type of Employee", "Item Name", "Entry Type", "Quantity", 
      "Given Tools Type", "Remarks"
    ]);
  }
  return sheet;
}

function createJSONOutput(data) {
  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

function formatDate(date) {
  if (!date) return '';
  if (typeof date === 'string') return date;
  try {
    // Format to match your sheet style: dd-MMM-yyyy (e.g., 12-May-2024)
    return Utilities.formatDate(date, Session.getScriptTimeZone(), "dd-MMM-yyyy");
  } catch (e) {
    return String(date);
  }
}
```

## App.tsx

Updated to dynamically discover new tools from the spreadsheet so you don't have to manually update the code every time you add a new tool type in the sheet.

```tsx
import React, { useState, useMemo, useEffect } from 'react';
import { 
  LogOut, 
  Search, 
  Plus, 
  FileSpreadsheet, 
  Users, 
  Package, 
  Loader2,
  RefreshCw
} from 'lucide-react';
import { USERS, TOOL_CATALOG } from './constants';
import { User, Transaction } from './types';
import ToolModal from './components/ToolModal';
import AIChat from './components/AIChat';
import Login from './components/Login';
import EmployeeDashboard from './components/EmployeeDashboard';
import { fetchTransactions, saveTransactionToSheet } from './services/sheetService';

type Tab = 'employee' | 'daily' | 'stock';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<Tab>('employee');
  const [employeeSearchId, setEmployeeSearchId] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // --- Data Loading ---

  const loadData = async () => {
    setIsLoading(true);
    try {
      const data = await fetchTransactions();
      setTransactions(data);
    } catch (e) {
      console.error("Error loading data", e);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  // --- Actions ---

  const handleSaveTransaction = async (trx: Transaction) => {
    // Optimistic Update
    const newTransactions = editingTransaction 
      ? transactions.map(t => t.id === trx.id ? trx : t) 
      : [...transactions, trx];

    setTransactions(newTransactions);
    setEditingTransaction(null);

    // Find the employee user object to send details to DB
    const empUser = USERS.find(u => u.id === trx.employeeId);

    // Save to Sheet
    const success = await saveTransactionToSheet(trx, empUser);
    if (!success) {
      alert("Note: Data saved locally but failed to sync to Google Sheet. Check console/connection.");
    }
  };

  // --- Calculations ---

  const selectedEmployee = useMemo(() => {
    // Try to find in hardcoded users, OR find from transaction history if missing
    let found = USERS.find(u => u.id === employeeSearchId && u.role === 'employee');

    if (!found) {
        // Look in transactions for this ID to support employees not in constants.ts
        const empTrx = transactions.find(t => t.employeeId === employeeSearchId);
        if (empTrx && empTrx.employeeId) {
            found = {
                id: empTrx.employeeId,
                name: empTrx['employeeName'] || 'Unknown',
                role: 'employee',
                designation: empTrx['designation'],
                department: empTrx['department'],
                typeOfEmployee: empTrx['typeOfEmployee'] as any
            };
        }
    }
    return found;
  }, [employeeSearchId, transactions]);

  // Helper: Get unique tool names from both Catalog AND Transactions
  const allToolNames = useMemo(() => {
      const names = new Set(TOOL_CATALOG.map(t => t.name));
      transactions.forEach(t => {
          if (t.toolName) names.add(t.toolName);
      });
      return Array.from(names).sort();
  }, [transactions]);

  // Derived: Employee Specific Tools List
  const employeeToolsData = useMemo(() => {
    if (!selectedEmployee) return [];

    const empTrx = transactions.filter(t => t.employeeId === selectedEmployee.id);
    const toolsMap = new Map<string, { 
      name: string, price: number, distributed: number, returned: number, faulty: number, damage: number, lost: number, remarks: string 
    }>();

    // Initialize all known tools
    allToolNames.forEach(name => {
      const catalogItem = TOOL_CATALOG.find(c => c.name === name);
      toolsMap.set(name, {
        name: name,
        price: catalogItem?.purchasePrice || 0,
        distributed: 0,
        returned: 0,
        faulty: 0,
        damage: 0,
        lost: 0,
        remarks: ''
      });
    });

    // Aggregate Transactions
    empTrx.forEach(t => {
      const tool = toolsMap.get(t.toolName);
      // If tool wasn't in catalog but is in transactions, create it now
      if (!tool) {
          const newTool = {
            name: t.toolName,
            price: 0,
            distributed: 0,
            returned: 0,
            faulty: 0,
            damage: 0,
            lost: 0,
            remarks: ''
          };
          toolsMap.set(t.toolName, newTool);
          // Re-get it to safe ref
          const ref = toolsMap.get(t.toolName)!;
          applyTrxToTool(ref, t);
      } else {
          applyTrxToTool(tool, t);
      }
    });

    // Return all where Distributed > 0
    return Array.from(toolsMap.values()).filter(t => t.distributed > 0);

  }, [selectedEmployee, transactions, allToolNames]);

  function applyTrxToTool(tool: any, t: Transaction) {
      if (t.entryType === 'Distribute') tool.distributed += t.quantity;
      if (t.entryType === 'Return') tool.returned += t.quantity;
      if (t.entryType === 'Faulty Return') tool.faulty += t.quantity;
      if (t.entryType === 'Damage') tool.damage += t.quantity;
      if (t.entryType === 'Lost') tool.lost += t.quantity;
      if (t.remarks) tool.remarks = t.remarks; 
  }

  // Derived: Stock Summary
  const stockSummaryData = useMemo(() => {
    const summary = allToolNames.map(name => {
      const toolTrx = transactions.filter(t => t.toolName === name);
      const catalogItem = TOOL_CATALOG.find(c => c.name === name);

      let purchase = 0;
      let distributed = 0;
      let returned = 0;
      let faulty = 0;
      let damage = 0;
      let lost = 0;

      toolTrx.forEach(t => {
        if (t.entryType === 'Stock IN') purchase += t.quantity;
        if (t.entryType === 'Distribute') distributed += t.quantity;
        if (t.entryType === 'Return') returned += t.quantity;
        if (t.entryType === 'Faulty Return') faulty += t.quantity;
        if (t.entryType === 'Damage') damage += t.quantity;
        if (t.entryType === 'Lost') lost += t.quantity;
      });

      // Stock Now Calculation
      // If no Stock IN found, assume 0 or maybe rely on purchase? 
      // For now, simple math: Stock IN - Distributed + Returned
      const stockNow = purchase - distributed + returned;

      return {
        name: name,
        purchase,
        distributed,
        returned,
        faulty,
        damage,
        lost,
        stockNow
      };
    });
    return summary;
  }, [transactions, allToolNames]);


  // Derived: Employee Tools for Dashboard
  const getToolsForEmployee = (userId: string) => {
    const myTrx = transactions.filter(t => t.employeeId === userId);
    return myTrx.filter(t => t.entryType === 'Distribute').map((t) => ({
      id: t.id,
      name: t.toolName,
      brand: 'Generic',
      serialNumber: `SN-${t.id}`,
      status: 'In Use',
      quantity: t.quantity,
      assignedDate: t.date,
      remarks: t.remarks
    })) as any[];
  };

  // --- Render ---

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center gap-4">
        <Loader2 className="w-10 h-10 text-blue-600 animate-spin" />
        <p className="text-slate-500 font-medium">Loading inventory data...</p>
      </div>
    );
  }

  if (!user) {
    return <Login onLogin={setUser} />;
  }

  if (user.role === 'employee') {
    return <EmployeeDashboard user={user} tools={getToolsForEmployee(user.id)} onLogout={() => setUser(null)} />;
  }

  return (
    <div className="min-h-screen bg-slate-100 font-sans text-slate-900 pb-20">

      {/* Top Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <img src="https://ui-avatars.com/api/?name=SARBS&background=0D9488&color=fff" className="w-8 h-8 rounded" alt="Logo" />
            <div>
               <h1 className="text-lg font-bold text-slate-800 leading-tight">SARBS Communications Ltd.</h1>
               <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">Tools Management System</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
             <button onClick={loadData} className="p-2 text-slate-400 hover:text-blue-600 transition-colors" title="Refresh Data">
               <RefreshCw className="w-5 h-5" />
             </button>
             <div className="text-right hidden sm:block">
               <div className="text-sm font-bold text-slate-800">{user.name}</div>
               <div className="text-xs text-slate-500">Administrator</div>
             </div>
             <button onClick={() => setUser(null)} className="p-2 text-slate-400 hover:text-red-600 transition-colors">
               <LogOut className="w-5 h-5" />
             </button>
          </div>
        </div>

        {/* Navigation Tabs */}
        <div className="max-w-7xl mx-auto px-4 mt-2 flex gap-1 overflow-x-auto">
           <button 
             onClick={() => setActiveTab('employee')}
             className={`px-4 py-3 text-sm font-bold border-b-2 transition-colors flex items-center gap-2 whitespace-nowrap ${activeTab === 'employee' ? 'border-blue-600 text-blue-600 bg-blue-50' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
           >
             <Users className="w-4 h-4" /> Stock + Employee Summary
           </button>
           <button 
             onClick={() => setActiveTab('daily')}
             className={`px-4 py-3 text-sm font-bold border-b-2 transition-colors flex items-center gap-2 whitespace-nowrap ${activeTab === 'daily' ? 'border-amber-500 text-amber-700 bg-amber-50' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
           >
             <FileSpreadsheet className="w-4 h-4" /> Daily Entry
           </button>
           <button 
             onClick={() => setActiveTab('stock')}
             className={`px-4 py-3 text-sm font-bold border-b-2 transition-colors flex items-center gap-2 whitespace-nowrap ${activeTab === 'stock' ? 'border-cyan-500 text-cyan-700 bg-cyan-50' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
           >
             <Package className="w-4 h-4" /> Stock Summary
           </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-6">

        {/* VIEW 1: Stock + Employee Summary */}
        {activeTab === 'employee' && (
          <div className="space-y-6">
             <div className="bg-white p-6 rounded-lg shadow-sm border border-slate-200">
                <div className="flex items-end gap-4 max-w-xl">
                   <div className="flex-1">
                      <label className="block text-sm font-bold text-slate-700 mb-1">Search Employee ID 👉</label>
                      <div className="relative">
                         <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                         <input 
                           type="text" 
                           className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded focus:ring-2 focus:ring-blue-500 outline-none"
                           placeholder="Enter ID (e.g. 10101)"
                           value={employeeSearchId}
                           onChange={e => setEmployeeSearchId(e.target.value)}
                         />
                      </div>
                   </div>
                   <div className="text-right flex-1">
                      <p className="text-sm font-bold text-slate-500">Date</p>
                      <p className="text-lg font-mono font-bold text-slate-800">{new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: '2-digit' })}</p>
                   </div>
                </div>
             </div>

             {selectedEmployee ? (
               <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden animate-in fade-in slide-in-from-bottom-4">
                  {/* Employee Header Card */}
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-px bg-slate-200 border-b border-slate-200">
                     <div className="bg-white p-4">
                        <p className="text-xs text-slate-500 font-bold uppercase">Name</p>
                        <p className="font-bold text-slate-800">{selectedEmployee.name}</p>
                     </div>
                     <div className="bg-white p-4">
                        <p className="text-xs text-slate-500 font-bold uppercase">Designation</p>
                        <p className="font-medium text-slate-700">{selectedEmployee.designation}</p>
                     </div>
                     <div className="bg-white p-4">
                        <p className="text-xs text-slate-500 font-bold uppercase">Department</p>
                        <p className="font-medium text-slate-700">{selectedEmployee.department}</p>
                     </div>
                     <div className="bg-white p-4">
                        <p className="text-xs text-slate-500 font-bold uppercase">Type</p>
                        <span className="inline-block px-2 py-0.5 rounded text-xs font-bold bg-green-100 text-green-700">{selectedEmployee.typeOfEmployee}</span>
                     </div>
                  </div>

                  {/* Summary Stats Row */}
                  <div className="bg-slate-50 px-4 py-2 border-b border-slate-200 flex justify-between items-center">
                     <span className="text-sm font-bold text-slate-600">Total Tools Assigned:</span>
                     <span className="text-lg font-bold text-blue-600">
                        {employeeToolsData.reduce((acc, curr) => acc + (curr.distributed - curr.returned), 0)}
                     </span>
                  </div>

                  {/* The Table */}
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm text-center">
                      <thead>
                        <tr className="bg-slate-100 border-b border-slate-200 text-slate-700">
                          <th className="px-4 py-3 font-bold text-left w-1/4">Tools Name</th>
                          <th className="px-4 py-3 font-bold border-l border-slate-200">Purchase Price</th>
                          <th className="px-4 py-3 font-bold border-l border-slate-200">Distributed Qty</th>
                          <th className="px-4 py-3 font-bold border-l border-slate-200">Return Qty</th>
                          <th className="px-4 py-3 font-bold border-l border-slate-200">Faulty Return</th>
                          <th className="px-4 py-3 font-bold border-l border-slate-200">Damage</th>
                          <th className="px-4 py-3 font-bold border-l border-slate-200">Lost</th>
                          <th className="px-4 py-3 font-bold border-l border-slate-200 bg-green-50 text-green-800">Final Tools Qty</th>
                          <th className="px-4 py-3 font-bold border-l border-slate-200 text-left">Remarks</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {employeeToolsData.map((row) => (
                          <tr key={row.name} className="hover:bg-slate-50">
                            <td className="px-4 py-2 text-left font-medium text-slate-800">{row.name}</td>
                            <td className="px-4 py-2 border-l border-slate-100">{row.price > 0 ? row.price : '-'}</td>
                            <td className="px-4 py-2 border-l border-slate-100">{row.distributed || ''}</td>
                            <td className="px-4 py-2 border-l border-slate-100">{row.returned || ''}</td>
                            <td className="px-4 py-2 border-l border-slate-100">{row.faulty || ''}</td>
                            <td className="px-4 py-2 border-l border-slate-100">{row.damage || ''}</td>
                            <td className="px-4 py-2 border-l border-slate-100">{row.lost || ''}</td>
                            <td className="px-4 py-2 border-l border-slate-100 font-bold bg-green-50 text-green-700">
                              {(row.distributed - row.returned - row.lost)}
                            </td>
                            <td className="px-4 py-2 border-l border-slate-100 text-left text-xs text-slate-500">{row.remarks}</td>
                          </tr>
                        ))}
                        {employeeToolsData.length === 0 && (
                          <tr>
