## backend/Code.gs

Updated to handle metadata from "Data Validation" sheet.

```javascript
// Google Apps Script - Backend Code
// Copy this entire file into your Google Apps Script editor (Code.gs)

function doGet(e) {
  try {
    const transactions = getTransactions();
    const metadata = getMetadata();

    return createJSONOutput({ 
      status: 'success',
      transactions: transactions,
      employees: metadata.employees,
      tools: metadata.tools
    });

  } catch (error) {
    return createJSONOutput({ status: 'error', message: error.toString() });
  }
}

function doPost(e) {
  const lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    const sheet = getSheet("Daily Entry");
    const requestData = JSON.parse(e.postData.contents);
    const p = requestData.payload;

    if (requestData.action === 'addTransaction') {
      // Append matching your exact Daily Entry structure
      sheet.appendRow([
        p.date,                    // Col A: Updated Date
        p.employeeId || '',        // Col B: ID
        p.employeeName || '',      // Col C: Name
        p.designation || '',       // Col D: Designation
        p.department || '',        // Col E: Department
        p.typeOfEmployee || '',    // Col F: Type
        p.toolName,                // Col G: Item Name
        p.entryType,               // Col H: Entry Type
        p.quantity,                // Col I: Quantity
        p.condition,               // Col J: Given Tools Type
        p.remarks || ''            // Col K: Remarks
      ]);

      return createJSONOutput({ status: 'success' });
    }

    return createJSONOutput({ status: 'error', message: 'Unknown action' });

  } catch (error) {
    return createJSONOutput({ status: 'error', message: error.toString() });
  } finally {
    lock.releaseLock();
  }
}

// --- Helpers ---

function getTransactions() {
  const sheet = getSheet("Daily Entry");
  const data = sheet.getDataRange().getValues();
  if (data.length <= 1) return [];

  const rows = data.slice(1);
  return rows.map(function(row, index) {
    return {
      id: 'row-' + (index + 2),
      date: formatDate(row[0]),
      employeeId: String(row[1] || ''),
      employeeName: row[2],
      designation: row[3],
      department: row[4],
      typeOfEmployee: row[5],
      toolName: row[6],
      entryType: row[7],
      quantity: Number(row[8] || 0),
      condition: row[9],
      remarks: row[10] || ''
    };
  });
}

function getMetadata() {
  const sheet = getSheet("Data Validation");
  // Assuming data exists. Get full range.
  // We need to find the last row for Columns A-E (Employees) and Column G (Tools)

  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return { employees: [], tools: [] };

  const range = sheet.getRange(2, 1, lastRow - 1, 7).getValues(); // Get A2:G(last)

  const employees = [];
  const tools = [];
  const addedEmpIds = {};
  const addedTools = {};

  for (let i = 0; i < range.length; i++) {
    const row = range[i];

    // Process Employee (Cols A-E: 0-4)
    const empId = String(row[0]);
    if (empId && empId !== '' && !addedEmpIds[empId]) {
      employees.push({
        id: empId,
        name: row[1],
        designation: row[2],
        department: row[3],
        typeOfEmployee: row[4]
      });
      addedEmpIds[empId] = true;
    }

    // Process Tool (Col G: 6)
    const toolName = String(row[6]);
    if (toolName && toolName !== '' && !addedTools[toolName]) {
      tools.push(toolName);
      addedTools[toolName] = true;
    }
  }

  return { employees: employees, tools: tools };
}

function getSheet(name) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
  }
  return sheet;
}

function createJSONOutput(data) {
  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

function formatDate(date) {
  if (!date) return '';
  if (typeof date === 'string') return date;
  try {
    return Utilities.formatDate(date, Session.getScriptTimeZone(), "dd-MMM-yyyy");
  } catch (e) {
    return String(date);
  }
}
