```typescript
import { User } from '../types';

declare global {
  interface Window {
    jspdf: any;
  }
}

export const generateEmployeePDF = (user: User | { name: string, id: string, department?: string, designation?: string }, tools: any[]) => {
  if (!window.jspdf) {
    alert("PDF library loading. Please try again in a moment.");
    return;
  }

  const { jsPDF } = window.jspdf;
  const doc = new jsPDF();

  // Header
  doc.setFillColor(13, 148, 136); // Teal color
  doc.rect(0, 0, 210, 40, 'F');

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.setFont("helvetica", "bold");
  doc.text("SARBS Communications Ltd.", 14, 20);

  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.text("Tools & Inventory Report", 14, 30);
  doc.text(`Generated: ${new Date().toLocaleDateString()}`, 150, 30);

  // Employee Details
  doc.setTextColor(40, 40, 40);
  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.text("Employee Details:", 14, 55);

  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.text(`Name: ${user.name}`, 14, 62);
  doc.text(`ID: ${user.id}`, 14, 67);
  doc.text(`Designation: ${user.designation || 'N/A'}`, 100, 62);
  doc.text(`Department: ${user.department || 'N/A'}`, 100, 67);

  // Table Data Preparation
  const tableRows = tools.map((tool) => [
    tool.name,
    tool.quantity,
    tool.assignedDate || '-',
    tool.remarks || '-'
  ]);

  // Table
  doc.autoTable({
    startY: 75,
    head: [['Tool Name', 'Qty', 'Assigned Date', 'Remarks']],
    body: tableRows,
    theme: 'striped',
    headStyles: { fillColor: [13, 148, 136] },
    styles: { fontSize: 9 },
  });

  // Footer
  const pageCount = doc.internal.getNumberOfPages();
  for(let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text('Authorized by Admin', 14, 285);
    doc.text('Page ' + i + ' of ' + pageCount, 190, 285, { align: 'right' });
  }

  doc.save(`Tools_Report_${user.id}_${new Date().toISOString().split('T')[0]}.pdf`);
};
