```typescript
import { Transaction, User } from '../types';
import { GOOGLE_SCRIPT_URL, INITIAL_TRANSACTIONS } from '../constants';

const HEADERS = {
  'Content-Type': 'text/plain;charset=utf-8', 
};

interface SheetResponse {
  transactions: Transaction[];
  employees: any[]; // Metadata from Data Validation
  tools: string[]; // Metadata from Data Validation
}

export const fetchSheetData = async (): Promise<SheetResponse> => {
  if (!GOOGLE_SCRIPT_URL) {
    console.warn("No Google Script URL provided. Using mock data.");
    return {
      transactions: INITIAL_TRANSACTIONS,
      employees: [],
      tools: []
    };
  }

  try {
    const response = await fetch(`${GOOGLE_SCRIPT_URL}?action=getData`);
    const data = await response.json();

    return {
      transactions: data.transactions || [],
      employees: data.employees || [],
      tools: data.tools || []
    };
  } catch (error) {
    console.error("Failed to fetch sheet data:", error);
    return {
      transactions: INITIAL_TRANSACTIONS,
      employees: [],
      tools: []
    };
  }
};

export const saveTransactionToSheet = async (transaction: Transaction, userDetails?: any): Promise<boolean> => {
  if (!GOOGLE_SCRIPT_URL) {
    return Promise.resolve(true);
  }

  try {
    // We send explicit details to ensure the sheet columns are filled even if we just have an ID
    const payload = {
      action: 'addTransaction',
      payload: {
        ...transaction,
        employeeName: userDetails?.name || '',
        designation: userDetails?.designation || '',
        department: userDetails?.department || '',
        typeOfEmployee: userDetails?.typeOfEmployee || ''
      }
    };

    const response = await fetch(GOOGLE_SCRIPT_URL, {
      method: 'POST',
      headers: HEADERS,
      body: JSON.stringify(payload)
    });

    const result = await response.json();
    return result.status === 'success';

  } catch (error) {
    console.error("Failed to save transaction:", error);
    return false;
  }
};
