import React, { useState, useEffect } from 'react';
import { Transaction, EntryType } from '../types';
import { X, Calendar, User as UserIcon, Wrench } from 'lucide-react';

interface ToolModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (transaction: Transaction, employeeDetails?: any) => void;
  initialTransaction?: Transaction | null;
  employees: any[]; // These should be filtered by department in the parent
  availableTools: string[];
}

const ToolModal: React.FC<ToolModalProps> = ({ 
  isOpen, 
  onClose, 
  onSave, 
  initialTransaction, 
  employees = [], 
  availableTools = [] 
}) => {

  const [formData, setFormData] = useState<Partial<Transaction>>({
    date: new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: '2-digit' }).replace(/ /g, '-'),
    entryType: 'Distribute',
    quantity: 1,
    condition: 'New',
    remarks: ''
  });

  const entryTypes: EntryType[] = ['Distribute', 'Return', 'Faulty Return', 'Damage', 'Lost', 'Stock IN'];

  // When ID changes, find the employee details
  const selectedEmployee = employees.find(e => e.id === formData.employeeId);

  useEffect(() => {
    if (initialTransaction) {
      setFormData(initialTransaction);
    } else {
      setFormData({
        date: new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: '2-digit' }).replace(/ /g, '-'),
        entryType: 'Distribute',
        quantity: 1,
        condition: 'New',
        toolName: availableTools[0] || '',
        employeeId: '',
        remarks: ''
      });
    }
  }, [initialTransaction, isOpen, availableTools]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      id: initialTransaction?.id || Date.now().toString(),
      ...formData
    } as Transaction, selectedEmployee);
    onClose();
  };

  const isEmployeeRequired = formData.entryType !== 'Stock IN';

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-lg overflow-hidden flex flex-col max-h-[90vh]">
        <div className="bg-slate-900 p-4 flex justify-between items-center text-white shrink-0">
          <h2 className="text-sm font-bold tracking-widest uppercase">
            {initialTransaction ? 'Edit Log Entry' : 'Log New Transaction'}
          </h2>
          <button onClick={onClose} className="hover:bg-white/20 p-1 rounded transition-colors">
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="overflow-y-auto p-6">
          <form onSubmit={handleSubmit} className="space-y-4">

            <div className="grid grid-cols-2 gap-4">
               <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Entry Date</label>
                  <div className="relative">
                     <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                     <input
                      required
                      type="text"
                      className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm"
                      placeholder="12-May-2024"
                      value={formData.date}
                      onChange={e => setFormData({ ...formData, date: e.target.value })}
                    />
                  </div>
               </div>
               <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Transaction Type</label>
                  <select
                    className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none font-bold text-sm bg-slate-50"
                    value={formData.entryType}
                    onChange={e => setFormData({ ...formData, entryType: e.target.value as EntryType })}
                  >
                    {entryTypes.map(t => (
                      <option key={t} value={t}>{t}</option>
                    ))}
                  </select>
               </div>
            </div>

            {isEmployeeRequired && (
               <div className="space-y-3 p-3 bg-slate-50 rounded-lg border border-slate-200">
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Target Employee ID</label>
                    <div className="relative">
                       <UserIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                       <select
                          className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none bg-white font-semibold text-sm"
                          value={formData.employeeId}
