import { Transaction, User } from '../types';
import { GOOGLE_SCRIPT_URL, INITIAL_TRANSACTIONS, USERS, TOOL_CATALOG } from '../constants';

// Use a CORS-friendly content type for Google Apps Script
const HEADERS = {
  'Content-Type': 'text/plain;charset=utf-8', 
};

// Exporting fetchSheetData as required by App.tsx to load transactions, employees and tools
export const fetchSheetData = async (): Promise<{ transactions: Transaction[], employees: any[], tools: string[] }> => {
  if (!GOOGLE_SCRIPT_URL) {
    console.warn("No Google Script URL provided. Using mock data.");
    return { 
      transactions: INITIAL_TRANSACTIONS, 
      employees: USERS, 
      tools: TOOL_CATALOG.map(t => t.name) 
    };
  }

  try {
    const response = await fetch(`${GOOGLE_SCRIPT_URL}?action=getFullData`);
    const data = await response.json();
    return {
      transactions: data.transactions || [],
      employees: data.employees || [],
      tools: data.tools || []
    };
  } catch (error) {
    console.error("Failed to fetch sheet data:", error);
    return { 
      transactions: INITIAL_TRANSACTIONS, 
      employees: USERS, 
      tools: TOOL_CATALOG.map(t => t.name) 
    };
  }
};

export const saveTransactionToSheet = async (transaction: Transaction, user?: User): Promise<boolean> => {
  if (!GOOGLE_SCRIPT_URL) {
    console.warn("No Google Script URL provided. Saving locally only.");
    return Promise.resolve(true);
  }

  try {
    const payload = {
      action: 'addTransaction',
      payload: {
        ...transaction,
        // Enrich with user details if available, so G-Sheet columns fill up correctly
        employeeName: user?.name,
        designation: user?.designation,
        department: user?.department,
        typeOfEmployee: user?.typeOfEmployee
      }
    };

    const response = await fetch(GOOGLE_SCRIPT_URL, {
      method: 'POST',
      headers: HEADERS,
      body: JSON.stringify(payload)
    });

    const result = await response.json();
    return result.status === 'success';

  } catch (error) {
    console.error("Failed to save transaction:", error);
    return false;
  }
};

import { GoogleGenAI } from "@google/genai";
import { Tool } from '../types';

// Initializing the Google GenAI SDK with named parameter as required
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateInventoryAnalysis = async (
  query: string,
  inventory: Tool[]
): Promise<string> => {
  try {
    const inventoryContext = JSON.stringify(inventory, null, 2);

    const systemInstruction = `
      You are an expert Inventory Manager assistant for SARBS Communications Ltd.
      You have access to the current tools inventory data provided below.

      Your goal is to answer questions about the tools, suggest maintenance, identify trends (like high breakage rates), 
      and help track who has what.

      Data Context:
      ${inventoryContext}

      Rules:
      1. Be professional, concise, and helpful.
      2. If asked about a specific tool, refer to its ID and Serial Number.
      3. If asked for a summary, provide counts and status breakdowns.
      4. Use formatting (bullet points, bold text) to make the response readable.
    `;

    // Using gemini-3-flash-preview for general inventory analysis tasks
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: query,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.7,
      },
    });

    // Accessing .text property directly from GenerateContentResponse
    return response.text || "I couldn't generate a response. Please try again.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Sorry, I encountered an error while processing your request. Please check your API key.";
  }
};

