  doc.setTextColor(255, 255, 255);
  doc.setFontSize(20);
  doc.setFont("helvetica", "bold");
  doc.text("SARBS Communications Ltd.", 14, 20);

  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.text("Official Tools & Equipment Report", 14, 30);
  doc.text(`Report Date: ${new Date().toLocaleDateString('en-GB')}`, 150, 30);

  // Info Block
  doc.setTextColor(40, 40, 40);
  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.text("Personnel Information:", 14, 55);

  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.text(`Name: ${user.name}`, 14, 62);
  doc.text(`ID: ${user.id}`, 14, 67);
  doc.text(`Designation: ${user.designation || 'N/A'}`, 100, 62);
  doc.text(`Department: ${user.department || 'N/A'}`, 100, 67);

  // Table
  const tableRows = tools.map((tool) => [
    tool.name,
    tool.quantity || 1,
    tool.assignedDate || '-',
    tool.remarks || 'No remarks'
  ]);

  doc.autoTable({
    startY: 75,
    head: [['Tool Description', 'Qty', 'Date Logged', 'Administrative Remarks']],
    body: tableRows,
    theme: 'grid',
    headStyles: { fillColor: [15, 23, 42], textColor: [255, 255, 255], fontStyle: 'bold' },
    styles: { fontSize: 9, cellPadding: 3 },
    alternateRowStyles: { fillColor: [248, 250, 252] }
  });

  // Footer
  const pageCount = doc.internal.getNumberOfPages();
  for(let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text('This is an automatically generated inventory document.', 14, 285);
    doc.text('Page ' + i + ' of ' + pageCount, 190, 285, { align: 'right' });
  }

  doc.save(`SARBS_Report_${user.id}_${Date.now()}.pdf`);
};

