  Smartphone
} from 'lucide-react';
import { USERS, TOOL_CATALOG } from './constants';
import { User, Transaction } from './types';
import ToolModal from './components/ToolModal';
import AIChat from './components/AIChat';
import Login from './components/Login';
import EmployeeDashboard from './components/EmployeeDashboard';
import { fetchSheetData, saveTransactionToSheet } from './services/sheetService';
import { generateEmployeePDF } from './services/pdfService';

type Tab = 'employee' | 'daily' | 'stock' | 'admins';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [allTransactions, setAllTransactions] = useState<Transaction[]>([]);
  const [fullEmployeeDirectory, setFullEmployeeDirectory] = useState<any[]>([]);
  const [availableTools, setAvailableTools] = useState<string[]>([]);
  const [sheetAdmins, setSheetAdmins] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSync, setLastSync] = useState<string>('');
  const [activeTab, setActiveTab] = useState<Tab>('employee');
  const [employeeSearchId, setEmployeeSearchId] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [installPrompt, setInstallPrompt] = useState<any>(null);

  // --- Sync Logic ---

  const loadData = useCallback(async (isBackground = false) => {
    if (!isBackground) setIsLoading(true);
    else setIsSyncing(true);

    try {
      const data = await fetchSheetData();
      setAllTransactions(data.transactions);
      setFullEmployeeDirectory(data.employees);
      setAvailableTools(data.tools);
      setSheetAdmins(data.admins);
      setLastSync(new Date().toLocaleTimeString());
    } catch (e) {
      console.error("Error loading data", e);
    } finally {
      setIsLoading(false);
      setIsSyncing(false);
    }
  }, []);

  // --- PWA & Connectivity Listeners ---

  useEffect(() => {
    // 1. Connectivity
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    // 2. Auto-refresh on window focus (Ensures data is fresh when user returns)
    const handleFocus = () => loadData(true);
    window.addEventListener('focus', handleFocus);

    // 3. PWA Install Prompt
    const handleInstallPrompt = (e: any) => {
      e.preventDefault();
      setInstallPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handleInstallPrompt);

    loadData();

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      window.removeEventListener('focus', handleFocus);
      window.removeEventListener('beforeinstallprompt', handleInstallPrompt);
    };
  }, [loadData]);

  const handleInstallClick = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') setInstallPrompt(null);
  };

  // --- Permissions-Aware Data ---

  const visibleEmployees = useMemo(() => {
    if (!user) return [];
    if (user.role === 'super_admin') return fullEmployeeDirectory;
    return fullEmployeeDirectory.filter(emp => emp.department === user.department);
  }, [user, fullEmployeeDirectory]);

  const visibleTransactions = useMemo(() => {
    if (!user) return [];
    if (user.role === 'super_admin') return allTransactions;
    return allTransactions.filter(trx => 
      trx.department === user.department || trx.entryType === 'Stock IN'
    );
  }, [user, allTransactions]);

  // --- Actions ---

  const handleSaveTransaction = async (trx: Transaction, employeeDetails?: any) => {
    const newTransactions = editingTransaction 
      ? allTransactions.map(t => t.id === trx.id ? trx : t) 
      : [...allTransactions, trx];

    setAllTransactions(newTransactions);
    setEditingTransaction(null);

    const success = await saveTransactionToSheet(trx, employeeDetails);
    if (!success) {
      alert("Note: Data saved locally but failed to sync to Google Sheet. Check internet.");
    } else {
      loadData(true); // Re-sync after save
    }
  };

  const handleLogin = (u: { id: string, password?: string }) => {
    const sheetAdmin = sheetAdmins.find(admin => admin.id === u.id && admin.password === u.password);
    if (sheetAdmin) {
      setUser(sheetAdmin);
      return;
    }

    const sheetEmp = fullEmployeeDirectory.find(e => e.id === u.id);
    if (sheetEmp && u.password === '12345') {
      setUser({
        id: sheetEmp.id,
        name: sheetEmp.name,
        role: 'employee',
        designation: sheetEmp.designation,
        department: sheetEmp.department,
        typeOfEmployee: sheetEmp.typeOfEmployee
      });
      return;
    }

    const found = USERS.find(existing => existing.id === u.id && existing.password === u.password);
    if (found) {
      setUser(found);
      return;
    }

    alert("Invalid ID or Password.");
  };

  // --- Calculations ---

  const selectedEmployeeResult = useMemo(() => {
    if (!employeeSearchId) return null;
    return visibleEmployees.find(e => e.id === employeeSearchId);
  }, [employeeSearchId, visibleEmployees]);

  const employeeToolsData = useMemo(() => {
    if (!selectedEmployeeResult) return [];
    const empTrx = visibleTransactions.filter(t => t.employeeId === selectedEmployeeResult.id);
    const toolsMap = new Map<string, any>();

    availableTools.forEach(name => {
       toolsMap.set(name, { name, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0, remarks: '' });
    });

    empTrx.forEach(t => {
      let tool = toolsMap.get(t.toolName);
      if (!tool) {
         tool = { name: t.toolName, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0, remarks: '' };
         toolsMap.set(t.toolName, tool);
      }
      if (t.entryType === 'Distribute') tool.distributed += t.quantity;
      if (t.entryType === 'Return') tool.returned += t.quantity;
      if (t.entryType === 'Faulty Return') tool.faulty += t.quantity;
      if (t.entryType === 'Damage') tool.damage += t.quantity;
      if (t.entryType === 'Lost') tool.lost += t.quantity;
      if (t.remarks) tool.remarks = t.remarks;
    });

    return Array.from(toolsMap.values()).filter(t => t.distributed > 0);
  }, [selectedEmployeeResult, visibleTransactions, availableTools]);

  const stockSummaryData = useMemo(() => {
    const allNames = Array.from(new Set([...TOOL_CATALOG.map(c => c.name), ...availableTools])).sort();
    return allNames.map(name => {
      const toolTrx = visibleTransactions.filter(t => t.toolName === name);
      let purchase = 0, distributed = 0, returned = 0, faulty = 0, damage = 0, lost = 0;
      toolTrx.forEach(t => {
        if (t.entryType === 'Stock IN') purchase += t.quantity;
        if (t.entryType === 'Distribute') distributed += t.quantity;
        if (t.entryType === 'Return') returned += t.quantity;
        if (t.entryType === 'Faulty Return') faulty += t.quantity;
        if (t.entryType === 'Damage') damage += t.quantity;
        if (t.entryType === 'Lost') lost += t.quantity;
      });
      return {
        name, purchase, distributed, returned, faulty, damage, lost,
        stockNow: purchase - distributed + returned
      };
    });
  }, [visibleTransactions, availableTools]);

  // --- Render ---

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-900 flex flex-col items-center justify-center gap-6 p-10">
        <div className="relative">
          <Loader2 className="w-16 h-16 text-blue-500 animate-spin" />
          <Package className="w-6 h-6 text-white absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />
        </div>
        <div className="text-center">
           <p className="text-white font-bold text-lg tracking-tight">SARBS Inventory Hub</p>
           <p className="text-slate-400 text-sm mt-1">Connecting to Cloud Sheet...</p>
        </div>
      </div>
    );
  }

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  if (user.role === 'employee') {
    const myTools = visibleTransactions.filter(t => t.employeeId === user.id && t.entryType === 'Distribute').map(t => ({
      id: t.id, name: t.toolName, brand: 'Generic', serialNumber: `SN-${t.id.substring(0, 8)}`,
      status: 'In Use', quantity: t.quantity, assignedDate: t.date, remarks: t.remarks
    }));
    return <EmployeeDashboard user={user} tools={myTools} onLogout={() => setUser(null)} />;
  }

  return (
    <div className="min-h-screen bg-slate-100 font-sans text-slate-900 pb-20 safe-top">

      {/* Top Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <img src="https://ui-avatars.com/api/?name=SARBS&background=0D9488&color=fff" className="w-8 h-8 rounded" alt="Logo" />
            <div className="hidden xs:block">
               <h1 className="text-sm sm:text-lg font-black text-slate-800 leading-tight">SARBS Communications</h1>
               <div className="flex items-center gap-2">
                 <span className={`text-[8px] sm:text-[10px] px-1.5 rounded flex items-center gap-1 font-bold ${isOnline ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                   {isOnline ? <Wifi className="w-2.5 h-2.5" /> : <WifiOff className="w-2.5 h-2.5" />}
                   {isOnline ? 'ONLINE' : 'OFFLINE'}
                 </span>
                 <span className="text-[9px] text-slate-400 font-bold uppercase">Sync: {lastSync}</span>
               </div>
            </div>
          </div>

          <div className="flex items-center gap-2 sm:gap-4">
             {installPrompt && (
               <button 
                onClick={handleInstallClick}
                className="hidden md:flex items-center gap-1.5 bg-blue-600 text-white px-3 py-1.5 rounded-full text-[10px] font-bold shadow-md hover:bg-blue-700 transition-all"
               >
                 <Smartphone className="w-3 h-3" /> Install App
               </button>
             )}

             <button 
               onClick={() => loadData(true)} 
               disabled={isSyncing}
               className={`p-2 text-slate-400 hover:text-blue-600 transition-colors ${isSyncing ? 'animate-spin text-blue-500' : ''}`} 
               title="Force Sync"
             >
               <RefreshCw className="w-5 h-5" />
             </button>

             <div className="flex items-center gap-2 bg-slate-50 border border-slate-200 px-3 py-1.5 rounded-full">
                {user.role === 'super_admin' ? (
                  <ShieldCheck className="w-4 h-4 text-indigo-600" />
                ) : (
                  <Building2 className="w-4 h-4 text-amber-600" />
                )}
                <div className="text-left hidden sm:block">
                  <div className="text-xs font-bold text-slate-800 leading-none">{user.name}</div>
                  <div className={`text-[9px] font-bold uppercase tracking-tighter mt-0.5 ${user.role === 'super_admin' ? 'text-indigo-600' : 'text-amber-600'}`}>
                    {user.role === 'super_admin' ? 'Super Admin' : `${user.department} Admin`}
                  </div>
                </div>
             </div>

             <button onClick={() => setUser(null)} className="p-2 text-slate-400 hover:text-red-600 transition-colors">
               <LogOut className="w-5 h-5" />
             </button>
          </div>
        </div>

        {/* Navigation Tabs */}
        <div className="max-w-7xl mx-auto px-4 mt-2 flex gap-1 overflow-x-auto no-scrollbar pb-1">
           <button 
             onClick={() => setActiveTab('employee')}
             className={`px-4 py-3 text-sm font-bold border-b-2 transition-colors flex items-center gap-2 whitespace-nowrap ${activeTab === 'employee' ? 'border-blue-600 text-blue-600 bg-blue-50' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
           >
             <Users className="w-4 h-4" /> Team
           </button>
           <button 
             onClick={() => setActiveTab('daily')}
             className={`px-4 py-3 text-sm font-bold border-b-2 transition-colors flex items-center gap-2 whitespace-nowrap ${activeTab === 'daily' ? 'border-amber-500 text-amber-700 bg-amber-50' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
           >
             <FileSpreadsheet className="w-4 h-4" /> Daily Log
           </button>
           <button 
             onClick={() => setActiveTab('stock')}
             className={`px-4 py-3 text-sm font-bold border-b-2 transition-colors flex items-center gap-2 whitespace-nowrap ${activeTab === 'stock' ? 'border-cyan-500 text-cyan-700 bg-cyan-50' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
           >
             <Package className="w-4 h-4" /> Stock
           </button>
           {user.role === 'super_admin' && (
             <button 
               onClick={() => setActiveTab('admins')}
               className={`px-4 py-3 text-sm font-bold border-b-2 transition-colors flex items-center gap-2 whitespace-nowrap ${activeTab === 'admins' ? 'border-indigo-600 text-indigo-700 bg-indigo-50' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
             >
               <ShieldCheck className="w-4 h-4" /> Admin Access
             </button>
           )}
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-6">

        {/* VIEW 1: Team Summary */}
        {activeTab === 'employee' && (
          <div className="space-y-6">
             <div className="bg-white p-6 rounded-lg shadow-sm border border-slate-200">
                <div className="flex items-end gap-4 max-w-xl">
                   <div className="flex-1">
                      <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Search Employee</label>
                      <div className="relative">
                         <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                         <input 
                           type="text" 
                           className="w-full pl-9 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                           placeholder="Enter Employee ID..."
                           value={employeeSearchId}
                           onChange={e => setEmployeeSearchId(e.target.value)}
                         />
                      </div>
                   </div>
                </div>
             </div>

             {selectedEmployeeResult ? (
               <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500">
                  <div className="grid grid-cols-2 md:grid-cols-5 gap-px bg-slate-100 border-b border-slate-200">
                     <div className="bg-white p-4">
                        <p className="text-[10px] text-slate-400 font-bold uppercase">Name</p>
                        <p className="font-bold text-slate-800 text-sm truncate">{selectedEmployeeResult.name}</p>
                     </div>
                     <div className="bg-white p-4">
                        <p className="text-[10px] text-slate-400 font-bold uppercase">Designation</p>
                        <p className="font-medium text-slate-600 text-sm truncate">{selectedEmployeeResult.designation}</p>
                     </div>
                     <div className="bg-white p-4">
                        <p className="text-[10px] text-slate-400 font-bold uppercase">Dept</p>
                        <p className="font-medium text-slate-600 text-sm">{selectedEmployeeResult.department}</p>
                     </div>
                     <div className="bg-white p-4">
                        <p className="text-[10px] text-slate-400 font-bold uppercase">Type</p>
                        <span className="inline-block px-2 py-0.5 rounded text-[10px] font-black bg-green-100 text-green-700">{selectedEmployeeResult.typeOfEmployee}</span>
                     </div>
                     <div className="bg-white p-4 flex items-center justify-center">
                        <button 
                           onClick={() => generateEmployeePDF(selectedEmployeeResult, employeeToolsData.map(t => ({
                             name: t.name,
                             quantity: t.distributed - t.returned - t.lost,
                             assignedDate: '-',
                             remarks: t.remarks
                           })))}
                           className="flex items-center gap-2 text-blue-600 hover:bg-blue-600 hover:text-white px-3 py-2 rounded-lg transition-all text-xs font-bold border border-blue-100"
                        >
                           <Download className="w-3.5 h-3.5" /> PDF Report
                        </button>
                     </div>
                  </div>

                  <div className="overflow-x-auto">
                    <table className="w-full text-xs text-center">
                      <thead>
                        <tr className="bg-slate-50 border-b border-slate-200 text-slate-500 uppercase">
                          <th className="px-4 py-3 font-black text-left w-1/4">Tool Model</th>
                          <th className="px-4 py-3 font-bold border-l border-slate-200">Dist.</th>
                          <th className="px-4 py-3 font-bold border-l border-slate-200">Ret.</th>
                          <th className="px-4 py-3 font-bold border-l border-slate-200 text-amber-600">Flt.</th>
                          <th className="px-4 py-3 font-bold border-l border-slate-200 text-red-500">Lost</th>
                          <th className="px-4 py-3 font-black border-l border-slate-200 bg-green-50 text-green-800">BAL</th>
                          <th className="px-4 py-3 font-bold border-l border-slate-200 text-left">Remarks</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {employeeToolsData.map((row) => (
                          <tr key={row.name} className="hover:bg-slate-50 transition-colors">
                            <td className="px-4 py-3 text-left font-bold text-slate-800">{row.name}</td>
                            <td className="px-4 py-3 border-l border-slate-100">{row.distributed || ''}</td>
                            <td className="px-4 py-3 border-l border-slate-100">{row.returned || ''}</td>
                            <td className="px-4 py-3 border-l border-slate-100 text-amber-600">{row.faulty || ''}</td>
                            <td className="px-4 py-3 border-l border-slate-100 text-red-600">{row.lost || ''}</td>
                            <td className="px-4 py-3 border-l border-slate-100 font-black bg-green-50 text-green-700 text-sm">
                              {(row.distributed - row.returned - row.lost)}
                            </td>
                            <td className="px-4 py-3 border-l border-slate-100 text-left text-slate-400 italic max-w-xs truncate">{row.remarks}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
               </div>
             ) : (
                <div className="text-center py-24 bg-white rounded-2xl border-2 border-dashed border-slate-200">
                   <Users className="w-16 h-16 text-slate-200 mx-auto mb-4" />
                   <p className="text-slate-400 font-bold uppercase tracking-widest text-xs">Enter ID to view department assets</p>
                </div>
             )}
          </div>
        )}

        {/* VIEW 2: Daily Log */}
        {activeTab === 'daily' && (
           <div className="space-y-4">
              <div className="flex justify-between items-center bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
                 <div>
                    <h2 className="text-sm font-black text-slate-800 uppercase tracking-tight">Activity Stream</h2>
                    <p className="text-[10px] text-slate-400 font-bold uppercase">{user.department} - Realtime Logs</p>
                 </div>
                 <button 
                   onClick={() => setIsModalOpen(true)}
                   className="flex items-center gap-2 bg-slate-900 hover:bg-black text-white px-5 py-2.5 rounded-xl shadow-lg font-black text-xs transition-all active:scale-95"
                 >
                   <Plus className="w-4 h-4" /> New Log
                 </button>
              </div>

              <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                 <div className="overflow-x-auto">
                    <table className="w-full text-[11px] text-left">
                       <thead className="bg-slate-50 text-slate-500 border-b border-slate-200">
                          <tr>
                             <th className="px-4 py-4 font-black uppercase">Date</th>
                             <th className="px-4 py-4 font-black uppercase">Employee</th>
                             <th className="px-4 py-4 font-black uppercase">Tool Name</th>
                             <th className="px-4 py-4 font-black uppercase text-center">Action</th>
                             <th className="px-4 py-4 font-black uppercase text-center">Qty</th>
                             <th className="px-4 py-4 font-black uppercase">Notes</th>
                          </tr>
                       </thead>
                       <tbody className="divide-y divide-slate-100">
                          {[...visibleTransactions].reverse().map((trx) => (
                             <tr key={trx.id} className="hover:bg-slate-50 transition-colors group">
                                <td className="px-4 py-3 font-mono text-[10px] text-slate-500">{trx.date}</td>
                                <td className="px-4 py-3 font-bold text-slate-800">{trx.employeeName || 'In-Stock'}</td>
                                <td className="px-4 py-3 font-medium">{trx.toolName}</td>
                                <td className="px-4 py-3 text-center">
                                   <span className={`px-2 py-1 rounded-md text-[9px] font-black uppercase tracking-tighter
                                     ${trx.entryType === 'Distribute' ? 'bg-green-100 text-green-700' : 
                                       trx.entryType === 'Return' ? 'bg-blue-100 text-blue-700' :
                                       trx.entryType === 'Stock IN' ? 'bg-indigo-100 text-indigo-700' :
                                       'bg-red-100 text-red-700'}`}>
                                      {trx.entryType}
                                   </span>
                                </td>
                                <td className="px-4 py-3 text-center font-black text-slate-900">{trx.quantity}</td>
                                <td className="px-4 py-3 text-slate-400 italic truncate max-w-[150px]">{trx.remarks}</td>
                             </tr>
                          ))}
                       </tbody>
                    </table>
                 </div>
              </div>
           </div>
        )}

        {/* VIEW 3: Stock Summary */}
        {activeTab === 'stock' && (
           <div className="space-y-4">
              <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
                 <h2 className="text-sm font-black text-slate-800 uppercase tracking-tight">Main Inventory Ledger</h2>
                 <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Master Count across all departments</p>
              </div>

              <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                 <div className="overflow-x-auto">
                    <table className="w-full text-xs text-center">
                       <thead className="bg-slate-50 text-slate-500 border-b border-slate-200 uppercase">
                          <tr>
                             <th className="px-4 py-4 font-black text-left w-1/4">Catalog Model</th>
                             <th className="px-4 py-4 font-black border-l border-slate-200">Inward</th>
                             <th className="px-4 py-4 font-black border-l border-slate-200">Out</th>
                             <th className="px-4 py-4 font-black border-l border-slate-200">Returned</th>
                             <th className="px-4 py-4 font-black border-l border-slate-200 text-red-500">Damage</th>
                             <th className="px-4 py-4 font-black border-l border-slate-200 bg-slate-900 text-white">Stock Net</th>
                          </tr>
                       </thead>
                       <tbody className="divide-y divide-slate-100">
                          {stockSummaryData.map((row) => (
                             <tr key={row.name} className="hover:bg-slate-50 transition-colors">
                                <td className="px-4 py-4 text-left font-bold text-slate-900">{row.name}</td>
                                <td className="px-4 py-4 border-l border-slate-100 font-medium">{row.purchase}</td>
                                <td className="px-4 py-4 border-l border-slate-100 font-medium">{row.distributed}</td>
                                <td className="px-4 py-4 border-l border-slate-100 font-medium">{row.returned}</td>
                                <td className="px-4 py-4 border-l border-slate-100 text-red-500">{row.damage}</td>
                                <td className="px-4 py-4 border-l border-slate-100 font-black bg-slate-50 text-base text-slate-900">
                                   {row.stockNow}
                                </td>
                             </tr>
                          ))}
                       </tbody>
                    </table>
                 </div>
              </div>
           </div>
        )}

        {/* VIEW 4: Admin Access */}
        {activeTab === 'admins' && user.role === 'super_admin' && (
           <div className="space-y-4 animate-in fade-in duration-700">
              <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex flex-col sm:flex-row justify-between items-center gap-4">
                 <div>
                    <h2 className="text-lg font-black text-slate-900 flex items-center gap-2">
                      <Lock className="w-6 h-6 text-indigo-600" /> Admin Access Controls
                    </h2>
                    <p className="text-xs text-slate-500 mt-1 font-medium">
                      Manage these credentials in the <span className="text-indigo-600 font-bold">"Admins"</span> tab of your Google Sheet.
                    </p>
                 </div>
                 <div className="flex items-center gap-3">
                    <div className="flex flex-col items-end">
                      <div className="flex items-center gap-2 text-[10px] font-black text-green-600 bg-green-50 px-3 py-2 rounded-full border border-green-100">
                         <RefreshCw className={`w-3 h-3 ${isSyncing ? 'animate-spin' : ''}`} />
                         CLOUD SYNC ACTIVE
                      </div>
                      <span className="text-[9px] text-slate-400 mt-1 uppercase font-bold tracking-tighter">Synced: {lastSync}</span>
                    </div>
                 </div>
              </div>

              <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                 <table className="w-full text-xs text-left">
                    <thead className="bg-slate-50 text-slate-500 border-b border-slate-200 uppercase">
                       <tr>
                          <th className="px-6 py-5 font-black">ID</th>
                          <th className="px-6 py-5 font-black">Admin Name</th>
                          <th className="px-6 py-5 font-black">Role</th>
                          <th className="px-6 py-5 font-black">Dept</th>
                          <th className="px-6 py-5 font-black">Title</th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                       {sheetAdmins.map((admin) => (
                          <tr key={admin.id} className="hover:bg-indigo-50/50 transition-colors">
                             <td className="px-6 py-4 font-mono font-bold text-slate-500">{admin.id}</td>
                             <td className="px-6 py-4 font-black text-slate-900">{admin.name}</td>
                             <td className="px-6 py-4">
                                <span className={`px-2 py-1 rounded-md text-[9px] font-black uppercase border shadow-sm ${admin.role === 'super_admin' ? 'bg-indigo-600 text-white border-indigo-700' : 'bg-white text-amber-600 border-amber-200'}`}>
                                   {admin.role.replace('_', ' ')}
                                </span>
                             </td>
                             <td className="px-6 py-4 text-slate-600 font-bold">{admin.department}</td>
                             <td className="px-6 py-4">
                                <div className="flex items-center gap-1.5 text-slate-500 font-bold">
                                   <UserCheck className="w-4 h-4 text-green-500" />
                                   <span>{admin.designation || 'Specialist'}</span>
                                </div>
                             </td>
                          </tr>
                       ))}
                    </tbody>
                 </table>
              </div>
           </div>
        )}

      </main>

      {/* Shared Modals */}
      <ToolModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveTransaction}
        initialTransaction={editingTransaction}
        employees={visibleEmployees}
        availableTools={availableTools}
      />

      <AIChat inventory={stockSummaryData} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { 
  LogOut, 
  Search, 
  Plus, 
  FileSpreadsheet, 
  Users, 
  Package, 
  Loader2,
  RefreshCw,
  Download,
  ShieldCheck,
  Building2,
  Lock,
  UserCheck,
  Clock,
  Wifi,
  WifiOff,
  Smartphone,
  CloudSync,
  AlertTriangle
} from 'lucide-react';
import { USERS, TOOL_CATALOG } from './constants';
import { User, Transaction } from './types';
import ToolModal from './components/ToolModal';
import AIChat from './components/AIChat';
import Login from './components/Login';
import EmployeeDashboard from './components/EmployeeDashboard';
import { fetchSheetData, saveTransactionToSheet } from './services/sheetService';
import { generateEmployeePDF } from './services/pdfService';

type Tab = 'employee' | 'daily' | 'stock' | 'admins';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [allTransactions, setAllTransactions] = useState<Transaction[]>([]);
  const [fullEmployeeDirectory, setFullEmployeeDirectory] = useState<any[]>([]);
  const [availableTools, setAvailableTools] = useState<string[]>([]);
  const [sheetAdmins, setSheetAdmins] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSync, setLastSync] = useState<string>('');
  const [activeTab, setActiveTab] = useState<Tab>('employee');
  const [employeeSearchId, setEmployeeSearchId] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [installPrompt, setInstallPrompt] = useState<any>(null);

  // --- Sync Logic ---

  const loadData = useCallback(async (isBackground = false) => {
    if (!isBackground) setIsLoading(true);
    else setIsSyncing(true);

    try {
      const data = await fetchSheetData();
      setAllTransactions(data.transactions);
      setFullEmployeeDirectory(data.employees);
      setAvailableTools(data.tools);
      setSheetAdmins(data.admins);
      setLastSync(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    } catch (e) {
      console.error("Error loading data", e);
    } finally {
      setIsLoading(false);
      // Brief delay for the syncing UI to be noticeable but not annoying
      setTimeout(() => setIsSyncing(false), 800);
    }
  }, []);

  // --- PWA & Connectivity Listeners ---

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const handleFocus = () => {
      if (navigator.onLine) loadData(true);
    };
    window.addEventListener('focus', handleFocus);

    const handleInstallPrompt = (e: any) => {
      e.preventDefault();
      setInstallPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handleInstallPrompt);

    loadData();

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      window.removeEventListener('focus', handleFocus);
      window.removeEventListener('beforeinstallprompt', handleInstallPrompt);
    };
  }, [loadData]);

  const handleInstallClick = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') setInstallPrompt(null);
  };

  // --- Permissions-Aware Data ---

  const visibleEmployees = useMemo(() => {
    if (!user) return [];
    if (user.role === 'super_admin') return fullEmployeeDirectory;
    return fullEmployeeDirectory.filter(emp => emp.department === user.department);
  }, [user, fullEmployeeDirectory]);

  const visibleTransactions = useMemo(() => {
    if (!user) return [];
    if (user.role === 'super_admin') return allTransactions;
    return allTransactions.filter(trx => 
      trx.department === user.department || trx.entryType === 'Stock IN'
    );
  }, [user, allTransactions]);

  // --- Actions ---

  const handleSaveTransaction = async (trx: Transaction, employeeDetails?: any) => {
    const newTransactions = editingTransaction 
      ? allTransactions.map(t => t.id === trx.id ? trx : t) 
      : [...allTransactions, trx];

    setAllTransactions(newTransactions);
    setEditingTransaction(null);

    const success = await saveTransactionToSheet(trx, employeeDetails);
    if (!success) {
      alert("Note: Data saved locally but failed to sync to Google Sheet. Check internet.");
    } else {
      loadData(true);
    }
  };

  const handleLogin = (u: { id: string, password?: string }) => {
    const sheetAdmin = sheetAdmins.find(admin => admin.id === u.id && admin.password === u.password);
    if (sheetAdmin) {
      setUser(sheetAdmin);
      return;
    }

    const sheetEmp = fullEmployeeDirectory.find(e => e.id === u.id);
    if (sheetEmp && u.password === '12345') {
      setUser({
        id: sheetEmp.id,
        name: sheetEmp.name,
        role: 'employee',
        designation: sheetEmp.designation,
        department: sheetEmp.department,
        typeOfEmployee: sheetEmp.typeOfEmployee
      });
      return;
    }

    const found = USERS.find(existing => existing.id === u.id && existing.password === u.password);
    if (found) {
      setUser(found);
      return;
    }

    alert("Invalid ID or Password. Make sure your G-Sheet Admin tab is up to date.");
  };

  const selectedEmployeeResult = useMemo(() => {
    if (!employeeSearchId) return null;
    return visibleEmployees.find(e => e.id === employeeSearchId);
  }, [employeeSearchId, visibleEmployees]);

  const employeeToolsData = useMemo(() => {
    if (!selectedEmployeeResult) return [];
    const empTrx = visibleTransactions.filter(t => t.employeeId === selectedEmployeeResult.id);
    const toolsMap = new Map<string, any>();

    availableTools.forEach(name => {
       toolsMap.set(name, { name, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0, remarks: '' });
    });

    empTrx.forEach(t => {
      let tool = toolsMap.get(t.toolName);
      if (!tool) {
         tool = { name: t.toolName, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0, remarks: '' };
         toolsMap.set(t.toolName, tool);
      }
      if (t.entryType === 'Distribute') tool.distributed += t.quantity;
      if (t.entryType === 'Return') tool.returned += t.quantity;
      if (t.entryType === 'Faulty Return') tool.faulty += t.quantity;
      if (t.entryType === 'Damage') tool.damage += t.quantity;
      if (t.entryType === 'Lost') tool.lost += t.quantity;
      if (t.remarks) tool.remarks = t.remarks;
    });

    return Array.from(toolsMap.values()).filter(t => t.distributed > 0);
  }, [selectedEmployeeResult, visibleTransactions, availableTools]);

  const stockSummaryData = useMemo(() => {
    const allNames = Array.from(new Set([...TOOL_CATALOG.map(c => c.name), ...availableTools])).sort();
    return allNames.map(name => {
      const toolTrx = visibleTransactions.filter(t => t.toolName === name);
      let purchase = 0, distributed = 0, returned = 0, faulty = 0, damage = 0, lost = 0;
      toolTrx.forEach(t => {
        if (t.entryType === 'Stock IN') purchase += t.quantity;
        if (t.entryType === 'Distribute') distributed += t.quantity;
        if (t.entryType === 'Return') returned += t.quantity;
        if (t.entryType === 'Faulty Return') faulty += t.quantity;
        if (t.entryType === 'Damage') damage += t.quantity;
        if (t.entryType === 'Lost') lost += t.quantity;
      });
      return {
        name, purchase, distributed, returned, faulty, damage, lost,
        stockNow: purchase - distributed + returned
      };
    });
  }, [visibleTransactions, availableTools]);

  // --- Render ---

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-900 flex flex-col items-center justify-center gap-6 p-10">
        <div className="relative">
          <Loader2 className="w-16 h-16 text-blue-500 animate-spin" />
          <Package className="w-6 h-6 text-white absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />
        </div>
        <div className="text-center">
           <p className="text-white font-bold text-lg tracking-tight">SARBS Inventory Hub</p>
           <p className="text-slate-400 text-sm mt-1">Syncing with Google Sheets...</p>
        </div>
      </div>
    );
  }

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  if (user.role === 'employee') {
    const myTools = visibleTransactions.filter(t => t.employeeId === user.id && t.entryType === 'Distribute').map(t => ({
      id: t.id, name: t.toolName, brand: 'Generic', serialNumber: `SN-${t.id.substring(0, 8)}`,
      status: 'In Use', quantity: t.quantity, assignedDate: t.date, remarks: t.remarks
    }));
    return <EmployeeDashboard user={user} tools={myTools} onLogout={() => setUser(null)} />;
  }

  return (
    <div className="min-h-screen bg-slate-100 font-sans text-slate-900 pb-20 safe-top">

      {/* Offline Alert Banner */}
      {!isOnline && (
        <div className="bg-red-600 text-white text-[10px] font-black uppercase tracking-widest py-2 text-center flex items-center justify-center gap-2 animate-pulse">
          <WifiOff className="w-3 h-3" /> Offline Mode - Changes will sync later
        </div>
      )}

      {/* Top Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-slate-900 p-1.5 rounded-lg">
              <Package className="w-5 h-5 text-white" />
            </div>
            <div className="hidden xs:block">
               <h1 className="text-sm sm:text-lg font-black text-slate-900 leading-tight">SARBS Admin</h1>
               <div className="flex items-center gap-2">
                 <span className={`text-[8px] px-1.5 rounded flex items-center gap-1 font-bold ${isOnline ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                   {isOnline ? <Wifi className="w-2.5 h-2.5" /> : <WifiOff className="w-2.5 h-2.5" />}
                   {isOnline ? 'LIVE' : 'DISCONNECTED'}
                 </span>
                 <span className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter">Updated: {lastSync}</span>
               </div>
            </div>
          </div>

          <div className="flex items-center gap-2 sm:gap-4">
             {installPrompt && (
               <button 
                onClick={handleInstallClick}
                className="hidden md:flex items-center gap-1.5 bg-blue-600 text-white px-4 py-2 rounded-full text-[10px] font-black shadow-lg hover:bg-blue-700 transition-all active:scale-95"
               >
                 <Smartphone className="w-3.5 h-3.5" /> INSTALL APP
               </button>
             )}

             <button 
               onClick={() => loadData(true)} 
               disabled={isSyncing}
               className={`p-2.5 rounded-full bg-slate-50 border border-slate-200 text-slate-400 hover:text-blue-600 transition-all shadow-sm ${isSyncing ? 'animate-spin text-blue-500 ring-2 ring-blue-100' : ''}`} 
               title="Sync Now"
             >
               <RefreshCw className="w-4 h-4" />
             </button>

             <div className="flex items-center gap-2 bg-slate-900 px-3 py-1.5 rounded-full shadow-md">
                {user.role === 'super_admin' ? (
                  <ShieldCheck className="w-4 h-4 text-blue-400" />
                ) : (
                  <Building2 className="w-4 h-4 text-amber-400" />
                )}
                <div className="text-left hidden sm:block">
                  <div className="text-[10px] font-bold text-white leading-none truncate max-w-[80px]">{user.name}</div>
                  <div className={`text-[8px] font-black uppercase tracking-tighter mt-0.5 ${user.role === 'super_admin' ? 'text-blue-400' : 'text-amber-400'}`}>
                    {user.role === 'super_admin' ? 'Super Admin' : `${user.department}`}
                  </div>
                </div>
             </div>

             <button onClick={() => setUser(null)} className="p-2 text-slate-400 hover:text-red-600 transition-colors">
               <LogOut className="w-5 h-5" />
             </button>
          </div>
        </div>

        {/* Navigation Tabs */}
        <div className="max-w-7xl mx-auto px-4 mt-2 flex gap-1 overflow-x-auto no-scrollbar pb-1">
           {[
             { id: 'employee', label: 'Team', icon: Users },
             { id: 'daily', label: 'Logs', icon: FileSpreadsheet },
             { id: 'stock', label: 'Inventory', icon: Package },
             ...(user.role === 'super_admin' ? [{ id: 'admins', label: 'Access', icon: ShieldCheck }] : [])
           ].map((tab) => (
             <button 
               key={tab.id}
               onClick={() => setActiveTab(tab.id as Tab)}
               className={`px-5 py-3 text-xs font-black border-b-2 transition-all flex items-center gap-2 whitespace-nowrap uppercase tracking-widest ${activeTab === tab.id ? 'border-slate-900 text-slate-900 bg-white shadow-sm' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
             >
               <tab.icon className="w-4 h-4" /> {tab.label}
             </button>
           ))}
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-6">

        {/* VIEW 1: Team Summary */}
        {activeTab === 'employee' && (
          <div className="space-y-6">
             <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
                <div className="flex flex-col sm:flex-row items-end gap-4">
                   <div className="w-full sm:max-w-md">
                      <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Search Employee Database</label>
                      <div className="relative group">
                         <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300 group-focus-within:text-blue-500 transition-colors" />
                         <input 
                           type="text" 
                           className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-4 focus:ring-blue-50 focus:border-blue-500 outline-none text-sm font-bold transition-all"
                           placeholder="Enter Employee ID (e.g. 11001)"
                           value={employeeSearchId}
                           onChange={e => setEmployeeSearchId(e.target.value)}
                         />
                      </div>
                   </div>
                </div>
             </div>

             {selectedEmployeeResult ? (
               <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500">
                  <div className="grid grid-cols-2 md:grid-cols-5 gap-px bg-slate-100 border-b border-slate-200">
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Full Name</p>
                        <p className="font-black text-slate-900 text-sm truncate">{selectedEmployeeResult.name}</p>
                     </div>
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Position</p>
                        <p className="font-bold text-slate-600 text-sm truncate">{selectedEmployeeResult.designation}</p>
                     </div>
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Business Unit</p>
                        <p className="font-bold text-slate-600 text-sm">{selectedEmployeeResult.department}</p>
                     </div>
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Contract Status</p>
                        <span className="inline-block px-2 py-0.5 rounded text-[10px] font-black bg-green-50 text-green-600 border border-green-100 uppercase">{selectedEmployeeResult.typeOfEmployee}</span>
                     </div>
                     <div className="bg-white p-5 flex items-center justify-center">
                        <button 
                           onClick={() => generateEmployeePDF(selectedEmployeeResult, employeeToolsData.map(t => ({
                             name: t.name,
                             quantity: t.distributed - t.returned - t.lost,
                             assignedDate: '-',
                             remarks: t.remarks
                           })))}
                           className="flex items-center gap-2 text-slate-900 bg-slate-50 hover:bg-slate-900 hover:text-white px-4 py-2.5 rounded-xl transition-all text-xs font-black border border-slate-200 shadow-sm"
                        >
                           <Download className="w-4 h-4" /> EXPORT PDF
                        </button>
                     </div>
                  </div>

                  <div className="overflow-x-auto">
                    <table className="w-full text-xs text-center">
                      <thead>
                        <tr className="bg-slate-50 border-b border-slate-200 text-slate-400 uppercase tracking-widest font-black">
                          <th className="px-6 py-4 text-left w-1/4">Tool Description</th>
                          <th className="px-4 py-4 border-l border-slate-100">Out</th>
                          <th className="px-4 py-4 border-l border-slate-100">In</th>
                          <th className="px-4 py-4 border-l border-slate-100 text-amber-500">Faulty</th>
                          <th className="px-4 py-4 border-l border-slate-100 text-red-600">Lost</th>
                          <th className="px-6 py-4 border-l border-slate-100 bg-green-50 text-green-900">NET BAL</th>
                          <th className="px-6 py-4 border-l border-slate-100 text-left">Latest Update</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {employeeToolsData.map((row) => (
                          <tr key={row.name} className="hover:bg-slate-50 transition-colors">
                            <td className="px-6 py-4 text-left font-black text-slate-800">{row.name}</td>
                            <td className="px-4 py-4 border-l border-slate-100 font-medium text-slate-400">{row.distributed || ''}</td>
                            <td className="px-4 py-4 border-l border-slate-100 font-medium text-slate-400">{row.returned || ''}</td>
                            <td className="px-4 py-4 border-l border-slate-100 font-bold text-amber-500">{row.faulty || ''}</td>
                            <td className="px-4 py-4 border-l border-slate-100 font-bold text-red-600">{row.lost || ''}</td>
                            <td className="px-6 py-4 border-l border-slate-100 font-black bg-green-50 text-green-700 text-base">
                              {(row.distributed - row.returned - row.lost)}
                            </td>
                            <td className="px-6 py-4 border-l border-slate-100 text-left text-slate-400 italic max-w-xs truncate">{row.remarks}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
               </div>
             ) : (
                <div className="text-center py-32 bg-white rounded-3xl border-4 border-dashed border-slate-100 flex flex-col items-center">
                   <div className="bg-slate-50 p-6 rounded-full mb-4">
                     <Users className="w-16 h-16 text-slate-200" />
                   </div>
                   <p className="text-slate-900 font-black uppercase tracking-widest text-sm">Personnel Lookup Required</p>
                   <p className="text-slate-400 text-xs mt-2 max-w-[250px]">Enter an employee ID above to view equipment assignment history.</p>
                </div>
             )}
          </div>
        )}

        {/* VIEW 2: Daily Log */}
        {activeTab === 'daily' && (
           <div className="space-y-4">
              <div className="flex justify-between items-center bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                 <div>
                    <h2 className="text-base font-black text-slate-900 uppercase tracking-tight">Stream: Logged Activity</h2>
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">{user.department} Operations</p>
                 </div>
                 <button 
                   onClick={() => setIsModalOpen(true)}
                   className="flex items-center gap-2 bg-slate-900 hover:bg-blue-600 text-white px-6 py-3 rounded-xl shadow-xl font-black text-xs transition-all active:scale-95"
                 >
                   <Plus className="w-5 h-5" /> COMMIT ENTRY
                 </button>
              </div>

              <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
                 <div className="overflow-x-auto">
                    <table className="w-full text-[11px] text-left">
                       <thead className="bg-slate-50 text-slate-500 border-b border-slate-200">
                          <tr className="uppercase font-black tracking-tighter">
                             <th className="px-6 py-5">Timestamp</th>
                             <th className="px-6 py-5">Target Personnel</th>
                             <th className="px-6 py-5">Material Description</th>
                             <th className="px-6 py-5 text-center">Protocol</th>
                             <th className="px-6 py-5 text-center">Unit</th>
                             <th className="px-6 py-5">Observation Notes</th>
                          </tr>
                       </thead>
                       <tbody className="divide-y divide-slate-100">
                          {[...visibleTransactions].reverse().map((trx) => (
                             <tr key={trx.id} className="hover:bg-slate-50 transition-colors group">
                                <td className="px-6 py-4 font-mono text-[10px] text-slate-400">{trx.date}</td>
                                <td className="px-6 py-4 font-black text-slate-900">{trx.employeeName || 'INTERNAL_STOCK'}</td>
                                <td className="px-6 py-4 font-bold text-slate-600">{trx.toolName}</td>
                                <td className="px-6 py-4 text-center">
                                   <span className={`px-2.5 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-tighter border shadow-sm
                                     ${trx.entryType === 'Distribute' ? 'bg-green-500 text-white border-green-600' : 
                                       trx.entryType === 'Return' ? 'bg-blue-500 text-white border-blue-600' :
                                       trx.entryType === 'Stock IN' ? 'bg-indigo-600 text-white border-indigo-700' :
                                       'bg-red-600 text-white border-red-700'}`}>
                                      {trx.entryType}
                                   </span>
                                </td>
                                <td className="px-6 py-4 text-center font-black text-slate-900 text-sm">{trx.quantity}</td>
                                <td className="px-6 py-4 text-slate-400 italic font-medium truncate max-w-[200px]">{trx.remarks}</td>
                             </tr>
                          ))}
                       </tbody>
                    </table>
                 </div>
              </div>
           </div>
        )}

        {/* VIEW 3: Stock Summary */}
        {activeTab === 'stock' && (
           <div className="space-y-4">
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                 <h2 className="text-base font-black text-slate-900 uppercase tracking-tight">Consolidated Asset Ledger</h2>
                 <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Master Unit Reconciliation</p>
              </div>

              <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
                 <div className="overflow-x-auto">
                    <table className="w-full text-xs text-center">
                       <thead className="bg-slate-50 text-slate-500 border-b border-slate-200 uppercase font-black tracking-widest">
                          <tr>
                             <th className="px-6 py-5 text-left w-1/4">Equipment Model</th>
                             <th className="px-4 py-5 border-l border-slate-100">Total In</th>
                             <th className="px-4 py-5 border-l border-slate-100">Total Out</th>
                             <th className="px-4 py-5 border-l border-slate-100">Ret. Clean</th>
                             <th className="px-4 py-5 border-l border-slate-100 text-red-500">Lost/Dam.</th>
                             <th className="px-6 py-5 border-l border-slate-100 bg-slate-900 text-white">READY STOCK</th>
                          </tr>
                       </thead>
                       <tbody className="divide-y divide-slate-100">
                          {stockSummaryData.map((row) => (
                             <tr key={row.name} className="hover:bg-slate-50 transition-colors">
                                <td className="px-6 py-5 text-left font-black text-slate-900">{row.name}</td>
                                <td className="px-4 py-5 border-l border-slate-100 font-bold text-slate-400">{row.purchase}</td>
                                <td className="px-4 py-5 border-l border-slate-100 font-bold text-slate-400">{row.distributed}</td>
                                <td className="px-4 py-5 border-l border-slate-100 font-bold text-slate-400">{row.returned}</td>
                                <td className="px-4 py-5 border-l border-slate-100 text-red-500 font-bold">{row.damage + row.lost}</td>
                                <td className="px-6 py-5 border-l border-slate-100 font-black bg-slate-50 text-xl text-slate-900">
                                   {row.stockNow}
                                </td>
                             </tr>
                          ))}
                       </tbody>
                    </table>
                 </div>
              </div>
           </div>
        )}

        {/* VIEW 4: Admin Access */}
        {activeTab === 'admins' && user.role === 'super_admin' && (
           <div className="space-y-4 animate-in fade-in duration-700">
              <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm flex flex-col sm:flex-row justify-between items-center gap-6">
                 <div>
                    <h2 className="text-xl font-black text-slate-900 flex items-center gap-3">
                      <Lock className="w-8 h-8 text-indigo-600" /> Administrative Hierarchy
                    </h2>
                    <p className="text-xs text-slate-500 mt-2 font-bold max-w-sm">
                      Syncing with the <span className="text-indigo-600 font-black italic">"Admins"</span> tab. Update your G-Sheet to add/remove access.
                    </p>
                 </div>
                 <div className="flex items-center gap-4">
                    <div className="flex flex-col items-end">
                      <div className={`flex items-center gap-2 text-[10px] font-black px-4 py-2 rounded-full border transition-all ${isSyncing ? 'bg-blue-600 text-white border-blue-700' : 'bg-green-50 text-green-600 border-green-200'}`}>
                         <RefreshCw className={`w-3.5 h-3.5 ${isSyncing ? 'animate-spin' : ''}`} />
                         {isSyncing ? 'REFRESHING DATABASE...' : 'SYSTEMS ONLINE'}
                      </div>
                      <span className="text-[10px] text-slate-400 mt-2 uppercase font-black tracking-tighter">Last Verification: {lastSync}</span>
                    </div>
                 </div>
              </div>

              <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
                 <table className="w-full text-xs text-left">
                    <thead className="bg-slate-50 text-slate-400 border-b border-slate-200 uppercase font-black tracking-widest">
                       <tr>
                          <th className="px-8 py-6">Identity ID</th>
                          <th className="px-8 py-6">Full Name</th>
                          <th className="px-8 py-6">Access Role</th>
                          <th className="px-8 py-6">Managed Department</th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                       {sheetAdmins.map((admin) => (
                          <tr key={admin.id} className="hover:bg-indigo-50/50 transition-colors">
                             <td className="px-8 py-5 font-mono font-black text-slate-500">{admin.id}</td>
                             <td className="px-8 py-5 font-black text-slate-900 text-sm">{admin.name}</td>
                             <td className="px-8 py-5">
                                <span className={`px-3 py-1.5 rounded-xl text-[10px] font-black uppercase border shadow-sm ${admin.role === 'super_admin' ? 'bg-indigo-900 text-white border-indigo-950' : 'bg-white text-amber-600 border-amber-200'}`}>
                                   {admin.role.replace('_', ' ')}
                                </span>
                             </td>
                             <td className="px-8 py-5 text-slate-600 font-black uppercase text-[10px] tracking-widest">{admin.department}</td>
                          </tr>
                       ))}
                    </tbody>
                 </table>
              </div>
           </div>
        )}

      </main>

      {/* Syncing Global Notification Overlay */}
      {isSyncing && (
        <div className="fixed bottom-24 left-6 z-50 flex items-center gap-3 bg-slate-900 text-white px-5 py-3 rounded-2xl shadow-2xl animate-in slide-in-from-left-10 duration-300">
          <CloudSync className="w-5 h-5 text-blue-400 animate-pulse" />
          <div className="flex flex-col">
            <span className="text-[10px] font-black uppercase tracking-widest">Syncing Cloud</span>
            <span className="text-[9px] text-slate-400 font-bold">Connecting to Google Sheet Hub...</span>
          </div>
        </div>
      )}

      {/* Shared Modals */}
      <ToolModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveTransaction}
        initialTransaction={editingTransaction}
        employees={visibleEmployees}
        availableTools={availableTools}
      />

      <AIChat inventory={stockSummaryData} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { 
  LogOut, 
  Search, 
  Plus, 
  FileSpreadsheet, 
  Users, 
  Package, 
  Loader2,
  RefreshCw,
  Download,
  ShieldCheck,
  Building2,
  Lock,
  UserCheck,
  Clock,
  Wifi,
  WifiOff,
  Smartphone,
  AlertTriangle
} from 'lucide-react';
import { USERS, TOOL_CATALOG } from './constants';
import { User, Transaction } from './types';
import ToolModal from './components/ToolModal';
import AIChat from './components/AIChat';
import Login from './components/Login';
import EmployeeDashboard from './components/EmployeeDashboard';
import { fetchSheetData, saveTransactionToSheet } from './services/sheetService';
import { generateEmployeePDF } from './services/pdfService';

type Tab = 'employee' | 'daily' | 'stock' | 'admins';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [allTransactions, setAllTransactions] = useState<Transaction[]>([]);
  const [fullEmployeeDirectory, setFullEmployeeDirectory] = useState<any[]>([]);
  const [availableTools, setAvailableTools] = useState<string[]>([]);
  const [sheetAdmins, setSheetAdmins] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSync, setLastSync] = useState<string>('');
  const [activeTab, setActiveTab] = useState<Tab>('employee');
  const [employeeSearchId, setEmployeeSearchId] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [installPrompt, setInstallPrompt] = useState<any>(null);

  // --- Sync Logic ---

  const loadData = useCallback(async (isBackground = false) => {
    if (!isBackground) setIsLoading(true);
    else setIsSyncing(true);

    try {
      const data = await fetchSheetData();
      setAllTransactions(data.transactions);
      setFullEmployeeDirectory(data.employees);
      setAvailableTools(data.tools);
      setSheetAdmins(data.admins);
      setLastSync(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    } catch (e) {
      console.error("Error loading data", e);
    } finally {
      setIsLoading(false);
      // Brief delay for the syncing UI to be noticeable
      setTimeout(() => setIsSyncing(false), 1000);
    }
  }, []);

  // --- PWA & Connectivity Listeners ---

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const handleFocus = () => {
      if (navigator.onLine) loadData(true);
    };
    window.addEventListener('focus', handleFocus);

    const handleInstallPrompt = (e: any) => {
      e.preventDefault();
      setInstallPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handleInstallPrompt);

    loadData();

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      window.removeEventListener('focus', handleFocus);
      window.removeEventListener('beforeinstallprompt', handleInstallPrompt);
    };
  }, [loadData]);

  const handleInstallClick = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') setInstallPrompt(null);
  };

  // --- Permissions-Aware Data ---

  const visibleEmployees = useMemo(() => {
    if (!user) return [];
    if (user.role === 'super_admin') return fullEmployeeDirectory;
    return fullEmployeeDirectory.filter(emp => emp.department === user.department);
  }, [user, fullEmployeeDirectory]);

  const visibleTransactions = useMemo(() => {
    if (!user) return [];
    if (user.role === 'super_admin') return allTransactions;
    return allTransactions.filter(trx => 
      trx.department === user.department || trx.entryType === 'Stock IN'
    );
  }, [user, allTransactions]);

  // --- Actions ---

  const handleSaveTransaction = async (trx: Transaction, employeeDetails?: any) => {
    const newTransactions = editingTransaction 
      ? allTransactions.map(t => t.id === trx.id ? trx : t) 
      : [...allTransactions, trx];

    setAllTransactions(newTransactions);
    setEditingTransaction(null);

    const success = await saveTransactionToSheet(trx, employeeDetails);
    if (!success) {
      alert("Note: Data saved locally but failed to sync to Google Sheet. Check internet.");
    } else {
      loadData(true);
    }
  };

  const handleLogin = (u: { id: string, password?: string }) => {
    const sheetAdmin = sheetAdmins.find(admin => admin.id === u.id && admin.password === u.password);
    if (sheetAdmin) {
      setUser(sheetAdmin);
      return;
    }

    const sheetEmp = fullEmployeeDirectory.find(e => e.id === u.id);
    if (sheetEmp && u.password === '12345') {
      setUser({
        id: sheetEmp.id,
        name: sheetEmp.name,
        role: 'employee',
        designation: sheetEmp.designation,
        department: sheetEmp.department,
        typeOfEmployee: sheetEmp.typeOfEmployee
      });
      return;
    }

    const found = USERS.find(existing => existing.id === u.id && existing.password === u.password);
    if (found) {
      setUser(found);
      return;
    }

    alert("Invalid ID or Password. Make sure your G-Sheet Admin tab is up to date.");
  };

  const selectedEmployeeResult = useMemo(() => {
    if (!employeeSearchId) return null;
    return visibleEmployees.find(e => e.id === employeeSearchId);
  }, [employeeSearchId, visibleEmployees]);

  const employeeToolsData = useMemo(() => {
    if (!selectedEmployeeResult) return [];
    const empTrx = visibleTransactions.filter(t => t.employeeId === selectedEmployeeResult.id);
    const toolsMap = new Map<string, any>();

    availableTools.forEach(name => {
       toolsMap.set(name, { name, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0, remarks: '' });
    });

    empTrx.forEach(t => {
      let tool = toolsMap.get(t.toolName);
      if (!tool) {
         tool = { name: t.toolName, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0, remarks: '' };
         toolsMap.set(t.toolName, tool);
      }
      if (t.entryType === 'Distribute') tool.distributed += t.quantity;
      if (t.entryType === 'Return') tool.returned += t.quantity;
      if (t.entryType === 'Faulty Return') tool.faulty += t.quantity;
      if (t.entryType === 'Damage') tool.damage += t.quantity;
      if (t.entryType === 'Lost') tool.lost += t.quantity;
      if (t.remarks) tool.remarks = t.remarks;
    });

    return Array.from(toolsMap.values()).filter(t => t.distributed > 0);
  }, [selectedEmployeeResult, visibleTransactions, availableTools]);

  const stockSummaryData = useMemo(() => {
    const allNames = Array.from(new Set([...TOOL_CATALOG.map(c => c.name), ...availableTools])).sort();
    return allNames.map(name => {
      const toolTrx = visibleTransactions.filter(t => t.toolName === name);
      let purchase = 0, distributed = 0, returned = 0, faulty = 0, damage = 0, lost = 0;
      toolTrx.forEach(t => {
        if (t.entryType === 'Stock IN') purchase += t.quantity;
        if (t.entryType === 'Distribute') distributed += t.quantity;
        if (t.entryType === 'Return') returned += t.quantity;
        if (t.entryType === 'Faulty Return') faulty += t.quantity;
        if (t.entryType === 'Damage') damage += t.quantity;
        if (t.entryType === 'Lost') lost += t.quantity;
      });
      return {
        name, purchase, distributed, returned, faulty, damage, lost,
        stockNow: purchase - distributed + returned
      };
    });
  }, [visibleTransactions, availableTools]);

  // --- Render ---

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-900 flex flex-col items-center justify-center gap-6 p-10">
        <div className="relative">
          <Loader2 className="w-16 h-16 text-blue-500 animate-spin" />
          <Package className="w-6 h-6 text-white absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />
        </div>
        <div className="text-center">
           <p className="text-white font-bold text-lg tracking-tight">SARBS Inventory Hub</p>
           <p className="text-slate-400 text-sm mt-1">Syncing with Google Sheets...</p>
        </div>
      </div>
    );
  }

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  if (user.role === 'employee') {
    const myTools = visibleTransactions.filter(t => t.employeeId === user.id && t.entryType === 'Distribute').map(t => ({
      id: t.id, name: t.toolName, brand: 'Generic', serialNumber: `SN-${t.id.substring(0, 8)}`,
      status: 'In Use', quantity: t.quantity, assignedDate: t.date, remarks: t.remarks
    }));
    return <EmployeeDashboard user={user} tools={myTools} onLogout={() => setUser(null)} />;
  }

  return (
    <div className="min-h-screen bg-slate-100 font-sans text-slate-900 pb-20 safe-top">

      {/* Offline Alert Banner */}
      {!isOnline && (
        <div className="bg-red-600 text-white text-[10px] font-black uppercase tracking-widest py-2 text-center flex items-center justify-center gap-2 animate-pulse sticky top-0 z-50">
          <WifiOff className="w-3 h-3" /> Offline Mode - Changes will sync later
        </div>
      )}

      {/* Top Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-slate-900 p-1.5 rounded-lg">
              <Package className="w-5 h-5 text-white" />
            </div>
            <div className="hidden xs:block">
               <h1 className="text-sm sm:text-lg font-black text-slate-900 leading-tight">SARBS Admin</h1>
               <div className="flex items-center gap-2">
                 <span className={`text-[8px] px-1.5 rounded flex items-center gap-1 font-bold ${isOnline ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                   {isOnline ? <Wifi className="w-2.5 h-2.5" /> : <WifiOff className="w-2.5 h-2.5" />}
                   {isOnline ? 'LIVE' : 'DISCONNECTED'}
                 </span>
                 <span className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter">Updated: {lastSync}</span>
               </div>
            </div>
          </div>

          <div className="flex items-center gap-2 sm:gap-4">
             {installPrompt && (
               <button 
                onClick={handleInstallClick}
                className="hidden md:flex items-center gap-1.5 bg-blue-600 text-white px-4 py-2 rounded-full text-[10px] font-black shadow-lg hover:bg-blue-700 transition-all active:scale-95"
               >
                 <Smartphone className="w-3.5 h-3.5" /> INSTALL APP
               </button>
             )}

             <button 
               onClick={() => loadData(true)} 
               disabled={isSyncing}
               className={`p-2.5 rounded-full bg-slate-50 border border-slate-200 text-slate-400 hover:text-blue-600 transition-all shadow-sm ${isSyncing ? 'animate-spin text-blue-500 ring-2 ring-blue-100' : ''}`} 
               title="Sync Now"
             >
               <RefreshCw className="w-4 h-4" />
             </button>

             <div className="flex items-center gap-2 bg-slate-900 px-3 py-1.5 rounded-full shadow-md">
                {user.role === 'super_admin' ? (
                  <ShieldCheck className="w-4 h-4 text-blue-400" />
                ) : (
                  <Building2 className="w-4 h-4 text-amber-400" />
                )}
                <div className="text-left hidden sm:block">
                  <div className="text-[10px] font-bold text-white leading-none truncate max-w-[80px]">{user.name}</div>
                  <div className={`text-[8px] font-black uppercase tracking-tighter mt-0.5 ${user.role === 'super_admin' ? 'text-blue-400' : 'text-amber-400'}`}>
                    {user.role === 'super_admin' ? 'Super Admin' : `${user.department}`}
                  </div>
                </div>
             </div>

             <button onClick={() => setUser(null)} className="p-2 text-slate-400 hover:text-red-600 transition-colors">
               <LogOut className="w-5 h-5" />
             </button>
          </div>
        </div>

        {/* Navigation Tabs */}
        <div className="max-w-7xl mx-auto px-4 mt-2 flex gap-1 overflow-x-auto no-scrollbar pb-1">
           {[
             { id: 'employee', label: 'Team', icon: Users },
             { id: 'daily', label: 'Logs', icon: FileSpreadsheet },
             { id: 'stock', label: 'Inventory', icon: Package },
             ...(user.role === 'super_admin' ? [{ id: 'admins', label: 'Access', icon: ShieldCheck }] : [])
           ].map((tab) => (
             <button 
               key={tab.id}
               onClick={() => setActiveTab(tab.id as Tab)}
               className={`px-5 py-3 text-xs font-black border-b-2 transition-all flex items-center gap-2 whitespace-nowrap uppercase tracking-widest ${activeTab === tab.id ? 'border-slate-900 text-slate-900 bg-white shadow-sm' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
             >
               <tab.icon className="w-4 h-4" /> {tab.label}
             </button>
           ))}
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-6">

        {/* VIEW 1: Team Summary */}
        {activeTab === 'employee' && (
          <div className="space-y-6">
             <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
                <div className="flex flex-col sm:flex-row items-end gap-4">
                   <div className="w-full sm:max-w-md">
                      <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Search Employee Database</label>
                      <div className="relative group">
                         <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300 group-focus-within:text-blue-500 transition-colors" />
                         <input 
                           type="text" 
                           className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-4 focus:ring-blue-50 focus:border-blue-500 outline-none text-sm font-bold transition-all"
                           placeholder="Enter Employee ID (e.g. 11001)"
                           value={employeeSearchId}
                           onChange={e => setEmployeeSearchId(e.target.value)}
                         />
                      </div>
                   </div>
                </div>
             </div>

             {selectedEmployeeResult ? (
               <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500">
                  <div className="grid grid-cols-2 md:grid-cols-5 gap-px bg-slate-100 border-b border-slate-200">
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Full Name</p>
                        <p className="font-black text-slate-900 text-sm truncate">{selectedEmployeeResult.name}</p>
                     </div>
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Position</p>
                        <p className="font-bold text-slate-600 text-sm truncate">{selectedEmployeeResult.designation}</p>
                     </div>
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Business Unit</p>
                        <p className="font-bold text-slate-600 text-sm">{selectedEmployeeResult.department}</p>
                     </div>
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Contract Status</p>
                        <span className="inline-block px-2 py-0.5 rounded text-[10px] font-black bg-green-50 text-green-600 border border-green-100 uppercase">{selectedEmployeeResult.typeOfEmployee}</span>
                     </div>
                     <div className="bg-white p-5 flex items-center justify-center">
                        <button 
                           onClick={() => generateEmployeePDF(selectedEmployeeResult, employeeToolsData.map(t => ({
                             name: t.name,
                             quantity: t.distributed - t.returned - t.lost,
                             assignedDate: '-',
                             remarks: t.remarks
                           })))}
                           className="flex items-center gap-2 text-slate-900 bg-slate-50 hover:bg-slate-900 hover:text-white px-4 py-2.5 rounded-xl transition-all text-xs font-black border border-slate-200 shadow-sm"
                        >
                           <Download className="w-4 h-4" /> EXPORT PDF
                        </button>
                     </div>
                  </div>

                  <div className="overflow-x-auto">
                    <table className="w-full text-xs text-center">
                      <thead>
                        <tr className="bg-slate-50 border-b border-slate-200 text-slate-400 uppercase tracking-widest font-black">
                          <th className="px-6 py-4 text-left w-1/4">Tool Description</th>
                          <th className="px-4 py-4 border-l border-slate-100">Out</th>
