                   className="flex items-center gap-2 bg-slate-900 hover:bg-blue-600 text-white px-6 py-3 rounded-xl shadow-xl font-black text-xs transition-all active:scale-95"
                 >
                   <Plus className="w-5 h-5" /> COMMIT ENTRY
                 </button>
              </div>

              <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
                 <div className="overflow-x-auto">
                    <table className="w-full text-[11px] text-left">
                       <thead className="bg-slate-50 text-slate-500 border-b border-slate-200">
                          <tr className="uppercase font-black tracking-tighter">
                             <th className="px-6 py-5">Timestamp</th>
                             <th className="px-6 py-5">Target Personnel</th>
                             <th className="px-6 py-5">Material Description</th>
                             <th className="px-6 py-5 text-center">Protocol</th>
                             <th className="px-6 py-5 text-center">Unit</th>
                             <th className="px-6 py-5">Observation Notes</th>
                          </tr>
                       </thead>
                       <tbody className="divide-y divide-slate-100">
                          {[...visibleTransactions].reverse().map((trx) => (
                             <tr key={trx.id} className="hover:bg-slate-50 transition-colors group">
                                <td className="px-6 py-4 font-mono text-[10px] text-slate-400">{trx.date}</td>
