                 <div className="flex items-center gap-4">
                    <div className="flex flex-col items-end">
                      <div className={`flex items-center gap-2 text-[10px] font-black px-4 py-2 rounded-full border transition-all ${isSyncing ? 'bg-blue-600 text-white border-blue-700' : 'bg-green-50 text-green-600 border-green-200'}`}>
                         <RefreshCw className={`w-3.5 h-3.5 ${isSyncing ? 'animate-spin' : ''}`} />
                         {isSyncing ? 'REFRESHING DATABASE...' : 'SYSTEMS ONLINE'}
                      </div>
                      <span className="text-[10px] text-slate-400 mt-2 uppercase font-black tracking-tighter">Last Verification: {lastSync}</span>
                    </div>
                 </div>
              </div>

              <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
                 <table className="w-full text-xs text-left">
                    <thead className="bg-slate-50 text-slate-400 border-b border-slate-200 uppercase font-black tracking-widest">
                       <tr>
                          <th className="px-8 py-6">Identity ID</th>
                          <th className="px-8 py-6">Full Name</th>
                          <th className="px-8 py-6">Access Role</th>
                          <th className="px-8 py-6">Managed Department</th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                       {sheetAdmins.map((admin) => (
                          <tr key={admin.id} className="hover:bg-indigo-50/50 transition-colors">
                             <td className="px-8 py-5 font-mono font-black text-slate-500">{admin.id}</td>
                             <td className="px-8 py-5 font-black text-slate-900 text-sm">{admin.name}</td>
                             <td className="px-8 py-5">
                                <span className={`px-3 py-1.5 rounded-xl text-[10px] font-black uppercase border shadow-sm ${admin.role === 'super_admin' ? 'bg-indigo-900 text-white border-indigo-950' : 'bg-white text-amber-600 border-amber-200'}`}>
                                   {admin.role.replace('_', ' ')}
                                </span>
                             </td>
                             <td className="px-8 py-5 text-slate-600 font-black uppercase text-[10px] tracking-widest">{admin.department}</td>
                          </tr>
                       ))}
                    </tbody>
                 </table>
              </div>
           </div>
        )}

      </main>

      {isSyncing && (
        <div className="fixed bottom-24 left-6 z-50 flex items-center gap-3 bg-slate-900 text-white px-5 py-3 rounded-2xl shadow-2xl animate-in slide-in-from-left-10 duration-300">
          <RefreshCw className="w-5 h-5 text-blue-400 animate-spin" />
          <div className="flex flex-col">
            <span className="text-[10px] font-black uppercase tracking-widest">Cloud Sync Active</span>
            <span className="text-[9px] text-slate-400 font-bold">Downloading from SARBS Hub...</span>
          </div>
        </div>
      )}

      <ToolModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveTransaction}
        initialTransaction={editingTransaction}
        employees={visibleEmployees}
        availableTools={availableTools}
      />

      <AIChat inventory={stockSummaryData} />
    </div>
  );
};

export default App;

