          <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500/10 rounded-full -mr-16 -mt-16 blur-2xl"></div>
          <div className="absolute bottom-0 left-0 w-24 h-24 bg-indigo-500/10 rounded-full -ml-12 -mb-12 blur-xl"></div>

          <div className="relative z-10">
            <div className="inline-flex p-1 bg-white rounded-2xl mb-4 shadow-lg border border-white/20">
              <img src={LOGO_URL} alt="SARBS Logo" className="w-20 h-20 object-contain rounded-xl" />
            </div>
            <h1 className="text-2xl font-black text-white mb-1 uppercase tracking-tight">SARBS Communications</h1>
            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Inventory Management System</p>
          </div>
        </div>

        {/* Sync Status Bar */}
        <div className="bg-slate-50 border-b border-slate-100 px-6 py-3 flex items-center justify-between">
          <div className="flex items-center gap-2">
            {isOnline ? (
              <span className="flex items-center gap-1 text-[10px] font-black text-green-600 bg-green-100 px-2 py-0.5 rounded-full">
                <Wifi className="w-2.5 h-2.5" /> ONLINE
              </span>
            ) : (
              <span className="flex items-center gap-1 text-[10px] font-black text-red-600 bg-red-100 px-2 py-0.5 rounded-full">
                <WifiOff className="w-2.5 h-2.5" /> OFFLINE
              </span>
            )}
            <span className="text-[10px] text-slate-400 font-bold uppercase">Sync: {lastSync || 'Never'}</span>
          </div>

          <div className="flex items-center gap-2">
            {showSuccess && !isSyncing && (
              <span className="flex items-center gap-1 text-[9px] font-black text-blue-600 animate-bounce">
