                  type="text"
                  required
                  className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-50 focus:border-blue-500 outline-none transition-all font-bold text-slate-800"
                  placeholder="ID from Admins tab"
                  value={id}
                  onChange={(e) => setId(e.target.value)}
                />
              </div>
            </div>

            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Security Password</label>
              <div className="relative group">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-300 group-focus-within:text-blue-500 transition-colors" />
                <input 
                  type="password"
                  required
                  className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-50 focus:border-blue-500 outline-none transition-all font-bold text-slate-800"
                  placeholder="••••••••"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
              </div>
              <p className="mt-2 text-[9px] text-slate-400 font-bold italic">
                {isSyncing ? 'Refreshing credentials...' : 'Note: Updates in G-Sheet require clicking "Refresh Cloud".'}
              </p>
            </div>

            <button 
              type="submit"
              disabled={isSyncing}
              className={`w-full py-4 font-black rounded-2xl shadow-xl transition-all active:scale-[0.97] uppercase tracking-widest text-xs ${isSyncing ? 'bg-slate-400 cursor-not-allowed' : 'bg-slate-900 hover:bg-black text-white shadow-slate-200'}`}
            >
              {isSyncing ? 'Syncing...' : 'Secure Login'}
            </button>
          </form>

          {/* App Installation Prompt */}
          {installPrompt && (
            <button 
              onClick={onInstall}
              className="w-full mt-4 py-3 bg-blue-50 hover:bg-blue-100 text-blue-600 border border-blue-200 font-black rounded-2xl transition-all flex items-center justify-center gap-2 text-[10px] uppercase tracking-widest"
            >
              <Smartphone className="w-4 h-4" /> Install to Home Screen
            </button>
          )}

          <div className="mt-8 pt-6 border-t border-slate-100 text-center">
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter">
              Authorized Access Only <br/>
              <span className="text-slate-300">© 2024 SARBS Communications Ltd.</span>
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { 
  LogOut, 
  Search, 
  Plus, 
  FileSpreadsheet, 
  Users, 
  Package, 
  Loader2,
  RefreshCw,
  Download,
  ShieldCheck,
  Building2,
  Lock,
  UserCheck,
  Clock,
  Wifi,
  WifiOff,
  Smartphone,
  AlertTriangle
} from 'lucide-react';
import { USERS, TOOL_CATALOG, LOGO_URL } from './constants';
import { User, Transaction, UserRole } from './types';
import ToolModal from './components/ToolModal';
import AIChat from './components/AIChat';
import Login from './components/Login';
import EmployeeDashboard from './components/EmployeeDashboard';
import { fetchSheetData, saveTransactionToSheet } from './services/sheetService';
import { generateEmployeePDF } from './services/pdfService';

type Tab = 'employee' | 'daily' | 'stock' | 'admins';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [allTransactions, setAllTransactions] = useState<Transaction[]>([]);
  const [fullEmployeeDirectory, setFullEmployeeDirectory] = useState<any[]>([]);
  const [availableTools, setAvailableTools] = useState<string[]>([]);
  const [sheetAdmins, setSheetAdmins] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSync, setLastSync] = useState<string>('');
  const [activeTab, setActiveTab] = useState<Tab>('employee');
  const [employeeSearchId, setEmployeeSearchId] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [installPrompt, setInstallPrompt] = useState<any>(null);

  // --- Sync Logic ---

  const loadData = useCallback(async (isBackground = false) => {
    if (!isBackground) setIsLoading(true);
    else setIsSyncing(true);

    try {
      const data = await fetchSheetData();
      setAllTransactions(data.transactions);
      setFullEmployeeDirectory(data.employees);
      setAvailableTools(data.tools);
      setSheetAdmins(data.admins);
      setLastSync(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));

      console.log(`[Cloud Sync] Found ${data.admins.length} admins in G-Sheet.`);
    } catch (e) {
      console.error("Error loading data", e);
    } finally {
      setIsLoading(false);
      setTimeout(() => setIsSyncing(false), 800);
    }
  }, []);

  // --- PWA & Connectivity Listeners ---

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const handleFocus = () => {
      if (navigator.onLine) loadData(true);
    };
    window.addEventListener('focus', handleFocus);

    const handleInstallPrompt = (e: any) => {
      e.preventDefault();
      setInstallPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handleInstallPrompt);

    loadData();

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      window.removeEventListener('focus', handleFocus);
      window.removeEventListener('beforeinstallprompt', handleInstallPrompt);
    };
  }, [loadData]);

  const handleInstallClick = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') setInstallPrompt(null);
  };

  // --- ACCESS CONTROLLED DATA ---

  const isSuperAdmin = useMemo(() => {
    if (!user) return false;
    // Handle both "super_admin" and "Super Admin" role names from the sheet
    const normalizedRole = user.role.toLowerCase().replace(/[\s_]/g, '');
    return normalizedRole === 'superadmin';
  }, [user]);

  const visibleEmployees = useMemo(() => {
    if (!user) return [];
    if (isSuperAdmin) return fullEmployeeDirectory;
    // Dept Admins only see employees belonging to their department
    return fullEmployeeDirectory.filter(emp => emp.department === user.department);
  }, [user, isSuperAdmin, fullEmployeeDirectory]);

  const visibleTransactions = useMemo(() => {
    if (!user) return [];
    if (isSuperAdmin) return allTransactions;
    // Dept Admins only see transactions stamped with their department
    return allTransactions.filter(trx => trx.department === user.department);
  }, [user, isSuperAdmin, allTransactions]);

  // --- Actions ---

  const handleSaveTransaction = async (trx: Transaction, employeeDetails?: any) => {
    if (!user) return;

    // IMPORTANT: Inject the current Admin's department for Stock IN transactions
    // and use the Employee's department for distributions/returns.
    const enrichedTrx = { ...trx };
    if (trx.entryType === 'Stock IN') {
      // Stock added by this admin belongs to their department
      enrichedTrx.department = user.department;
    } else if (employeeDetails) {
      // Transactions with employees are tied to that employee's department
      enrichedTrx.department = employeeDetails.department;
    } else {
      // Fallback
      enrichedTrx.department = user.department;
    }

    const newTransactions = editingTransaction 
      ? allTransactions.map(t => t.id === enrichedTrx.id ? enrichedTrx : t) 
      : [...allTransactions, enrichedTrx];

    setAllTransactions(newTransactions);
    setEditingTransaction(null);

    const success = await saveTransactionToSheet(enrichedTrx, employeeDetails || { department: user.department });
    if (!success) {
      alert("Note: Data saved locally but failed to sync to Google Sheet. Check internet.");
    } else {
      loadData(true);
    }
  };

  const handleLogin = (u: { id: string, password?: string }) => {
    const inputId = String(u.id || '').trim();
    const inputPass = String(u.password || '').trim();

    if (!inputId) {
      alert("Please enter a valid Personnel ID.");
      return;
    }

    // Dynamic Admin Login from G-Sheet "Admins" Tab
    const sheetAdmin = sheetAdmins.find(admin => 
      String(admin.id).trim() === inputId && 
      String(admin.password).trim() === inputPass
    );

    if (sheetAdmin) {
      // Standardize role to internal slug but keep display info
      const rawRole = sheetAdmin.role.toLowerCase().replace(/[\s_]/g, '');
      const internalRole: UserRole = rawRole === 'superadmin' ? 'super_admin' : 'dept_admin';

      setUser({ 
        ...sheetAdmin, 
        role: internalRole 
      });
      return;
    }

    // Employee Direct Access (Internal Fallback)
    const sheetEmp = fullEmployeeDirectory.find(e => String(e.id).trim() === inputId);
    if (sheetEmp && inputPass === '12345') {
      setUser({
        id: String(sheetEmp.id).trim(),
        name: sheetEmp.name,
        role: 'employee',
        designation: sheetEmp.designation,
        department: sheetEmp.department,
        typeOfEmployee: sheetEmp.typeOfEmployee
      });
      return;
    }

    // Hardcoded Rescue
    const foundFallback = USERS.find(existing => 
      String(existing.id).trim() === inputId && 
      String(existing.password).trim() === inputPass
    );

    if (foundFallback) {
      setUser(foundFallback);
      return;
    }

    alert(`Authentication Failed.\n\nOnly registered Admins from the Google Sheet can log in.\nSuper Admin must define your role in the 'Admins' tab.`);
  };

  const selectedEmployeeResult = useMemo(() => {
    if (!employeeSearchId) return null;
    const searchTrimmed = employeeSearchId.trim();
    // Use filtered employees list based on permissions
    return visibleEmployees.find(e => String(e.id).trim() === searchTrimmed);
  }, [employeeSearchId, visibleEmployees]);

  const employeeToolsData = useMemo(() => {
    if (!selectedEmployeeResult) return [];
    // Only show transactions visible to current user for this employee
    const empTrx = visibleTransactions.filter(t => t.employeeId === selectedEmployeeResult.id);
    const toolsMap = new Map<string, any>();

    availableTools.forEach(name => {
       toolsMap.set(name, { name, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0, remarks: '' });
    });

    empTrx.forEach(t => {
      let tool = toolsMap.get(t.toolName);
      if (!tool) {
         tool = { name: t.toolName, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0, remarks: '' };
         toolsMap.set(t.toolName, tool);
      }
      if (t.entryType === 'Distribute') tool.distributed += t.quantity;
      if (t.entryType === 'Return') tool.returned += t.quantity;
      if (t.entryType === 'Faulty Return') tool.faulty += t.quantity;
      if (t.entryType === 'Damage') tool.damage += t.quantity;
      if (t.entryType === 'Lost') tool.lost += t.quantity;
      if (t.remarks) tool.remarks = t.remarks;
    });

    return Array.from(toolsMap.values()).filter(t => t.distributed > 0);
  }, [selectedEmployeeResult, visibleTransactions, availableTools]);

  const stockSummaryData = useMemo(() => {
    const allNames = Array.from(new Set([...TOOL_CATALOG.map(c => c.name), ...availableTools])).sort();
    return allNames.map(name => {
      // visibleTransactions is already pre-filtered by department for non-SuperAdmins
      const toolTrx = visibleTransactions.filter(t => t.toolName === name);
      let purchase = 0, distributed = 0, returned = 0, faulty = 0, damage = 0, lost = 0;
      toolTrx.forEach(t => {
        if (t.entryType === 'Stock IN') purchase += t.quantity;
        if (t.entryType === 'Distribute') distributed += t.quantity;
        if (t.entryType === 'Return') returned += t.quantity;
        if (t.entryType === 'Faulty Return') faulty += t.quantity;
        if (t.entryType === 'Damage') damage += t.quantity;
        if (t.entryType === 'Lost') lost += t.quantity;
      });
      return {
        name, purchase, distributed, returned, faulty, damage, lost,
        stockNow: purchase - distributed + returned
      };
    }).filter(tool => tool.purchase > 0 || tool.distributed > 0);
  }, [visibleTransactions, availableTools]);

  // --- Render ---

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-900 flex flex-col items-center justify-center gap-6 p-10">
        <div className="relative animate-pulse">
          <img src={LOGO_URL} alt="SARBS Logo" className="w-24 h-24 object-contain shadow-2xl rounded-2xl" />
          <Loader2 className="w-32 h-32 text-blue-500 absolute -top-4 -left-4 animate-spin opacity-30" />
        </div>
        <div className="text-center">
           <p className="text-white font-black text-xl tracking-tight uppercase">SARBS Inventory Hub</p>
           <p className="text-slate-400 text-sm mt-1 font-bold uppercase tracking-widest">Establishing Secure Connection...</p>
        </div>
      </div>
    );
  }

  if (!user) {
    return (
      <Login 
        onLogin={handleLogin} 
        isSyncing={isSyncing} 
        lastSync={lastSync} 
        onRefresh={() => loadData(true)}
        isOnline={isOnline}
        installPrompt={installPrompt}
        onInstall={handleInstallClick}
      />
    );
  }

  if (user.role === 'employee') {
    const myTools = visibleTransactions.filter(t => t.employeeId === user.id && t.entryType === 'Distribute').map(t => ({
      id: t.id, name: t.toolName, brand: 'Generic', serialNumber: `SN-${t.id.substring(0, 8)}`,
      status: 'In Use', quantity: t.quantity, assignedDate: t.date, remarks: t.remarks
    }));
    return <EmployeeDashboard user={user} tools={myTools} onLogout={() => setUser(null)} />;
  }

  return (
    <div className="min-h-screen bg-slate-100 font-sans text-slate-900 pb-20 safe-top">

      {!isOnline && (
        <div className="bg-red-600 text-white text-[10px] font-black uppercase tracking-widest py-2 text-center flex items-center justify-center gap-2 animate-pulse sticky top-0 z-50">
          <WifiOff className="w-3 h-3" /> Offline Mode - Changes will sync later
        </div>
      )}

      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-white p-1 rounded-lg border border-slate-100 shadow-sm">
              <img src={LOGO_URL} alt="SARBS" className="w-8 h-8 object-contain" />
            </div>
            <div className="hidden xs:block">
               <h1 className="text-sm sm:text-lg font-black text-slate-900 leading-tight">SARBS Admin</h1>
               <div className="flex items-center gap-2">
                 <span className={`text-[8px] px-1.5 rounded flex items-center gap-1 font-bold ${isOnline ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                   {isOnline ? <Wifi className="w-2.5 h-2.5" /> : <WifiOff className="w-2.5 h-2.5" />}
                   {isOnline ? 'LIVE' : 'DISCONNECTED'}
                 </span>
                 <span className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter">Updated: {lastSync}</span>
               </div>
            </div>
          </div>

          <div className="flex items-center gap-2 sm:gap-4">
             {installPrompt && (
               <button 
                onClick={handleInstallClick}
                className="hidden md:flex items-center gap-1.5 bg-blue-600 text-white px-4 py-2 rounded-full text-[10px] font-black shadow-lg hover:bg-blue-700 transition-all active:scale-95"
               >
                 <Smartphone className="w-3.5 h-3.5" /> INSTALL APP
               </button>
             )}

             <button 
               onClick={() => loadData(true)} 
               disabled={isSyncing}
               className={`p-2.5 rounded-full bg-slate-50 border border-slate-200 text-slate-400 hover:text-blue-600 transition-all shadow-sm ${isSyncing ? 'animate-spin text-blue-500 ring-2 ring-blue-100' : ''}`} 
               title="Sync Now"
             >
               <RefreshCw className="w-4 h-4" />
             </button>

             <div className="flex items-center gap-2 bg-slate-900 px-3 py-1.5 rounded-full shadow-md">
                {isSuperAdmin ? (
                  <ShieldCheck className="w-4 h-4 text-blue-400" />
                ) : (
                  <Building2 className="w-4 h-4 text-amber-400" />
                )}
                <div className="text-left hidden sm:block">
                  <div className="text-[10px] font-bold text-white leading-none truncate max-w-[80px]">{user.name}</div>
                  <div className={`text-[8px] font-black uppercase tracking-tighter mt-0.5 ${isSuperAdmin ? 'text-blue-400' : 'text-amber-400'}`}>
                    {isSuperAdmin ? 'Super Admin' : `${user.department}`}
                  </div>
                </div>
             </div>

             <button onClick={() => setUser(null)} className="p-2 text-slate-400 hover:text-red-600 transition-colors">
               <LogOut className="w-5 h-5" />
             </button>
          </div>
        </div>

        <div className="max-w-7xl mx-auto px-4 mt-2 flex gap-1 overflow-x-auto no-scrollbar pb-1">
           {[
             { id: 'employee', label: 'Team', icon: Users },
             { id: 'daily', label: 'Logs', icon: FileSpreadsheet },
             { id: 'stock', label: 'Inventory', icon: Package },
             ...(isSuperAdmin ? [{ id: 'admins', label: 'Access', icon: ShieldCheck }] : [])
           ].map((tab) => (
             <button 
               key={tab.id}
               onClick={() => setActiveTab(tab.id as Tab)}
               className={`px-5 py-3 text-xs font-black border-b-2 transition-all flex items-center gap-2 whitespace-nowrap uppercase tracking-widest ${activeTab === tab.id ? 'border-slate-900 text-slate-900 bg-white shadow-sm' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
             >
               <tab.icon className="w-4 h-4" /> {tab.label}
             </button>
           ))}
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-6">

        {activeTab === 'employee' && (
          <div className="space-y-6">
             <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
                <div className="flex flex-col sm:flex-row items-end gap-4">
                   <div className="w-full sm:max-w-md">
                      <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Search Employee Database</label>
                      <div className="relative group">
                         <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300 group-focus-within:text-blue-500 transition-colors" />
                         <input 
                           type="text" 
                           className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-4 focus:ring-blue-50 focus:border-blue-500 outline-none text-sm font-bold transition-all"
                           placeholder="Enter Employee ID"
                           value={employeeSearchId}
                           onChange={e => setEmployeeSearchId(e.target.value)}
                         />
                      </div>
                   </div>
                </div>
             </div>

             {selectedEmployeeResult ? (
               <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500">
                  <div className="grid grid-cols-2 md:grid-cols-5 gap-px bg-slate-100 border-b border-slate-200">
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Full Name</p>
                        <p className="font-black text-slate-900 text-sm truncate">{selectedEmployeeResult.name}</p>
                     </div>
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Position</p>
                        <p className="font-bold text-slate-600 text-sm truncate">{selectedEmployeeResult.designation}</p>
                     </div>
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Business Unit</p>
                        <p className="font-bold text-slate-600 text-sm">{selectedEmployeeResult.department}</p>
                     </div>
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Contract Status</p>
                        <span className="inline-block px-2 py-0.5 rounded text-[10px] font-black bg-green-50 text-green-600 border border-green-100 uppercase">{selectedEmployeeResult.typeOfEmployee}</span>
                     </div>
                     <div className="bg-white p-5 flex items-center justify-center">
                        <button 
                           onClick={() => generateEmployeePDF(selectedEmployeeResult, employeeToolsData.map(t => ({
                             name: t.name,
                             quantity: t.distributed - t.returned - t.lost,
                             assignedDate: '-',
                             remarks: t.remarks
                           })))}
                           className="flex items-center gap-2 text-slate-900 bg-slate-50 hover:bg-slate-900 hover:text-white px-4 py-2.5 rounded-xl transition-all text-xs font-black border border-slate-200 shadow-sm"
                        >
                           <Download className="w-4 h-4" /> EXPORT PDF
                        </button>
                     </div>
                  </div>

                  <div className="overflow-x-auto">
                    <table className="w-full text-xs text-center">
                      <thead>
                        <tr className="bg-slate-50 border-b border-slate-200 text-slate-400 uppercase tracking-widest font-black">
                          <th className="px-6 py-4 text-left w-1/4">Tool Description</th>
                          <th className="px-4 py-4 border-l border-slate-100">Out</th>
                          <th className="px-4 py-4 border-l border-slate-100">In</th>
                          <th className="px-4 py-4 border-l border-slate-100 text-amber-500">Faulty</th>
                          <th className="px-4 py-4 border-l border-slate-100 text-red-600">Lost</th>
                          <th className="px-6 py-4 border-l border-slate-100 bg-green-50 text-green-900">NET BAL</th>
                          <th className="px-6 py-4 border-l border-slate-100 text-left">Latest Update</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {employeeToolsData.map((row) => (
                          <tr key={row.name} className="hover:bg-slate-50 transition-colors">
                            <td className="px-6 py-4 text-left font-black text-slate-800">{row.name}</td>
                            <td className="px-4 py-4 border-l border-slate-100 font-medium text-slate-400">{row.distributed || ''}</td>
                            <td className="px-4 py-4 border-l border-slate-100 font-medium text-slate-400">{row.returned || ''}</td>
                            <td className="px-4 py-4 border-l border-slate-100 font-bold text-amber-500">{row.faulty || ''}</td>
                            <td className="px-4 py-4 border-l border-slate-100 font-bold text-red-600">{row.lost || ''}</td>
                            <td className="px-6 py-4 border-l border-slate-100 font-black bg-green-50 text-green-700 text-base">
                              {(row.distributed - row.returned - row.lost)}
                            </td>
                            <td className="px-6 py-4 border-l border-slate-100 text-left text-slate-400 italic max-w-xs truncate">{row.remarks}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
               </div>
             ) : (
                <div className="text-center py-32 bg-white rounded-3xl border-4 border-dashed border-slate-100 flex flex-col items-center">
                   <div className="bg-slate-50 p-6 rounded-full mb-4">
                     <Users className="w-16 h-16 text-slate-200" />
                   </div>
                   <p className="text-slate-900 font-black uppercase tracking-widest text-sm">Personnel Lookup Required</p>
                   <p className="text-slate-400 text-xs mt-2 max-w-[250px]">Enter an employee ID above to view equipment assignment history.</p>
                </div>
             )}
          </div>
        )}

        {activeTab === 'daily' && (
           <div className="space-y-4">
              <div className="flex justify-between items-center bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                 <div>
                    <h2 className="text-base font-black text-slate-900 uppercase tracking-tight">Stream: Logged Activity</h2>
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">{isSuperAdmin ? 'Global' : user.department} Operations</p>
                 </div>
                 <button 
                   onClick={() => setIsModalOpen(true)}
                   className="flex items-center gap-2 bg-slate-900 hover:bg-blue-600 text-white px-6 py-3 rounded-xl shadow-xl font-black text-xs transition-all active:scale-95"
