import React, { useState, useEffect } from 'react';
import { Transaction, EntryType } from '../types';
import { X, Calendar, User as UserIcon, Wrench, Plus, Trash2, Hash, Zap } from 'lucide-react';

interface ToolItem {
  toolName: string;
  quantity: number;
  condition: 'New' | 'Used';
}

interface ToolModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (transactions: Transaction[], employeeDetails?: any) => void;
  initialTransaction?: Transaction | null;
  employees: any[]; 
  availableTools: string[];
}

const ToolModal: React.FC<ToolModalProps> = ({ 
  isOpen, 
  onClose, 
  onSave, 
  initialTransaction, 
  employees = [], 
  availableTools = [] 
}) => {

  const [date, setDate] = useState('');
  const [entryType, setEntryType] = useState<EntryType>('Distribute');
  const [employeeId, setEmployeeId] = useState('');
  const [remarks, setRemarks] = useState('');
  const [toolItems, setToolItems] = useState<ToolItem[]>([
    { toolName: '', quantity: 1, condition: 'New' }
  ]);

  const entryTypes: EntryType[] = ['Distribute', 'Return', 'Faulty Return', 'Damage', 'Lost', 'Stock IN'];

  // When ID changes, find the employee details
  const selectedEmployee = employees.find(e => e.id === employeeId);

  useEffect(() => {
    if (initialTransaction) {
      setDate(initialTransaction.date);
      setEntryType(initialTransaction.entryType);
      setEmployeeId(initialTransaction.employeeId || '');
      setRemarks(initialTransaction.remarks || '');
      setToolItems([{
        toolName: initialTransaction.toolName,
        quantity: initialTransaction.quantity,
        condition: initialTransaction.condition as any
      }]);
    } else {
      setDate(new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: '2-digit' }).replace(/ /g, '-'));
      setEntryType('Distribute');
      setEmployeeId('');
      setRemarks('');
      setToolItems([{ toolName: availableTools[0] || '', quantity: 1, condition: 'New' }]);
    }
  }, [initialTransaction, isOpen, availableTools]);

  if (!isOpen) return null;

  const addToolItem = () => {
    setToolItems([...toolItems, { toolName: availableTools[0] || '', quantity: 1, condition: 'New' }]);
  };

  const removeToolItem = (index: number) => {
    if (toolItems.length > 1) {
      setToolItems(toolItems.filter((_, i) => i !== index));
    }
  };

  const updateToolItem = (index: number, field: keyof ToolItem, value: any) => {
    const newItems = [...toolItems];
    newItems[index] = { ...newItems[index], [field]: value };
    setToolItems(newItems);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const transactions: Transaction[] = toolItems.map((item, idx) => ({
      id: initialTransaction && idx === 0 ? initialTransaction.id : `${Date.now()}-${idx}`,
      date,
      entryType,
      employeeId,
      remarks,
      ...item
    } as Transaction));

    onSave(transactions, selectedEmployee);
    onClose();
  };

  const isEmployeeRequired = entryType !== 'Stock IN';

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col max-h-[90vh] animate-in zoom-in-95 duration-200">
        <div className="bg-slate-900 p-6 flex justify-between items-center text-white shrink-0">
          <div>
            <h2 className="text-sm font-black tracking-[0.2em] uppercase flex items-center gap-2">
              <Zap className="w-4 h-4 text-blue-400" />
              {initialTransaction ? 'Edit Log Entry' : 'Log New Transaction'}
            </h2>
            <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Personnel Inventory Protocol</p>
          </div>
          <button onClick={onClose} className="hover:bg-white/10 p-2 rounded-xl transition-colors">
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="overflow-y-auto p-6 space-y-6">
          <form onSubmit={handleSubmit} className="space-y-6">

            {/* Metadata Section */}
            <div className="grid grid-cols-2 gap-4">
               <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Entry Date</label>
                  <div className="relative">
                     <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                     <input
                      required
                      type="text"
                      className="w-full pl-10 pr-3 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-4 focus:ring-blue-50 focus:border-blue-500 outline-none font-black text-sm transition-all"
                      placeholder="12-May-24"
                      value={date}
                      onChange={e => setDate(e.target.value)}
                    />
                  </div>
               </div>
               <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Transaction Type</label>
                  <select
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-4 focus:ring-blue-50 focus:border-blue-500 outline-none font-black text-sm cursor-pointer"
                    value={entryType}
                    onChange={e => setEntryType(e.target.value as EntryType)}
                  >
                    {entryTypes.map(t => (
                      <option key={t} value={t}>{t}</option>
                    ))}
                  </select>
               </div>
            </div>

            {/* Employee Section */}
            {isEmployeeRequired && (
               <div className="p-4 bg-slate-50 rounded-2xl border border-slate-200 space-y-4">
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Target Personnel</label>
                    <div className="relative">
                       <UserIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                       <select
                          required
                          className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl focus:ring-4 focus:ring-blue-50 focus:border-blue-500 outline-none font-black text-sm transition-all cursor-pointer"
                          value={employeeId}
                          onChange={e => setEmployeeId(e.target.value)}
                        >
                          <option value="">Search & Select Employee...</option>
                          {employees.map(emp => (
                            <option key={emp.id} value={emp.id}>{emp.id} — {emp.name}</option>
                          ))}
                        </select>
                    </div>
                  </div>

                  {selectedEmployee && (
                    <div className="grid grid-cols-2 gap-4 animate-in fade-in slide-in-from-top-1 duration-300">
                       <div className="bg-white p-3 rounded-xl border border-slate-100 shadow-sm">
                          <span className="block text-[8px] text-slate-400 font-black uppercase tracking-widest mb-1">Full Name</span>
                          <span className="font-black text-slate-800 text-xs">{selectedEmployee.name}</span>
                       </div>
                       <div className="bg-white p-3 rounded-xl border border-slate-100 shadow-sm">
                          <span className="block text-[8px] text-slate-400 font-black uppercase tracking-widest mb-1">Managed Dept</span>
                          <span className="font-black text-slate-800 text-xs">{selectedEmployee.department}</span>
                       </div>
                    </div>
                  )}
               </div>
            )}

            {/* Tools Batch Section */}
            <div className="space-y-4">
               <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest">Assigned Material(s)</label>

               <div className="space-y-3">
                  {toolItems.map((item, index) => (
                    <div key={index} className="grid grid-cols-12 gap-2 p-4 bg-white border border-slate-200 rounded-2xl shadow-sm group relative">
                       <div className="col-span-12 sm:col-span-6">
                          <label className="block text-[8px] font-black text-slate-400 uppercase mb-1">Tool Name</label>
                          <div className="relative">
                            <Wrench className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-300" />
                            <select
                              required
                              className="w-full pl-8 pr-3 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-xs font-bold transition-all cursor-pointer"
                              value={item.toolName}
                              onChange={e => updateToolItem(index, 'toolName', e.target.value)}
                            >
                              <option value="">Choose Tool...</option>
                              {availableTools.map(name => (
                                <option key={name} value={name}>{name}</option>
                              ))}
                            </select>
                          </div>
                       </div>

                       <div className="col-span-6 sm:col-span-3">
                          <label className="block text-[8px] font-black text-slate-400 uppercase mb-1">Qty</label>
                          <div className="relative">
                            <Hash className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-300" />
                            <input
                              type="number"
                              min="1"
                              required
                              className="w-full pl-8 pr-3 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none font-black text-xs"
                              value={item.quantity}
                              onChange={e => updateToolItem(index, 'quantity', parseInt(e.target.value))}
                            />
                          </div>
                       </div>

                       <div className="col-span-6 sm:col-span-3">
                          <label className="block text-[8px] font-black text-slate-400 uppercase mb-1">Condition</label>
                          <select
                            className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-xs font-bold cursor-pointer"
                            value={item.condition}
                            onChange={e => updateToolItem(index, 'condition', e.target.value)}
                          >
                            <option value="New">New</option>
                            <option value="Used">Used</option>
                          </select>
                       </div>

                       {toolItems.length > 1 && !initialTransaction && (
                         <button 
                           type="button"
                           onClick={() => removeToolItem(index)}
                           className="absolute -top-2 -right-2 bg-red-100 text-red-600 p-1.5 rounded-full border border-red-200 shadow-sm hover:bg-red-600 hover:text-white transition-all scale-0 group-hover:scale-100"
                         >
                           <Trash2 className="w-3 h-3" />
                         </button>
                       )}
                    </div>
                  ))}
               </div>

               {!initialTransaction && (
                 <div className="pt-2 flex justify-start">
                   <button 
                    type="button" 
                    onClick={addToolItem}
                    className="text-[11px] font-black text-blue-600 hover:text-white hover:bg-blue-600 border-2 border-blue-600 border-dashed px-6 py-2 rounded-xl flex items-center gap-2 transition-all w-full sm:w-auto justify-center"
                   >
                     <Plus className="w-4 h-4" /> ADD MORE TOOLS
                   </button>
                 </div>
               )}
            </div>

            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Administrative Remarks</label>
              <textarea
                rows={3}
                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-4 focus:ring-blue-50 focus:border-blue-500 outline-none resize-none text-xs font-bold italic"
                placeholder="Details of distribution, specific site references, or return observations..."
                value={remarks}
                onChange={e => setRemarks(e.target.value)}
              />
            </div>

            <div className="flex justify-end gap-3 pt-6 border-t border-slate-100">
              <button
                type="button"
                onClick={onClose}
                className="px-6 py-3 text-xs text-slate-400 hover:text-slate-600 font-black transition-all uppercase tracking-widest"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="px-8 py-3 bg-slate-900 text-white hover:bg-blue-600 rounded-2xl font-black shadow-xl transition-all active:scale-[0.98] text-xs uppercase tracking-widest"
              >
                Commit {toolItems.length > 1 ? `${toolItems.length} Entries` : 'Entry'}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default ToolModal;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { 
  LogOut, 
  Search, 
  Plus, 
  FileSpreadsheet, 
  Users, 
  Package, 
  Loader2,
  RefreshCw,
  Download,
  ShieldCheck,
  Building2,
  Lock,
  UserCheck,
  Clock,
  Wifi,
  WifiOff,
  Smartphone,
  AlertTriangle,
  Filter
} from 'lucide-react';
import { USERS, TOOL_CATALOG, LOGO_URL } from './constants';
import { User, Transaction, UserRole } from './types';
import ToolModal from './components/ToolModal';
import AIChat from './components/AIChat';
import Login from './components/Login';
import EmployeeDashboard from './components/EmployeeDashboard';
import { fetchSheetData, saveTransactionToSheet } from './services/sheetService';
import { generateEmployeePDF } from './services/pdfService';

type Tab = 'employee' | 'daily' | 'stock' | 'admins';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [allTransactions, setAllTransactions] = useState<Transaction[]>([]);
  const [fullEmployeeDirectory, setFullEmployeeDirectory] = useState<any[]>([]);
  const [availableTools, setAvailableTools] = useState<string[]>([]);
  const [sheetAdmins, setSheetAdmins] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSync, setLastSync] = useState<string>('');
  const [activeTab, setActiveTab] = useState<Tab>('employee');
  const [employeeSearchId, setEmployeeSearchId] = useState('');
  const [selectedDeptFilter, setSelectedDeptFilter] = useState<string>('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [installPrompt, setInstallPrompt] = useState<any>(null);

  // --- Sync Logic ---

  const loadData = useCallback(async (isBackground = false) => {
    if (!isBackground) setIsLoading(true);
    else setIsSyncing(true);

    try {
      const data = await fetchSheetData();
      setAllTransactions(data.transactions);
      setFullEmployeeDirectory(data.employees);
      setAvailableTools(data.tools);
      setSheetAdmins(data.admins);
      setLastSync(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));

      console.log(`[Cloud Sync] Found ${data.admins.length} admins in G-Sheet.`);
    } catch (e) {
      console.error("Error loading data", e);
    } finally {
      setIsLoading(false);
      setTimeout(() => setIsSyncing(false), 800);
    }
  }, []);

  // --- PWA & Connectivity Listeners ---

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const handleFocus = () => {
      if (navigator.onLine) loadData(true);
    };
    window.addEventListener('focus', handleFocus);

    const handleInstallPrompt = (e: any) => {
      e.preventDefault();
      setInstallPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handleInstallPrompt);

    loadData();

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      window.removeEventListener('focus', handleFocus);
      window.removeEventListener('beforeinstallprompt', handleInstallPrompt);
    };
  }, [loadData]);

  const handleInstallClick = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') setInstallPrompt(null);
  };

  // --- ACCESS CONTROLLED DATA ---

  const isSuperAdmin = useMemo(() => {
    if (!user) return false;
    const normalizedRole = user.role.toLowerCase().replace(/[\s_]/g, '');
    return normalizedRole === 'superadmin';
  }, [user]);

  const departments = useMemo(() => {
    const depts = new Set<string>();
    fullEmployeeDirectory.forEach(emp => {
      if (emp.department) depts.add(emp.department);
    });
    return Array.from(depts).sort();
  }, [fullEmployeeDirectory]);

  const visibleEmployees = useMemo(() => {
    if (!user) return [];
    if (isSuperAdmin) return fullEmployeeDirectory;
    return fullEmployeeDirectory.filter(emp => emp.department === user.department);
  }, [user, isSuperAdmin, fullEmployeeDirectory]);

  const visibleTransactions = useMemo(() => {
    if (!user) return [];
    if (isSuperAdmin) return allTransactions;
    return allTransactions.filter(trx => trx.department === user.department);
  }, [user, isSuperAdmin, allTransactions]);

  // --- Actions ---

  const handleSaveTransactions = async (transactions: Transaction[], employeeDetails?: any) => {
    if (!user) return;

    const enrichedTransactions = transactions.map(trx => {
      const enrichedTrx = { ...trx };
      if (trx.entryType === 'Stock IN') {
        enrichedTrx.department = user.department;
      } else if (employeeDetails) {
        enrichedTrx.department = employeeDetails.department;
      } else {
        enrichedTrx.department = user.department;
      }
      return enrichedTrx;
    });

    // Update local state first for responsiveness
    let newAllTransactions = [...allTransactions];
    enrichedTransactions.forEach(trx => {
      const index = newAllTransactions.findIndex(t => t.id === trx.id);
      if (index !== -1) {
        newAllTransactions[index] = trx;
      } else {
        newAllTransactions.push(trx);
      }
    });

    setAllTransactions(newAllTransactions);
    setEditingTransaction(null);

    // Save to sheet (serial for simplicity, could be parallelized)
    let allSuccess = true;
    setIsSyncing(true);
    for (const trx of enrichedTransactions) {
      const success = await saveTransactionToSheet(trx, employeeDetails || { department: user.department });
      if (!success) allSuccess = false;
    }

    if (!allSuccess) {
      alert("Some entries failed to sync to Google Sheet. Please refresh to verify.");
    }

    loadData(true);
  };

  const handleLogin = (u: { id: string, password?: string }) => {
    const inputId = String(u.id || '').trim();
    const inputPass = String(u.password || '').trim();

    if (!inputId) {
      alert("Please enter a valid Personnel ID.");
      return;
    }

    const sheetAdmin = sheetAdmins.find(admin => 
      String(admin.id).trim() === inputId && 
      String(admin.password).trim() === inputPass
    );

    if (sheetAdmin) {
      const rawRole = sheetAdmin.role.toLowerCase().replace(/[\s_]/g, '');
      const internalRole: UserRole = rawRole === 'superadmin' ? 'super_admin' : 'dept_admin';

      setUser({ 
        ...sheetAdmin, 
        role: internalRole 
      });
      return;
    }

    const sheetEmp = fullEmployeeDirectory.find(e => String(e.id).trim() === inputId);
    if (sheetEmp && inputPass === '12345') {
      setUser({
        id: String(sheetEmp.id).trim(),
        name: sheetEmp.name,
        role: 'employee',
        designation: sheetEmp.designation,
        department: sheetEmp.department,
        typeOfEmployee: sheetEmp.typeOfEmployee
      });
      return;
    }

    const foundFallback = USERS.find(existing => 
      String(existing.id).trim() === inputId && 
      String(existing.password).trim() === inputPass
    );

    if (foundFallback) {
      setUser(foundFallback);
      return;
    }

    alert(`Authentication Failed.\n\nOnly registered Admins from the Google Sheet can log in.\nSuper Admin must define your role in the 'Admins' tab.`);
  };

  const selectedEmployeeResult = useMemo(() => {
    if (!employeeSearchId) return null;
    const searchTrimmed = employeeSearchId.trim().toLowerCase();

    // Try exact ID match or exact Name match
    return visibleEmployees.find(e => 
      String(e.id).trim().toLowerCase() === searchTrimmed || 
      String(e.name).trim().toLowerCase() === searchTrimmed
    );
  }, [employeeSearchId, visibleEmployees]);

  const employeeToolsData = useMemo(() => {
    if (!selectedEmployeeResult) return [];
    const empTrx = visibleTransactions.filter(t => t.employeeId === selectedEmployeeResult.id);
    const toolsMap = new Map<string, any>();

    availableTools.forEach(name => {
       toolsMap.set(name, { name, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0, remarks: '' });
    });

    empTrx.forEach(t => {
      let tool = toolsMap.get(t.toolName);
      if (!tool) {
         tool = { name: t.toolName, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0, remarks: '' };
         toolsMap.set(t.toolName, tool);
      }
      if (t.entryType === 'Distribute') tool.distributed += t.quantity;
      if (t.entryType === 'Return') tool.returned += t.quantity;
      if (t.entryType === 'Faulty Return') tool.faulty += t.quantity;
      if (t.entryType === 'Damage') tool.damage += t.quantity;
      if (t.entryType === 'Lost') tool.lost += t.quantity;
      if (t.remarks) tool.remarks = t.remarks;
    });

    return Array.from(toolsMap.values()).filter(t => t.distributed > 0);
  }, [selectedEmployeeResult, visibleTransactions, availableTools]);

  const stockSummaryData = useMemo(() => {
    let targetTrx = allTransactions;
    if (!isSuperAdmin) {
      targetTrx = visibleTransactions;
    } else if (selectedDeptFilter !== '') {
      targetTrx = allTransactions.filter(t => t.department === selectedDeptFilter);
    }

    const allNames = Array.from(new Set([...TOOL_CATALOG.map(c => c.name), ...availableTools])).sort();
    return allNames.map(name => {
      const toolTrx = targetTrx.filter(t => t.toolName === name);
      let purchase = 0, distributed = 0, returned = 0, faulty = 0, damage = 0, lost = 0;
      toolTrx.forEach(t => {
        if (t.entryType === 'Stock IN') purchase += t.quantity;
        if (t.entryType === 'Distribute') distributed += t.quantity;
        if (t.entryType === 'Return') returned += t.quantity;
        if (t.entryType === 'Faulty Return') faulty += t.quantity;
        if (t.entryType === 'Damage') damage += t.quantity;
        if (t.entryType === 'Lost') lost += t.quantity;
      });
      return {
        name, purchase, distributed, returned, faulty, damage, lost,
        stockNow: purchase - distributed + returned
      };
    }).filter(tool => tool.purchase > 0 || tool.distributed > 0);
  }, [allTransactions, visibleTransactions, availableTools, isSuperAdmin, selectedDeptFilter]);

  // --- Render ---

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-900 flex flex-col items-center justify-center gap-6 p-10">
        <div className="relative">
          <img src={LOGO_URL} alt="SARBS Logo" className="w-24 h-24 object-contain" />
          <Loader2 className="w-32 h-32 text-blue-500 absolute -top-4 -left-4 animate-spin opacity-30" />
        </div>
        <div className="text-center">
           <p className="text-white font-black text-xl tracking-tight uppercase">SARBS Inventory Hub</p>
           <p className="text-slate-400 text-sm mt-1 font-bold uppercase tracking-widest">Establishing Secure Connection...</p>
        </div>
      </div>
    );
  }

  if (!user) {
    return (
      <Login 
        onLogin={handleLogin} 
        isSyncing={isSyncing} 
        lastSync={lastSync} 
        onRefresh={() => loadData(true)}
        isOnline={isOnline}
        installPrompt={installPrompt}
        onInstall={handleInstallClick}
      />
    );
  }

  if (user.role === 'employee') {
    const myTools = visibleTransactions.filter(t => t.employeeId === user.id && t.entryType === 'Distribute').map(t => ({
      id: t.id, name: t.toolName, brand: 'Generic', serialNumber: `SN-${t.id.substring(0, 8)}`,
      status: 'In Use', quantity: t.quantity, assignedDate: t.date, remarks: t.remarks
    }));
    return <EmployeeDashboard user={user} tools={myTools} onLogout={() => setUser(null)} />;
  }

  return (
    <div className="min-h-screen bg-slate-100 font-sans text-slate-900 pb-20 safe-top">

      {!isOnline && (
        <div className="bg-red-600 text-white text-[10px] font-black uppercase tracking-widest py-2 text-center flex items-center justify-center gap-2 animate-pulse sticky top-0 z-50">
          <WifiOff className="w-3 h-3" /> Offline Mode - Changes will sync later
        </div>
      )}

      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="flex items-center justify-center">
              <img src={LOGO_URL} alt="SARBS" className="w-10 h-10 object-contain" />
            </div>
            <div className="hidden xs:block">
               <h1 className="text-sm sm:text-lg font-black text-slate-900 leading-tight">SARBS Admin</h1>
               <div className="flex items-center gap-2">
                 <span className={`text-[8px] px-1.5 rounded flex items-center gap-1 font-bold ${isOnline ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                   {isOnline ? <Wifi className="w-2.5 h-2.5" /> : <WifiOff className="w-2.5 h-2.5" />}
                   {isOnline ? 'LIVE' : 'DISCONNECTED'}
                 </span>
                 <span className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter">Updated: {lastSync}</span>
               </div>
            </div>
          </div>

          <div className="flex items-center gap-2 sm:gap-4">
             {installPrompt && (
               <button 
                onClick={handleInstallClick}
                className="hidden md:flex items-center gap-1.5 bg-blue-600 text-white px-4 py-2 rounded-full text-[10px] font-black shadow-lg hover:bg-blue-700 transition-all active:scale-95"
               >
                 <Smartphone className="w-3.5 h-3.5" /> INSTALL APP
               </button>
             )}

             <button 
               onClick={() => loadData(true)} 
               disabled={isSyncing}
               className={`p-2.5 rounded-full bg-slate-50 border border-slate-200 text-slate-400 hover:text-blue-600 transition-all shadow-sm ${isSyncing ? 'animate-spin text-blue-500 ring-2 ring-blue-100' : ''}`} 
               title="Sync Now"
             >
               <RefreshCw className="w-4 h-4" />
             </button>

             <div className="flex items-center gap-2 bg-slate-900 px-3 py-1.5 rounded-full shadow-md">
                {isSuperAdmin ? (
                  <ShieldCheck className="w-4 h-4 text-blue-400" />
                ) : (
                  <Building2 className="w-4 h-4 text-amber-400" />
                )}
                <div className="text-left hidden sm:block">
                  <div className="text-[10px] font-bold text-white leading-none truncate max-w-[80px]">{user.name}</div>
                  <div className={`text-[8px] font-black uppercase tracking-tighter mt-0.5 ${isSuperAdmin ? 'text-blue-400' : 'text-amber-400'}`}>
                    {isSuperAdmin ? 'Super Admin' : `${user.department}`}
                  </div>
                </div>
             </div>

             <button onClick={() => setUser(null)} className="p-2 text-slate-400 hover:text-red-600 transition-colors">
               <LogOut className="w-5 h-5" />
             </button>
          </div>
        </div>

        <div className="max-w-7xl mx-auto px-4 mt-2 flex gap-1 overflow-x-auto no-scrollbar pb-1">
           {[
             { id: 'employee', label: 'Team', icon: Users },
             { id: 'daily', label: 'Logs', icon: FileSpreadsheet },
             { id: 'stock', label: 'Inventory', icon: Package },
             ...(isSuperAdmin ? [{ id: 'admins', label: 'Access', icon: ShieldCheck }] : [])
           ].map((tab) => (
             <button 
               key={tab.id}
               onClick={() => setActiveTab(tab.id as Tab)}
               className={`px-5 py-3 text-xs font-black border-b-2 transition-all flex items-center gap-2 whitespace-nowrap uppercase tracking-widest ${activeTab === tab.id ? 'border-slate-900 text-slate-900 bg-white shadow-sm' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
             >
               <tab.icon className="w-4 h-4" /> {tab.label}
             </button>
           ))}
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-6">

        {activeTab === 'employee' && (
          <div className="space-y-6">
             <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
                <div className="flex flex-col sm:flex-row items-end gap-4">
                   <div className="w-full sm:max-w-md">
                      <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Search Employee Database</label>
                      <div className="relative group">
                         <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300 group-focus-within:text-blue-500 transition-colors" />
                         <input 
                           type="text" 
                           list="employee-search-options"
                           className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-4 focus:ring-blue-50 focus:border-blue-500 outline-none text-sm font-bold transition-all"
                           placeholder="Search by ID or Full Name..."
                           value={employeeSearchId}
                           onChange={e => setEmployeeSearchId(e.target.value)}
                         />
                         <datalist id="employee-search-options">
                            {visibleEmployees.map(emp => (
                              <option key={emp.id} value={emp.id}>{emp.name}</option>
                            ))}
                            {visibleEmployees.map(emp => (
                              <option key={`name-${emp.id}`} value={emp.name}>{emp.id}</option>
                            ))}
                         </datalist>
                      </div>
                   </div>
                </div>
             </div>

             {selectedEmployeeResult ? (
               <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500">
                  <div className="grid grid-cols-2 md:grid-cols-5 gap-px bg-slate-100 border-b border-slate-200">
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Full Name</p>
                        <p className="font-black text-slate-900 text-sm truncate">{selectedEmployeeResult.name}</p>
                     </div>
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Position</p>
                        <p className="font-bold text-slate-600 text-sm truncate">{selectedEmployeeResult.designation}</p>
                     </div>
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Business Unit</p>
                        <p className="font-bold text-slate-600 text-sm">{selectedEmployeeResult.department}</p>
                     </div>
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Contract Status</p>
                        <span className="inline-block px-2 py-0.5 rounded text-[10px] font-black bg-green-50 text-green-600 border border-green-100 uppercase">{selectedEmployeeResult.typeOfEmployee}</span>
                     </div>
                     <div className="bg-white p-5 flex items-center justify-center">
                        <button 
