                       </thead>
                       <tbody className="divide-y divide-slate-100">
                          {stockSummaryData.map((row) => (
                             <tr key={row.name} className="hover:bg-slate-50 transition-colors">
                                <td className="px-4 py-5 text-left font-black text-slate-900 border-r border-slate-50">{row.name}</td>
                                <td className="px-2 py-5 font-bold text-slate-500 border-r border-slate-50">{row.purchase || 0}</td>
