                      />
                      {searchQuery && (
                        <button onClick={() => { setSearchQuery(''); setSelectedEmployee(null); }} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-300 hover:text-red-500"><CloseIcon className="w-4 h-4" /></button>
