                             <ChevronRight className="w-4 h-4 text-slate-200 group-hover:text-blue-500" />
                          </button>
                        ))}
                     </div>
                   )}
                </div>
             </div>

             {selectedEmployee ? (
               <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden animate-in fade-in duration-500">
                  <div className="grid grid-cols-2 md:grid-cols-5 gap-px bg-slate-100 border-b border-slate-200">
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Full Name</p>
                        <p className="font-black text-slate-900 text-sm truncate">{selectedEmployee.name}</p>
                     </div>
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Position</p>
                        <p className="font-bold text-slate-600 text-sm truncate">{selectedEmployee.designation}</p>
                     </div>
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Business Unit</p>
                        <p className="font-bold text-slate-600 text-sm">{selectedEmployee.department}</p>
                     </div>
                     <div className="bg-white p-5">
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-tighter">Contract Status</p>
                        <span className="inline-block px-2 py-0.5 rounded text-[10px] font-black bg-green-50 text-green-600 border border-green-100 uppercase">{selectedEmployee.typeOfEmployee}</span>
                     </div>
                     <div className="bg-white p-5 flex items-center justify-center">
                        <button onClick={() => generateEmployeePDF(selectedEmployee, employeeToolsData.map(t => ({ name: t.name, quantity: t.distributed - t.returned - t.lost, assignedDate: '-', remarks: t.remarks })))} className="flex items-center gap-2 bg-slate-50 hover:bg-slate-900 hover:text-white px-4 py-2.5 rounded-xl transition-all text-xs font-black border border-slate-200 shadow-sm">
