interface AdminModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (admin: User) => void;
  initialData?: User | null;
  departments: string[];
}

const AdminModal: React.FC<AdminModalProps> = ({ 
  isOpen, 
  onClose, 
  onSave, 
  initialData,
  departments
