function doGet(e) {
  try {
    const transactions = getTransactions();
    const metadata = getMetadata();
    const admins = getAdmins();

    return createJSONOutput({ 
      status: 'success',
      transactions: transactions,
      employees: metadata.employees,
      tools: metadata.tools,
      admins: admins
    });

  } catch (error) {
    console.error("Critical doGet Error: " + error.toString());
    return createJSONOutput({ status: 'error', message: error.toString() });
  }
}

function doPost(e) {
  const lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    const requestData = JSON.parse(e.postData.contents);
    const p = requestData.payload;

    if (requestData.action === 'addTransaction') {
      const sheet = getSheet("Daily Entry");
      sheet.appendRow([
        p.date,
        p.employeeId || '',
        p.employeeName || '',
        p.designation || '',
        p.department || '',
        p.typeOfEmployee || '',
        p.toolName,
        p.entryType,
        p.quantity,
        p.condition,
        p.remarks || ''
      ]);
      return createJSONOutput({ status: 'success' });
    }

    if (requestData.action === 'addEmployee') {
      const sheet = getSheet("Data Validation");
      // Columns: ID(1), Name(2), Designation(3), Dept(4), Type(5), Empty(6), ToolName(7)
      sheet.appendRow([
        p.id,
        p.name,
        p.designation,
        p.department,
        p.typeOfEmployee,
        '', // Empty placeholder
        ''  // Tool Name placeholder
      ]);
      return createJSONOutput({ status: 'success' });
    }

    if (requestData.action === 'upsertAdmin') {
      const sheet = getSheet("Admins");
      const currentAdmins = getAdmins();
      const targetId = String(p.id).trim();

      // Find existing admin row index (0-based)
      let rowIndex = -1;
      for (let i = 0; i < currentAdmins.length; i++) {
        if (currentAdmins[i].id === targetId) {
          rowIndex = i;
          break;
        }
      }

      const rowValues = [p.id, p.name, p.password, p.role, p.department, p.designation];

      if (rowIndex !== -1) {
        // Update existing row
        sheet.getRange(rowIndex + 2, 1, 1, 6).setValues([rowValues]);
      } else {
        // Append new row
        sheet.appendRow(rowValues);
      }
      return createJSONOutput({ status: 'success' });
    }

    if (requestData.action === 'deleteAdmin') {
      const sheet = getSheet("Admins");
      const data = sheet.getDataRange().getValues();
      const targetId = String(p.id).trim();

      for (let i = 1; i < data.length; i++) {
        if (String(data[i][0]).trim() === targetId) {
          sheet.deleteRow(i + 1);
          return createJSONOutput({ status: 'success' });
        }
      }
      return createJSONOutput({ status: 'error', message: 'Admin not found' });
    }

    return createJSONOutput({ status: 'error', message: 'Unknown action: ' + requestData.action });

  } catch (error) {
    console.error("Critical doPost Error: " + error.toString());
    return createJSONOutput({ status: 'error', message: error.toString() });
  } finally {
    lock.releaseLock();
  }
}

function getAdmins() {
  const sheet = getSheet("Admins");
  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return [];
  const data = sheet.getRange(2, 1, lastRow - 1, 6).getDisplayValues();

  return data.map(function(row) {
    return {
      id: String(row[0] || '').trim(),
      name: String(row[1] || '').trim(),
      password: String(row[2] || '').trim(),
      role: String(row[3] || '').trim(),
      department: String(row[4] || '').trim(),
      designation: String(row[5] || '').trim()
    };
  }).filter(function(admin) {
    return admin.id !== "";
  });
}

function getTransactions() {
  const sheet = getSheet("Daily Entry");
  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return [];
  const data = sheet.getDataRange().getDisplayValues();
  const rows = data.slice(1);

  return rows.map(function(row, index) {
    return {
      id: 'row-' + (index + 2),
      date: String(row[0] || '').trim(),
      employeeId: String(row[1] || '').trim(),
      employeeName: String(row[2] || '').trim(),
      designation: String(row[3] || '').trim(),
      department: String(row[4] || '').trim(),
      typeOfEmployee: String(row[5] || '').trim(),
      toolName: String(row[6] || '').trim(),
      entryType: String(row[7] || '').trim(),
      quantity: Number(row[8] || 0),
      condition: String(row[9] || '').trim(),
      remarks: String(row[10] || '').trim()
    };
  });
}

function getMetadata() {
  const sheet = getSheet("Data Validation");
  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return { employees: [], tools: [] };
  const range = sheet.getRange(2, 1, lastRow - 1, 7).getDisplayValues(); 
  const employees = [];
  const tools = [];
  const addedEmpIds = {};
  const addedTools = {};

  for (let i = 0; i < range.length; i++) {
    const row = range[i];
    const empId = String(row[0] || '').trim();
    if (empId && !addedEmpIds[empId]) {
      employees.push({
        id: empId,
        name: String(row[1] || '').trim(),
        designation: String(row[2] || '').trim(),
        department: String(row[3] || '').trim(),
        typeOfEmployee: String(row[4] || '').trim()
      });
      addedEmpIds[empId] = true;
    }
    const toolName = String(row[6] || '').trim();
    if (toolName && !addedTools[toolName]) {
      tools.push(toolName);
      addedTools[toolName] = true;
    }
  }
  return { employees: employees, tools: tools };
}

function getSheet(name) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
    if (name === "Admins") {
      sheet.appendRow(["ID", "Name", "Password", "Role", "Department", "Designation"]);
    } else if (name === "Daily Entry") {
      sheet.appendRow(["Date", "ID", "Name", "Designation", "Department", "Type", "Item Name", "Entry Type", "Quantity", "Condition", "Remarks"]);
    } else if (name === "Data Validation") {
       sheet.appendRow(["ID", "Name", "Designation", "Department", "Type of Employee", "", "Tool Name"]);
    }
  }
  return sheet;
}

function createJSONOutput(data) {
  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

import { Transaction, User } from '../types';
import { GOOGLE_SCRIPT_URL, INITIAL_TRANSACTIONS, USERS, TOOL_CATALOG } from '../constants';

const HEADERS = {
  'Content-Type': 'text/plain;charset=utf-8', 
};

export interface SheetData {
  transactions: Transaction[];
  employees: any[];
  tools: string[];
  admins: User[];
}

export const fetchSheetData = async (): Promise<SheetData> => {
  if (!GOOGLE_SCRIPT_URL) {
    return { 
      transactions: INITIAL_TRANSACTIONS, 
      employees: USERS.filter(u => u.role === 'employee'), 
      tools: TOOL_CATALOG.map(t => t.name),
      admins: USERS.filter(u => u.role !== 'employee')
    };
  }

  try {
    const response = await fetch(`${GOOGLE_SCRIPT_URL}?action=getFullData&t=${Date.now()}`);
    if (!response.ok) throw new Error('Network response was not ok');
    const data = await response.json();
    return {
      transactions: data.transactions || [],
      employees: data.employees || [],
      tools: data.tools || [],
      admins: data.admins || []
    };
  } catch (error) {
    console.error("Failed to fetch sheet data:", error);
    return { 
      transactions: INITIAL_TRANSACTIONS, 
      employees: [], 
      tools: TOOL_CATALOG.map(t => t.name),
      admins: USERS
    };
  }
};

export const saveTransactionToSheet = async (transaction: Transaction, user?: any): Promise<boolean> => {
  if (!GOOGLE_SCRIPT_URL) return Promise.resolve(true);
  try {
    const payload = {
      action: 'addTransaction',
      payload: {
        ...transaction,
        employeeName: user?.name,
        designation: user?.designation,
        department: user?.department,
        typeOfEmployee: user?.typeOfEmployee
      }
    };
    const response = await fetch(GOOGLE_SCRIPT_URL, {
      method: 'POST',
      headers: HEADERS,
      body: JSON.stringify(payload)
    });
    const result = await response.json();
    return result.status === 'success';
  } catch (error) {
    console.error("Failed to save transaction:", error);
    return false;
  }
};

export const saveEmployeeToSheet = async (employee: any): Promise<boolean> => {
  if (!GOOGLE_SCRIPT_URL) return Promise.resolve(true);
  try {
    const payload = {
      action: 'addEmployee',
      payload: employee
    };
    const response = await fetch(GOOGLE_SCRIPT_URL, {
      method: 'POST',
      headers: HEADERS,
      body: JSON.stringify(payload)
    });
    const result = await response.json();
    return result.status === 'success';
  } catch (error) {
    console.error("Failed to save employee:", error);
    return false;
  }
};

export const saveAdminToSheet = async (admin: User): Promise<boolean> => {
  if (!GOOGLE_SCRIPT_URL) return Promise.resolve(true);
