                      <select className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-black" value={selectedDeptFilter} onChange={(e) => setSelectedDeptFilter(e.target.value)}>
                        <option value="">All Department Tools Inventory</option>
                        {departments.map(dept => <option key={dept} value={dept}>{dept}</option>)}
                      </select>
                   </div>
                 )}
              </div>
              <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden overflow-x-auto">
                 <table className="w-full text-[11px] text-center border-collapse">
                    <thead className="bg-[#F8FAFC] text-slate-500 border-b border-slate-200 uppercase font-black">
                       <tr>
                          <th className="px-4 py-5 text-left border-r border-slate-200 min-w-[200px]">Tools Name</th>
                          <th className="px-2 py-5 border-r border-slate-200">Purchase</th>
                          <th className="px-2 py-5 border-r border-slate-200">Dist. Qty</th>
                          <th className="px-2 py-5 border-r border-slate-200">Ret. Qty</th>
                          <th className="px-2 py-5 border-r border-slate-200 text-amber-600">Faulty</th>
                          <th className="px-2 py-5 border-r border-slate-200 text-red-500">Damage</th>
                          <th className="px-2 py-5 border-r border-slate-200 text-red-700">Lost</th>
                          <th className="px-4 py-5 bg-slate-900 text-white font-black">Stock Now</th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                       {stockSummaryData.map((row) => (
                          <tr key={row.name} className="hover:bg-slate-50">
                             <td className="px-4 py-5 text-left font-black text-slate-900 border-r border-slate-100">{row.name}</td>
                             <td className="px-2 py-5 font-bold text-slate-500 border-r border-slate-100">{row.purchase || 0}</td>
                             <td className="px-2 py-5 font-bold text-slate-500 border-r border-slate-100">{row.distributed || 0}</td>
                             <td className="px-2 py-5 font-bold text-slate-500 border-r border-slate-100">{row.returned || 0}</td>
                             <td className="px-2 py-5 font-bold text-amber-600 border-r border-slate-100">{row.faulty || 0}</td>
                             <td className="px-2 py-5 font-bold text-red-500 border-r border-slate-100">{row.damage || 0}</td>
                             <td className="px-2 py-5 font-bold text-red-600 border-r border-slate-100">{row.lost || 0}</td>
                             <td className="px-4 py-5 font-black bg-slate-50 text-base text-slate-900">{row.stockNow}</td>
                          </tr>
                       ))}
                    </tbody>
                 </table>
              </div>
           </div>
        )}

        {activeTab === 'admins' && isSuperAdmin && (
           <div className="space-y-4">
              <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex justify-between items-center">
                 <div>
                    <h2 className="text-base font-black text-slate-900 uppercase tracking-tight flex items-center gap-2">
                       <Lock className="w-5 h-5 text-indigo-600" /> Administrative Access List
                    </h2>
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">Managed directly from "Admins" G-Sheet</p>
                 </div>
                 <button 
                   onClick={() => { setEditingAdmin(null); setIsAdminModalOpen(true); }}
                   className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-2.5 rounded-xl shadow-lg font-black text-xs transition-all active:scale-95 uppercase tracking-widest"
                 >
                    <UserPlus className="w-4 h-4" /> ADD ADMIN
                 </button>
              </div>
              <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden overflow-x-auto">
                 <table className="w-full text-xs text-left">
                    <thead className="bg-[#F8FAFC] text-slate-400 border-b uppercase font-black tracking-widest">
                       <tr>
                          <th className="px-8 py-5">Personnel ID</th>
                          <th className="px-8 py-5">Name</th>
                          <th className="px-8 py-5">Role</th>
                          <th className="px-8 py-5">Department</th>
                          <th className="px-8 py-5">Designation</th>
                          <th className="px-8 py-5 text-center">Action</th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                       {sheetAdmins.map((admin) => {
                          const isSuper = admin.role.toLowerCase().replace(/[\s_]/g, '') === 'superadmin' || admin.role.toLowerCase().replace(/[\s_]/g, '') === 'super_admin';
                          return (
                            <tr key={admin.id} className="hover:bg-indigo-50/50 transition-colors">
                               <td className="px-8 py-5 font-mono font-black text-slate-500">{admin.id}</td>
                               <td className="px-8 py-5 font-black text-slate-900 text-base">{admin.name}</td>
                               <td className="px-8 py-5">
                                  <span className={`px-2.5 py-1.5 rounded-lg text-[9px] font-black uppercase border ${isSuper ? 'bg-indigo-900 text-white border-indigo-950 shadow-md' : 'bg-white text-amber-600 border-amber-200'}`}>
                                     {admin.role.replace(/_/g, ' ')}
                                  </span>
                               </td>
                               <td className="px-8 py-5 text-slate-600 font-black uppercase text-[10px]">{admin.department}</td>
                               <td className="px-8 py-5 text-slate-400 font-bold">{admin.designation}</td>
                               <td className="px-8 py-5 text-center flex items-center justify-center gap-2">
                                  <button 
                                    onClick={() => { setEditingAdmin(admin); setIsAdminModalOpen(true); }}
                                    className="p-2 hover:bg-white rounded-lg text-slate-400 hover:text-indigo-600 transition-colors border border-transparent hover:border-slate-200"
                                    title="Edit Administrator"
                                  >
                                     <Edit2 className="w-4 h-4" />
                                  </button>
                                  <button 
                                    onClick={() => handleDeleteAdmin(admin.id, admin.role)}
                                    disabled={isSuper}
                                    className={`p-2 rounded-lg transition-colors border border-transparent ${isSuper ? 'text-slate-200 cursor-not-allowed' : 'text-slate-400 hover:text-red-600 hover:bg-white hover:border-slate-200'}`}
                                    title={isSuper ? "Super Admin cannot be deleted" : "Delete Administrator"}
                                  >
                                     <Trash2 className="w-4 h-4" />
                                  </button>
                               </td>
                            </tr>
                          );
                       })}
                    </tbody>
                 </table>
              </div>
           </div>
        )}
      </main>

      <ToolModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSave={handleSaveTransactions} 
        initialTransaction={editingTransaction} 
        employees={visibleEmployees} 
        availableTools={availableTools} 
      />

      <EmployeeModal 
        isOpen={isEmployeeModalOpen}
        onClose={() => setIsEmployeeModalOpen(false)}
        onSave={handleSaveEmployee}
        isAdmin={isAdmin}
        isSuperAdmin={isSuperAdmin}
        userDepartment={user?.department || ''}
        allDepartments={departments}
      />

      <AdminModal 
        isOpen={isAdminModalOpen}
        onClose={() => { setIsAdminModalOpen(false); setEditingAdmin(null); }}
        onSave={handleSaveAdmin}
        initialData={editingAdmin}
        departments={departments}
      />

      <AIChat inventory={stockSummaryData} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useCallback, useRef } from 'react';
import { 
  LogOut, 
  Search, 
  Plus, 
  FileSpreadsheet, 
  Users, 
  Package, 
  Loader2,
  RefreshCw,
  Download,
  ShieldCheck,
  Building2,
  Lock,
  Wifi,
  WifiOff,
  Smartphone,
  Filter,
  ChevronRight,
  Edit2,
  UserPlus,
  Trash2,
  Contact,
  X as CloseIcon
} from 'lucide-react';
import { USERS, TOOL_CATALOG, LOGO_URL } from './constants';
import { User, Transaction, UserRole } from './types';
import ToolModal from './components/ToolModal';
import AdminModal from './components/AdminModal';
import EmployeeModal from './components/EmployeeModal';
import AIChat from './components/AIChat';
import Login from './components/Login';
import EmployeeDashboard from './components/EmployeeDashboard';
import { fetchSheetData, saveTransactionToSheet, saveAdminToSheet, deleteAdminFromSheet, saveEmployeeToSheet, updateEmployeeStatusInSheet, SheetData } from './services/sheetService';
import { generateEmployeePDF } from './services/pdfService';

type Tab = 'employee' | 'directory' | 'daily' | 'stock' | 'admins';

const CACHE_KEY = 'sarbs_inventory_cache';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [allTransactions, setAllTransactions] = useState<Transaction[]>([]);
  const [fullEmployeeDirectory, setFullEmployeeDirectory] = useState<any[]>([]);
  const [availableTools, setAvailableTools] = useState<string[]>([]);
  const [sheetAdmins, setSheetAdmins] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSync, setLastSync] = useState<string>('');
  const [activeTab, setActiveTab] = useState<Tab>('employee');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedEmployee, setSelectedEmployee] = useState<any>(null);
  const [showSearchResults, setShowSearchResults] = useState(false);
  const searchRef = useRef<HTMLDivElement>(null);

  const [selectedDeptFilter, setSelectedDeptFilter] = useState<string>('');
  const [directoryDeptFilter, setDirectoryDeptFilter] = useState<string>('');
  const [directorySearchQuery, setDirectorySearchQuery] = useState<string>('');

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEmployeeModalOpen, setIsEmployeeModalOpen] = useState(false);
  const [isAdminModalOpen, setIsAdminModalOpen] = useState(false);
  const [editingAdmin, setEditingAdmin] = useState<User | null>(null);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [installPrompt, setInstallPrompt] = useState<any>(null);

  // --- Sync Logic ---

  const loadData = useCallback(async (isBackground = false) => {
    const hasExistingData = allTransactions.length > 0 || fullEmployeeDirectory.length > 0;

    if (!isBackground && !hasExistingData) {
      setIsLoading(true);
    } else {
      setIsSyncing(true);
    }

    try {
      const data = await fetchSheetData();

      setAllTransactions(data.transactions);
      setFullEmployeeDirectory(data.employees);
      setAvailableTools(data.tools);
      setSheetAdmins(data.admins);

      const timeStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      setLastSync(timeStr);

      localStorage.setItem(CACHE_KEY, JSON.stringify({
        ...data,
        cachedAt: timeStr,
        timestamp: Date.now()
      }));

    } catch (e) {
      console.error("Error loading data", e);
    } finally {
      setIsLoading(false);
      setTimeout(() => setIsSyncing(false), 800);
    }
  }, [allTransactions.length, fullEmployeeDirectory.length]);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const cached = localStorage.getItem(CACHE_KEY);
    if (cached) {
      try {
        const parsed: SheetData & { cachedAt: string } = JSON.parse(cached);
        setAllTransactions(parsed.transactions || []);
        setFullEmployeeDirectory(parsed.employees || []);
        setAvailableTools(parsed.tools || []);
        setSheetAdmins(parsed.admins || []);
        setLastSync(parsed.cachedAt || '');

        setIsLoading(false);
        loadData(true);
      } catch (e) {
        loadData(false);
      }
    } else {
      loadData(false);
    }

    const handleClickOutside = (event: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(event.target as Node)) {
        setShowSearchResults(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const handleInstallClick = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') setInstallPrompt(null);
  };

  // --- ACCESS CONTROLLED DATA ---

  const isSuperAdmin = useMemo(() => {
    if (!user) return false;
    const normalizedRole = user.role.toLowerCase().replace(/[\s_]/g, '');
    return normalizedRole === 'superadmin' || normalizedRole === 'super_admin';
  }, [user]);

  const isAdmin = useMemo(() => {
     if (!user) return false;
     return user.role === 'dept_admin' || isSuperAdmin;
  }, [user, isSuperAdmin]);

  const departments = useMemo(() => {
    const depts = new Set<string>();
    fullEmployeeDirectory.forEach(emp => {
      if (emp.department) depts.add(emp.department);
    });
    sheetAdmins.forEach(admin => {
       if (admin.department && admin.department !== 'All') depts.add(admin.department);
    });
    return Array.from(depts).sort();
  }, [fullEmployeeDirectory, sheetAdmins]);

  const visibleEmployees = useMemo(() => {
    if (!user) return [];
    if (isSuperAdmin) return fullEmployeeDirectory;
    return fullEmployeeDirectory.filter(emp => emp.department === user.department);
  }, [user, isSuperAdmin, fullEmployeeDirectory]);

  // Specific for Directory Tab filtering
  const filteredDirectory = useMemo(() => {
    let list = visibleEmployees;

    // Additional filters for Super Admin on Directory tab
    if (isSuperAdmin && directoryDeptFilter) {
      list = list.filter(emp => emp.department === directoryDeptFilter);
    }

    if (directorySearchQuery.trim()) {
      const q = directorySearchQuery.toLowerCase().trim();
      list = list.filter(emp => 
        String(emp.id).toLowerCase().includes(q) || 
        String(emp.name).toLowerCase().includes(q) ||
        String(emp.designation).toLowerCase().includes(q)
      );
    }

    return list;
  }, [visibleEmployees, isSuperAdmin, directoryDeptFilter, directorySearchQuery]);

  const visibleTransactions = useMemo(() => {
    if (!user) return [];
    if (isSuperAdmin) return allTransactions;
    return allTransactions.filter(trx => trx.department === user.department);
  }, [user, isSuperAdmin, allTransactions]);

  const searchResults = useMemo(() => {
    if (!searchQuery.trim()) return [];
    const query = searchQuery.toLowerCase().trim();
    return visibleEmployees.filter(emp => 
      String(emp.id).toLowerCase().includes(query) || 
      String(emp.name).toLowerCase().includes(query)
    ).slice(0, 10); 
  }, [searchQuery, visibleEmployees]);

  // --- Actions ---

  const handleSaveTransactions = async (transactions: Transaction[], employeeDetails?: any) => {
    if (!user) return;
    const enrichedTransactions = transactions.map(trx => ({
      ...trx,
      department: trx.entryType === 'Stock IN' ? user.department : (employeeDetails?.department || user.department)
    }));

    let newAllTransactions = [...allTransactions];
    enrichedTransactions.forEach(trx => {
      const index = newAllTransactions.findIndex(t => t.id === trx.id);
      if (index !== -1) newAllTransactions[index] = trx;
      else newAllTransactions.push(trx);
    });

    setAllTransactions(newAllTransactions);
    setIsSyncing(true);
    for (const trx of enrichedTransactions) {
      await saveTransactionToSheet(trx, employeeDetails || { department: user.department });
    }
    loadData(true);
  };

  const handleSaveEmployee = async (employeeData: any) => {
     setIsSyncing(true);
     const success = await saveEmployeeToSheet(employeeData);
     if (success) {
        setIsEmployeeModalOpen(false);
        loadData(true);
     } else {
        alert("Failed to save personnel to hub.");
        setIsSyncing(false);
     }
  };

  const handleUpdateEmployeeStatus = async (empId: string, newStatus: string) => {
    setIsSyncing(true);
    const success = await updateEmployeeStatusInSheet(empId, newStatus);
    if (success) {
      loadData(true);
    } else {
      alert("Failed to update personnel status.");
      setIsSyncing(false);
    }
  };

  const handleSaveAdmin = async (adminData: User) => {
    setIsSyncing(true);
    const success = await saveAdminToSheet(adminData);
    if (success) {
      setIsAdminModalOpen(false);
      setEditingAdmin(null);
      loadData(true);
    } else {
      alert("Failed to save administrator to Cloud Hub.");
      setIsSyncing(false);
    }
  };

  const handleDeleteAdmin = async (adminId: string, role: string) => {
    const normalizedRole = role.toLowerCase().replace(/[\s_]/g, '');
    if (normalizedRole === 'superadmin' || normalizedRole === 'super_admin') {
      alert("Security Protocol: Super Admin accounts cannot be deleted via the dashboard.");
      return;
    }

    if (!confirm(`Are you sure you want to revoke access for ID: ${adminId}?`)) return;

    setIsSyncing(true);
    const success = await deleteAdminFromSheet(adminId);
    if (success) {
      loadData(true);
    } else {
      alert("Failed to remove administrator from Cloud Hub.");
      setIsSyncing(false);
    }
  };

  const handleLogin = (u: { id: string, password?: string }) => {
    const inputId = String(u.id || '').trim();
    const inputPass = String(u.password || '').trim();

    if (!inputId) return alert("Please enter a valid Personnel ID.");

    const sheetAdmin = sheetAdmins.find(admin => 
      String(admin.id).trim() === inputId && String(admin.password).trim() === inputPass
    );

    if (sheetAdmin) {
      const rawRole = sheetAdmin.role.toLowerCase().replace(/[\s_]/g, '');
      setUser({ ...sheetAdmin, role: (rawRole === 'superadmin' || rawRole === 'super_admin') ? 'super_admin' : 'dept_admin' });
      return;
    }

    const sheetEmp = fullEmployeeDirectory.find(e => String(e.id).trim() === inputId);
    if (sheetEmp && inputPass === '12345') {
      setUser({
        id: String(sheetEmp.id).trim(),
        name: sheetEmp.name,
        role: 'employee',
        designation: sheetEmp.designation,
        department: sheetEmp.department,
        typeOfEmployee: sheetEmp.typeOfEmployee
      });
      return;
    }

    const foundFallback = USERS.find(existing => String(existing.id).trim() === inputId && String(existing.password).trim() === inputPass);
    if (foundFallback) return setUser(foundFallback);

    alert(`Authentication Failed. ID or Password may be incorrect.`);
  };

  const employeeToolsData = useMemo(() => {
    if (!selectedEmployee) return [];
    const empTrx = visibleTransactions.filter(t => t.employeeId === selectedEmployee.id);
    const toolsMap = new Map<string, any>();

    availableTools.forEach(name => {
       toolsMap.set(name, { name, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0, remarks: '' });
    });

    empTrx.forEach(t => {
      let tool = toolsMap.get(t.toolName);
      if (!tool) {
         tool = { name: t.toolName, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0, remarks: '' };
         toolsMap.set(t.toolName, tool);
      }
      if (t.entryType === 'Distribute') tool.distributed += t.quantity;
      if (t.entryType === 'Return') tool.returned += t.quantity;
      if (t.entryType === 'Faulty Return') tool.faulty += t.quantity;
      if (t.entryType === 'Damage') tool.damage += t.quantity;
      if (t.entryType === 'Lost') tool.lost += t.quantity;
      if (t.remarks) tool.remarks = t.remarks;
    });

    return Array.from(toolsMap.values()).filter(t => t.distributed > 0);
  }, [selectedEmployee, visibleTransactions, availableTools]);

  const stockSummaryData = useMemo(() => {
    let targetTrx = allTransactions;
    if (!isSuperAdmin) targetTrx = visibleTransactions;
    else if (selectedDeptFilter !== '') targetTrx = allTransactions.filter(t => t.department === selectedDeptFilter);

    const allNames = Array.from(new Set([...TOOL_CATALOG.map(c => c.name), ...availableTools])).sort();
    return allNames.map(name => {
      const toolTrx = targetTrx.filter(t => t.toolName === name);
      let purchase = 0, distributed = 0, returned = 0, faulty = 0, damage = 0, lost = 0;
      toolTrx.forEach(t => {
        if (t.entryType === 'Stock IN') purchase += t.quantity;
        if (t.entryType === 'Distribute') distributed += t.quantity;
        if (t.entryType === 'Return') returned += t.quantity;
        if (t.entryType === 'Faulty Return') faulty += t.quantity;
        if (t.entryType === 'Damage') damage += t.quantity;
        if (t.entryType === 'Lost') lost += t.quantity;
      });
      return {
        name, purchase, distributed, returned, faulty, damage, lost,
        stockNow: purchase - distributed + returned
      };
    }).filter(tool => tool.purchase > 0 || tool.distributed > 0);
  }, [allTransactions, visibleTransactions, availableTools, isSuperAdmin, selectedDeptFilter]);

  // --- Render ---

  if (isLoading) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center gap-6 p-10 text-center">
        <img src={LOGO_URL} alt="SARBS Logo" className="w-24 h-24 object-contain animate-pulse" />
        <div>
           <p className="text-slate-900 font-black text-xl tracking-tight uppercase">SARBS Inventory Hub</p>
           <p className="text-slate-500 text-sm mt-1 font-bold uppercase tracking-widest">Accessing Secure Records...</p>
        </div>
      </div>
    );
  }

  if (!user) return <Login onLogin={handleLogin} isSyncing={isSyncing} lastSync={lastSync} onRefresh={() => loadData(true)} isOnline={isOnline} installPrompt={installPrompt} onInstall={handleInstallClick} />;

  if (user.role === 'employee') {
    return <EmployeeDashboard user={user} transactions={visibleTransactions} onLogout={() => setUser(null)} />;
  }

  return (
    <div className="min-h-screen bg-[#F0F4F8] font-sans text-slate-900 pb-20 safe-top">
      {!isOnline && (
        <div className="bg-red-600 text-white text-[10px] font-black uppercase tracking-widest py-2 text-center sticky top-0 z-50 animate-pulse">
          Connection Interrupted - Changes will sync later
        </div>
      )}

      {/* Modern Header - Screenshot Aligned */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 px-6 py-3">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3 w-1/4">
            <img src={LOGO_URL} alt="SARBS" className="w-12 h-12 object-contain" />
          </div>

          <div className="flex items-center justify-center gap-8 w-2/4">
            {[
              { id: 'employee', label: 'LOOKUP', icon: Search },
              { id: 'directory', label: 'DIRECTORY', icon: Users },
              { id: 'daily', label: 'LOGS', icon: FileSpreadsheet },
              { id: 'stock', label: 'INVENTORY', icon: Package },
              ...(isSuperAdmin ? [{ id: 'admins', label: 'ACCESS', icon: ShieldCheck }] : [])
            ].map((tab) => (
              <button 
                key={tab.id} 
                onClick={() => setActiveTab(tab.id as Tab)} 
                className={`px-2 py-4 text-xs font-black transition-all flex items-center gap-2 border-b-4 ${activeTab === tab.id ? 'border-slate-900 text-slate-900' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
              >
                <tab.icon className="w-4 h-4" /> {tab.label}
              </button>
            ))}
          </div>

          <div className="flex items-center justify-end gap-4 w-1/4">
             <button onClick={() => loadData(true)} className={`p-2 rounded-full hover:bg-slate-100 ${isSyncing ? 'animate-spin text-blue-500' : 'text-slate-400'}`}>
               <RefreshCw className="w-5 h-5" />
             </button>
             <div className="flex items-center gap-2 bg-[#0F172A] px-5 py-2.5 rounded-full text-white shadow-lg">
                <ShieldCheck className="w-4 h-4 text-blue-400" />
                <span className="text-xs font-black uppercase tracking-wider">{isSuperAdmin ? 'Super Admin' : 'Admin'}</span>
             </div>
             <button onClick={() => setUser(null)} className="p-2 text-slate-400 hover:text-red-600 transition-colors">
               <LogOut className="w-6 h-6" />
             </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-8">
        {activeTab === 'employee' && (
          <div className="space-y-6">
             <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col md:flex-row justify-between items-center gap-4">
                <div className="w-full sm:max-w-md relative" ref={searchRef}>
