                            </td>
                            <td className="px-8 py-4 text-center font-black text-slate-900">{trx.quantity}</td>
                            <td className="px-8 py-4 text-slate-400 italic truncate max-w-[200px]">{trx.remarks}</td>
                         </tr>
                      ))}
                   </tbody>
                </table>
              </div>
           </div>
        )}

        {activeTab === 'stock' && (
           <div className="space-y-4">
              <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row justify-between gap-4">
                 <div>
                    <h2 className="text-base font-black text-slate-900 uppercase tracking-tight">Asset Ledger</h2>
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">{isSuperAdmin ? 'Master Reconciliation' : user.department}</p>
                 </div>
                 {isSuperAdmin && (
                   <div className="flex flex-col min-w-[240px]">
                      <label className="text-[9px] font-black text-slate-400 uppercase mb-1 tracking-widest">Filter</label>
                      <select className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-black" value={selectedDeptFilter} onChange={(e) => setSelectedDeptFilter(e.target.value)}>
                        <option value="">All Departments</option>
                        {departments.map(dept => <option key={dept} value={dept}>{dept}</option>)}
                      </select>
                   </div>
                 )}
              </div>
              <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden overflow-x-auto">
                 <table className="w-full text-[11px] text-center border-collapse min-w-[900px]">
                    <thead className="bg-[#F8FAFC] text-slate-500 border-b border-slate-200 uppercase font-black">
                       <tr>
                          <th className="px-4 py-5 text-left border-r border-slate-200 min-w-[200px]">Tools Name</th>
                          <th className="px-2 py-5 border-r border-slate-200">Purchase</th>
                          <th className="px-2 py-5 border-r border-slate-200">Dist. Qty</th>
                          <th className="px-2 py-5 border-r border-slate-200">Ret. Qty</th>
                          <th className="px-2 py-5 border-r border-slate-200 text-amber-600">Faulty</th>
                          <th className="px-2 py-5 border-r border-slate-200 text-red-500">Damage</th>
                          <th className="px-2 py-5 border-r border-slate-200 text-red-700">Lost</th>
                          <th className="px-4 py-5 bg-slate-900 text-white font-black">Stock Now</th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                       {stockSummaryData.map((row) => (
                          <tr key={row.name} className="hover:bg-slate-50">
                             <td className="px-4 py-5 text-left font-black text-slate-900 border-r border-slate-100">{row.name}</td>
                             <td className="px-2 py-5 font-bold text-slate-500 border-r border-slate-100">{row.purchase || 0}</td>
                             <td className="px-2 py-5 font-bold text-slate-500 border-r border-slate-100">{row.distributed || 0}</td>
                             <td className="px-2 py-5 font-bold text-slate-500 border-r border-slate-100">{row.returned || 0}</td>
                             <td className="px-2 py-5 font-bold text-amber-600 border-r border-slate-100">{row.faulty || 0}</td>
                             <td className="px-2 py-5 font-bold text-red-500 border-r border-slate-100">{row.damage || 0}</td>
                             <td className="px-2 py-5 font-bold text-red-600 border-r border-slate-100">{row.lost || 0}</td>
                             <td className="px-4 py-5 font-black bg-slate-50 text-base text-slate-900">{row.stockNow}</td>
                          </tr>
                       ))}
                    </tbody>
                 </table>
              </div>
           </div>
        )}

        {activeTab === 'admins' && isSuperAdmin && (
           <div className="space-y-4">
              <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col sm:flex-row justify-between items-center gap-4">
                 <div>
                    <h2 className="text-base font-black text-slate-900 uppercase tracking-tight flex items-center gap-2">
                       <Lock className="w-5 h-5 text-indigo-600" /> Access List
                    </h2>
                 </div>
                 <button onClick={() => { setEditingAdmin(null); setIsAdminModalOpen(true); }} className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-2.5 rounded-xl shadow-lg font-black text-xs transition-all active:scale-95 uppercase tracking-widest w-full sm:w-auto justify-center">
                    <UserPlus className="w-4 h-4" /> ADD ADMIN
                 </button>
              </div>
              <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden overflow-x-auto">
                 <table className="w-full text-xs text-left min-w-[800px]">
                    <thead className="bg-[#F8FAFC] text-slate-400 border-b uppercase font-black tracking-widest">
                       <tr>
                          <th className="px-8 py-5">Personnel ID</th>
                          <th className="px-8 py-5">Name</th>
                          <th className="px-8 py-5">Role</th>
                          <th className="px-8 py-5">Department</th>
                          <th className="px-8 py-5">Designation</th>
                          <th className="px-8 py-5 text-center">Action</th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                       {sheetAdmins.map((admin) => {
                          const isSuper = admin.role.toLowerCase().replace(/[\s_]/g, '') === 'superadmin' || admin.role.toLowerCase().replace(/[\s_]/g, '') === 'super_admin';
                          return (
                            <tr key={admin.id} className="hover:bg-indigo-50/50 transition-colors">
                               <td className="px-8 py-5 font-mono font-black text-slate-500">{admin.id}</td>
                               <td className="px-8 py-5 font-black text-slate-900 text-base">{admin.name}</td>
                               <td className="px-8 py-5">
                                  <span className={`px-2.5 py-1.5 rounded-lg text-[9px] font-black uppercase border ${isSuper ? 'bg-indigo-900 text-white border-indigo-950 shadow-md' : 'bg-white text-amber-600 border-amber-200'}`}>
                                     {admin.role.replace(/_/g, ' ')}
                                  </span>
                               </td>
                               <td className="px-8 py-5 text-slate-600 font-black uppercase text-[10px]">{admin.department}</td>
                               <td className="px-8 py-5 text-slate-400 font-bold">{admin.designation}</td>
                               <td className="px-8 py-5 text-center flex items-center justify-center gap-2">
                                  <button onClick={() => { setEditingAdmin(admin); setIsAdminModalOpen(true); }} className="p-2 hover:bg-white rounded-lg text-slate-400 hover:text-indigo-600 transition-colors border border-transparent hover:border-slate-200"><Edit2 className="w-4 h-4" /></button>
                                  <button onClick={() => handleDeleteAdmin(admin.id, admin.role)} disabled={isSuper} className={`p-2 rounded-lg transition-colors border border-transparent ${isSuper ? 'text-slate-200 cursor-not-allowed' : 'text-slate-400 hover:text-red-600 hover:bg-white hover:border-slate-200'}`}><Trash2 className="w-4 h-4" /></button>
                               </td>
                            </tr>
                          );
                       })}
                    </tbody>
                 </table>
              </div>
           </div>
        )}
      </main>

      <ToolModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveTransactions} initialTransaction={editingTransaction} employees={visibleEmployees} availableTools={availableTools} />
      <EmployeeModal isOpen={isEmployeeModalOpen} onClose={() => setIsEmployeeModalOpen(false)} onSave={handleSaveEmployee} isAdmin={isAdmin} isSuperAdmin={isSuperAdmin} userDepartment={user?.department || ''} allDepartments={departments} />
      <AdminModal isOpen={isAdminModalOpen} onClose={() => { setIsAdminModalOpen(false); setEditingAdmin(null); }} onSave={handleSaveAdmin} initialData={editingAdmin} departments={departments} />
      <AIChat inventory={stockSummaryData} />
    </div>
  );
};

export default App;

