               <h1 className="text-lg font-bold text-slate-900">My Tools</h1>
               <p className="text-xs text-slate-500">Employee Portal</p>
             </div>
          </div>
          <div className="flex items-center gap-2 sm:gap-4">
             <div className="text-right hidden sm:block">
               <div className="text-sm font-semibold text-slate-800">{user.name}</div>
               <div className="text-xs text-slate-500">{user.id}</div>
             </div>
             <button 
               onClick={() => setIsPassModalOpen(true)}
               className="text-[10px] sm:text-xs font-black uppercase tracking-widest text-blue-600 bg-blue-50 hover:bg-blue-100 px-3 py-2 rounded-lg transition-colors flex items-center gap-1.5"
             >
               <Key className="w-3 h-3" /> <span className="hidden xs:inline">Security</span>
