            </p>
          </div>
          <button 
             onClick={() => generateEmployeePDF(user, employeeToolsData)}
             className="relative z-10 bg-white/10 hover:bg-white/20 text-white border border-white/20 px-4 py-3 rounded-lg flex items-center gap-2 transition-colors font-bold text-sm backdrop-blur-sm"
          >
             <Download className="w-4 h-4" /> Download Detailed Report (PDF)
          </button>
        </div>

        <div>
           <div className="flex items-center gap-2 mb-4">
             <CheckCircle className="w-5 h-5 text-green-600" />
             <h3 className="text-lg font-bold text-slate-800 uppercase tracking-tight">Active Inventory Summary</h3>
