               ))}
             </div>
           ) : (
             <div className="text-center py-20 bg-white rounded-xl border border-dashed border-slate-300">
               <Package className="w-10 h-10 text-slate-200 mx-auto mb-2" />
               <p className="text-slate-400 font-medium">No tools currently assigned to your ID.</p>
             </div>
           )}
        </div>
      </main>

      {/* Password Request Modal */}
      {isPassModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
           <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">
              <div className="bg-blue-900 p-6 flex justify-between items-center text-white">
                 <div className="flex items-center gap-2">
                    <Key className="w-5 h-5 text-blue-300" />
                    <h2 className="text-sm font-black uppercase tracking-widest">Security Customization</h2>
                 </div>
                 <button onClick={() => setIsPassModalOpen(false)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                    <X className="w-5 h-5" />
                 </button>
              </div>

              <div className="p-6">
                 {successMsg ? (
                    <div className="bg-green-50 text-green-700 p-6 rounded-2xl border border-green-200 text-center animate-in fade-in duration-300">
                       <CheckCircle className="w-10 h-10 mx-auto mb-3 text-green-500" />
                       <p className="font-bold text-sm">{successMsg}</p>
