                 ) : (
                    <form onSubmit={handlePasswordRequest} className="space-y-4">
                       <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest leading-relaxed">
                          Request to change your login password. Your new password will be active once a Super Admin approves the request.
                       </p>
                       <div>
                          <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">Desired New Password</label>
