export default App;

import { Transaction, User } from '../types';
import { GOOGLE_SCRIPT_URL as RAW_URL, INITIAL_TRANSACTIONS, USERS, TOOL_CATALOG } from '../constants';

const GOOGLE_SCRIPT_URL = RAW_URL.trim();

const HEADERS = {
  'Content-Type': 'text/plain;charset=utf-8', 
};

export interface SheetData {
  transactions: Transaction[];
  employees: any[];
  tools: string[];
  admins: User[];
}

export const fetchSheetData = async (): Promise<SheetData> => {
  if (!GOOGLE_SCRIPT_URL) {
    return { 
      transactions: INITIAL_TRANSACTIONS, 
      employees: USERS.filter(u => u.role === 'employee'), 
      tools: TOOL_CATALOG.map(t => t.name),
      admins: USERS.filter(u => u.role !== 'employee')
    };
  }

  try {
    const response = await fetch(`${GOOGLE_SCRIPT_URL}?action=getFullData&t=${Date.now()}`);
    if (!response.ok) throw new Error('Network response was not ok');
    const data = await response.json();
    return {
      transactions: data.transactions || [],
      employees: data.employees || [],
      tools: data.tools || [],
      admins: data.admins || []
    };
  } catch (error) {
    console.error("Failed to fetch sheet data:", error);
    return { 
      transactions: INITIAL_TRANSACTIONS, 
      employees: [], 
      tools: TOOL_CATALOG.map(t => t.name),
      admins: USERS
    };
  }
};

export const saveTransactionToSheet = async (transaction: Transaction, user?: any): Promise<boolean> => {
  if (!GOOGLE_SCRIPT_URL) return Promise.resolve(true);
  try {
    const payload = {
      action: 'addTransaction',
      payload: {
        ...transaction,
        employeeName: user?.name,
        designation: user?.designation,
        department: user?.department,
        typeOfEmployee: user?.typeOfEmployee
      }
    };
    const response = await fetch(GOOGLE_SCRIPT_URL, {
      method: 'POST',
      headers: HEADERS,
      body: JSON.stringify(payload)
    });
    const result = await response.json();
    return result.status === 'success';
  } catch (error) {
    console.error("Failed to save transaction:", error);
    return false;
  }
};

export const saveEmployeeToSheet = async (employee: any): Promise<boolean> => {
  if (!GOOGLE_SCRIPT_URL) return Promise.resolve(true);
  try {
    const payload = {
      action: 'addEmployee',
      payload: employee
    };
    const response = await fetch(GOOGLE_SCRIPT_URL, {
      method: 'POST',
      headers: HEADERS,
      body: JSON.stringify(payload)
    });
    const result = await response.json();
    return result.status === 'success';
  } catch (error) {
    console.error("Failed to save employee:", error);
    return false;
  }
};

export const updateEmployeeStatusInSheet = async (empId: string, status: string): Promise<boolean> => {
  if (!GOOGLE_SCRIPT_URL) return Promise.resolve(true);
  try {
    const payload = {
      action: 'updateEmployeeStatus',
      payload: { id: empId, status }
    };
    const response = await fetch(GOOGLE_SCRIPT_URL, {
      method: 'POST',
      headers: HEADERS,
      body: JSON.stringify(payload)
    });
    const result = await response.json();
    return result.status === 'success';
  } catch (error) {
    console.error("Failed to update status:", error);
    return false;
  }
};

export const requestEmployeePasswordChange = async (empId: string, newPassword: string): Promise<{ success: boolean, message?: string }> => {
  if (!GOOGLE_SCRIPT_URL) return { success: false, message: "URL not configured" };
  try {
    const payload = {
      action: 'requestPasswordChange',
      payload: { id: empId, newPassword }
    };

    // We use a simplified fetch for GAS POST to avoid CORS Preflight (OPTIONS) which GAS doesn't support
    const response = await fetch(GOOGLE_SCRIPT_URL, {
      method: 'POST',
      headers: HEADERS, // text/plain is key here
      body: JSON.stringify(payload),
      redirect: 'follow'
    });

    const text = await response.text();
    let result;
    try {
      result = JSON.parse(text);
    } catch (e) {
      console.error("Non-JSON response from script:", text);
      return { success: false, message: "Server returned invalid format. Check Script Deployment." };
    }

    return { 
      success: result.status === 'success', 
      message: result.message 
    };
  } catch (error) {
    console.error("Network Error:", error);
    return { success: false, message: "Network connection failure." };
  }
};

