import React, { useMemo, useState } from 'react';
import { User, Transaction } from '../types';
import { Package, Clock, AlertCircle, CheckCircle, Download, Key, X, Send, Loader2, History } from 'lucide-react';
import { generateEmployeePDF } from '../services/pdfService';
import { LOGO_URL } from '../constants';
import { requestEmployeePasswordChange } from '../services/sheetService';

interface EmployeeDashboardProps {
  user: User;
  transactions: Transaction[]; 
  onLogout: () => void;
  isSyncing?: boolean;
}

const EmployeeDashboard: React.FC<EmployeeDashboardProps> = ({ user, transactions, onLogout, isSyncing = false }) => {
  const [isPassModalOpen, setIsPassModalOpen] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [successMsg, setSuccessMsg] = useState('');

  const employeeToolsData = useMemo(() => {
    const empTrx = transactions.filter(t => t.employeeId === user.id);
    const toolsMap = new Map<string, any>();

    empTrx.forEach(t => {
      let tool = toolsMap.get(t.toolName);
      if (!tool) {
         tool = { name: t.toolName, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0, remarks: '' };
         toolsMap.set(t.toolName, tool);
      }
      if (t.entryType === 'Distribute') tool.distributed += t.quantity;
      if (t.entryType === 'Return') tool.returned += t.quantity;
      if (t.entryType === 'Faulty Return') tool.faulty += t.quantity;
      if (t.entryType === 'Damage') tool.damage += t.quantity;
      if (t.entryType === 'Lost') tool.lost += t.quantity;
      if (t.remarks) tool.remarks = t.remarks;
    });

    return Array.from(toolsMap.values()).filter(t => t.distributed > 0);
  }, [user, transactions]);

  const recentHistory = useMemo(() => {
    return transactions
      .filter(t => t.employeeId === user.id)
      .reverse()
      .slice(0, 10);
  }, [user, transactions]);

  const handlePasswordRequest = async (e: React.FormEvent) => {
    e.preventDefault();
    const cleanPass = newPassword.trim();
    if (!cleanPass) return;

    setIsSubmitting(true);
    try {
      const result = await requestEmployeePasswordChange(user.id, cleanPass);

      if (result.success) {
        setSuccessMsg('Request sent! Super Admin approval is required for activation.');
        setNewPassword('');
        setTimeout(() => {
          setIsPassModalOpen(false);
          setSuccessMsg('');
        }, 3000);
      } else {
        alert(`Communication Failed: ${result.message || 'The authentication script did not acknowledge the request.'}`);
      }
    } catch (err) {
      alert("System could not reach the Cloud Hub. Please verify your internet connection.");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-20 shadow-sm">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="flex items-center justify-center">
               <img src={LOGO_URL} alt="SARBS" className="w-10 h-10 object-contain" />
             </div>
             <div>
               <h1 className="text-lg font-bold text-slate-900">Inventory Hub</h1>
               <p className="text-[10px] text-slate-500 font-bold uppercase tracking-tight">Personnel Portal</p>
             </div>
          </div>
          <div className="flex items-center gap-2 sm:gap-4">
             <div className="text-right hidden sm:block">
               <div className="text-sm font-black text-slate-800">{user.name}</div>
               <div className="text-[10px] text-slate-400 font-bold">{user.id}</div>
             </div>
             <button onClick={() => setIsPassModalOpen(true)} className="text-[10px] sm:text-xs font-black uppercase tracking-widest text-blue-600 bg-blue-50 hover:bg-blue-100 px-3 py-2 rounded-lg transition-colors flex items-center gap-1.5 border border-blue-100">
               <Key className="w-3 h-3" /> Security
             </button>
             <button onClick={onLogout} className="text-[10px] sm:text-xs font-black uppercase tracking-widest text-red-600 bg-red-50 hover:bg-red-100 px-3 py-2 rounded-lg transition-colors border border-red-100">
               Sign Out
             </button>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">
        <div className="bg-slate-900 rounded-3xl p-8 text-white shadow-2xl flex justify-between items-center flex-wrap gap-6 relative overflow-hidden">
          <div className="absolute top-0 right-0 w-80 h-80 bg-blue-500/10 rounded-full -mr-40 -mt-40 blur-3xl"></div>
          <div className="relative z-10">
            <h2 className="text-2xl font-black mb-2 uppercase tracking-tight">Active Ledger: {user.name}</h2>
            <p className="text-slate-400 text-sm font-medium">
              Unit: <span className="text-white font-black">{user.department}</span> • Position: <span className="text-white font-black">{user.designation}</span>
            </p>
          </div>
          <button onClick={() => generateEmployeePDF(user, employeeToolsData)} className="relative z-10 bg-white hover:bg-slate-100 text-slate-900 px-6 py-3 rounded-2xl flex items-center gap-3 transition-all font-black text-xs uppercase tracking-widest shadow-xl active:scale-95">
             <Download className="w-4 h-4" /> Export Tools Report (PDF)
          </button>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-8">
            <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
               <div className="px-8 py-6 border-b border-slate-100 flex items-center gap-3 bg-slate-50/50">
                 <div className="bg-green-100 p-2 rounded-lg"><CheckCircle className="w-5 h-5 text-green-600" /></div>
                 <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest">Current Inventory Summary</h3>
               </div>

               <div className="overflow-x-auto">
                  <table className="w-full text-xs text-center border-collapse min-w-[800px]">
                    <thead className="bg-[#F8FAFC] border-b border-slate-200 text-slate-500 uppercase tracking-widest font-black">
                      <tr>
                        <th className="px-8 py-5 text-left">Tools Name</th>
                        <th className="px-4 py-5 border-l border-slate-100">Dist.</th>
                        <th className="px-4 py-5 border-l border-slate-100">Ret.</th>
                        <th className="px-6 py-5 border-l border-slate-100 bg-green-50 text-green-900">Final Qty</th>
                        <th className="px-6 py-5 border-l border-slate-100 text-left">Remarks</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {employeeToolsData.length > 0 ? employeeToolsData.map((row) => (
                        <tr key={row.name} className="hover:bg-slate-50 transition-colors">
                          <td className="px-8 py-5 text-left font-black text-slate-800 text-sm">{row.name}</td>
                          <td className="px-4 py-5 border-l border-slate-100 font-bold text-slate-500">{row.distributed || '0'}</td>
                          <td className="px-4 py-5 border-l border-slate-100 font-bold text-slate-500">{row.returned || '0'}</td>
                          <td className="px-6 py-5 border-l border-slate-100 font-black bg-green-50 text-green-700 text-base">
                            {(row.distributed - row.returned - row.faulty - row.damage - row.lost)}
                          </td>
                          <td className="px-6 py-5 border-l border-slate-100 text-left text-slate-400 italic font-medium truncate max-w-xs">{row.remarks || '-'}</td>
                        </tr>
                      )) : (
                        <tr><td colSpan={5} className="py-20 text-slate-400 font-black uppercase italic tracking-widest text-sm text-center">No active assets.</td></tr>
                      )}
                    </tbody>
                  </table>
               </div>
            </div>
          </div>

          <div className="lg:col-span-1">
            <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden sticky top-24">
              <div className="px-6 py-5 border-b border-slate-100 flex items-center gap-3 bg-slate-900 text-white">
                <History className="w-5 h-5 text-blue-400" />
                <h3 className="text-xs font-black uppercase tracking-widest">Recent Activity Log</h3>
              </div>
              <div className="p-4 space-y-4 max-h-[600px] overflow-y-auto">
                {recentHistory.length > 0 ? recentHistory.map((trx) => (
                  <div key={trx.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 space-y-2 relative group hover:bg-white transition-all">
                    <div className="flex justify-between items-start">
                      <span className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">{trx.date}</span>
                      <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase border ${
                        trx.entryType === 'Distribute' ? 'bg-green-100 text-green-700 border-green-200' :
                        trx.entryType === 'Return' ? 'bg-blue-100 text-blue-700 border-blue-200' :
                        'bg-red-100 text-red-700 border-red-200'
                      }`}>
                        {trx.entryType}
                      </span>
                    </div>
                    <div className="font-black text-xs text-slate-800">{trx.toolName}</div>
                    <div className="flex items-center justify-between">
                      <span className="text-[10px] text-slate-500 font-bold italic truncate max-w-[70%]">{trx.remarks || 'No remarks'}</span>
                      <span className="font-black text-xs">Qty: {trx.quantity}</span>
                    </div>
                  </div>
                )) : (
                  <div className="py-10 text-center text-slate-300 font-black uppercase text-[10px]">No recent transactions</div>
                )}
              </div>
            </div>
          </div>
        </div>
      </main>

      {/* Password Request Modal */}
      {isPassModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
           <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden flex flex-col animate-in zoom-in-95 duration-200 border border-slate-200">
              <div className="bg-slate-900 p-6 flex justify-between items-center text-white">
                 <div className="flex items-center gap-2">
                    <div className="bg-blue-500 p-1.5 rounded-lg"><Key className="w-4 h-4 text-white" /></div>
                    <h2 className="text-xs font-black uppercase tracking-widest">Security Protocol</h2>
                 </div>
                 <button onClick={() => setIsPassModalOpen(false)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                    <X className="w-5 h-5" />
                 </button>
              </div>

              <div className="p-8">
                 {successMsg ? (
                    <div className="bg-green-50 text-green-700 p-8 rounded-3xl border border-green-200 text-center animate-in fade-in duration-300">
                       <CheckCircle className="w-12 h-12 mx-auto mb-4 text-green-500" />
                       <p className="font-black text-sm uppercase tracking-tight">{successMsg}</p>
                    </div>
                 ) : (
                    <form onSubmit={handlePasswordRequest} className="space-y-6">
                       <div className="bg-blue-50 p-4 rounded-2xl border border-blue-100 text-[10px] text-blue-700 font-black uppercase tracking-widest leading-relaxed">
                          SUBMIT A NEW PASSWORD. REQUESTS REQUIRE APPROVAL BY GLOBAL ADMINISTRATION BEFORE ACTIVATION.
                       </div>
                       <div>
                          <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">New Security Password</label>
                          <input type="text" required minLength={4} className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-black text-sm transition-all shadow-inner focus:border-blue-500" placeholder="MIN 4 CHARACTERS" value={newPassword} onChange={(e) => setNewPassword(e.target.value)} />
                       </div>
                       <button type="submit" disabled={isSubmitting || !newPassword} className="w-full py-4 bg-slate-900 hover:bg-black disabled:bg-slate-300 text-white font-black rounded-2xl text-xs uppercase tracking-[0.2em] shadow-2xl flex items-center justify-center gap-3 transition-all active:scale-95">
                          {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
                          {isSubmitting ? 'TRANSMITTING...' : 'COMMIT REQUEST'}
                       </button>
                    </form>
                 )}
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default EmployeeDashboard;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Transaction, EntryType } from '../types';
import { X, Calendar, Wrench, Plus, Trash2, Hash, Zap, Search, ChevronRight, CheckCircle2, MessageSquareText } from 'lucide-react';
import { TOOL_CATALOG } from '../constants';

interface ToolItem {
  toolName: string;
  quantity: number;
  condition: 'New' | 'Used';
  remarks: string; // Per-item remarks
  searchQuery: string;
  showDropdown: boolean;
}

interface ToolModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (transactions: Transaction[], employeeDetails?: any) => void;
  initialTransaction?: Transaction | null;
  employees: any[]; 
  availableTools: string[];
}

const ToolModal: React.FC<ToolModalProps> = ({ 
  isOpen, 
  onClose, 
  onSave, 
  initialTransaction, 
  employees = [], 
  availableTools = [] 
}) => {

  const [date, setDate] = useState('');
  const [entryType, setEntryType] = useState<EntryType>('Distribute');
  const [employeeId, setEmployeeId] = useState('');
  const [employeeSearchQuery, setEmployeeSearchQuery] = useState('');
  const [showEmployeeResults, setShowEmployeeResults] = useState(false);
  const [globalRemarks, setGlobalRemarks] = useState('');
  const [toolItems, setToolItems] = useState<ToolItem[]>([
    { toolName: '', quantity: 1, condition: 'New', remarks: '', searchQuery: '', showDropdown: false }
  ]);

  const searchRef = useRef<HTMLDivElement>(null);
  const toolRefs = useRef<(HTMLDivElement | null)[]>([]);

  const masterToolList = useMemo(() => {
    const cloudTools = availableTools || [];
    const localTools = TOOL_CATALOG.map(t => t.name);
    return Array.from(new Set([...cloudTools, ...localTools])).filter(t => t.trim() !== '').sort();
  }, [availableTools]);

  const entryTypes: EntryType[] = ['Distribute', 'Return', 'Faulty Return', 'Damage', 'Lost', 'Stock IN'];

  const selectedEmployee = useMemo(() => 
    employees.find(e => String(e.id).trim() === employeeId),
    [employees, employeeId]
  );

  useEffect(() => {
    if (initialTransaction) {
      setDate(initialTransaction.date);
      setEntryType(initialTransaction.entryType);
      setEmployeeId(initialTransaction.employeeId || '');
      const emp = employees.find(e => e.id === initialTransaction.employeeId);
      setEmployeeSearchQuery(emp ? `${emp.id} - ${emp.name}` : initialTransaction.employeeId || '');
      setGlobalRemarks(initialTransaction.remarks || '');
      setToolItems([{
        toolName: initialTransaction.toolName,
        quantity: initialTransaction.quantity,
        condition: initialTransaction.condition as any,
        remarks: initialTransaction.remarks || '',
        searchQuery: initialTransaction.toolName,
        showDropdown: false
      }]);
    } else {
      setDate(new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: '2-digit' }).replace(/ /g, '-'));
      setEntryType('Distribute');
      setEmployeeId('');
      setEmployeeSearchQuery('');
      setGlobalRemarks('');
      setToolItems([{ toolName: '', quantity: 1, condition: 'New', remarks: '', searchQuery: '', showDropdown: false }]);
    }
  }, [initialTransaction, isOpen, employees]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(event.target as Node)) {
        setShowEmployeeResults(false);
      }
      toolRefs.current.forEach((ref, index) => {
        if (ref && !ref.contains(event.target as Node)) {
          updateToolItem(index, { showDropdown: false });
        }
      });
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const filteredEmployees = useMemo(() => {
    if (!employeeSearchQuery.trim()) return [];
    const q = employeeSearchQuery.toLowerCase().trim();
    return employees.filter(emp => 
      String(emp.id).toLowerCase().includes(q) || 
      String(emp.name).toLowerCase().includes(q)
    ).slice(0, 5);
  }, [employeeSearchQuery, employees]);

  const getFilteredTools = (query: string) => {
    const q = query.toLowerCase().trim();
    if (!q) return masterToolList;
    return masterToolList.filter(t => t.toLowerCase().includes(q));
  };

  const updateToolItem = (index: number, updates: Partial<ToolItem>) => {
    setToolItems(prev => {
      const next = [...prev];
      if (!next[index]) return prev;
      next[index] = { ...next[index], ...updates };
      return next;
    });
  };

  const selectTool = (index: number, name: string) => {
    updateToolItem(index, { 
      toolName: name, 
      searchQuery: name, 
      showDropdown: false 
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const isValid = toolItems.every(item => item.toolName.trim() !== '');
    if (!isValid) {
      alert("Validation Error: Please select a valid tool name from the list for all entries.");
      return;
    }

    const transactions: Transaction[] = toolItems.map((item, idx) => ({
      id: initialTransaction && idx === 0 ? initialTransaction.id : `${Date.now()}-${idx}`,
      date,
      entryType,
      employeeId,
      remarks: item.remarks ? `${globalRemarks} [${item.remarks}]`.trim() : globalRemarks,
      toolName: item.toolName,
      quantity: item.quantity,
      condition: item.condition
    } as Transaction));

    onSave(transactions, selectedEmployee);
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-3xl overflow-hidden flex flex-col max-h-[90vh] animate-in zoom-in-95 duration-200">
        <div className="bg-slate-900 p-6 flex justify-between items-center text-white shrink-0">
          <div>
            <h2 className="text-sm font-black tracking-[0.2em] uppercase flex items-center gap-2">
              <Zap className="w-4 h-4 text-blue-400" />
              {initialTransaction ? 'Edit Log Entry' : 'Log New Transaction'}
            </h2>
            <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">SARBS Communications Ltd.</p>
          </div>
          <button onClick={onClose} className="hover:bg-white/10 p-2 rounded-xl transition-colors">
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="overflow-y-auto p-6 space-y-6 bg-slate-50/50">
          <form onSubmit={handleSubmit} className="space-y-6">

            <div className="grid grid-cols-2 gap-4">
               <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Entry Date</label>
                  <div className="relative">
                     <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                     <input
                      required
                      type="text"
                      className="w-full pl-10 pr-3 py-3 bg-white border border-slate-200 rounded-xl focus:ring-4 focus:ring-blue-50 focus:border-blue-500 outline-none font-black text-sm transition-all"
                      placeholder="12-May-24"
                      value={date}
                      onChange={e => setDate(e.target.value)}
                    />
                  </div>
               </div>
               <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Transaction Type</label>
                  <select
                    className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl focus:ring-4 focus:ring-blue-50 focus:border-blue-500 outline-none font-black text-sm cursor-pointer"
                    value={entryType}
                    onChange={e => setEntryType(e.target.value as EntryType)}
                  >
                    {entryTypes.map(t => (
                      <option key={t} value={t}>{t}</option>
                    ))}
                  </select>
               </div>
            </div>

            {entryType !== 'Stock IN' && (
               <div className="p-4 bg-white rounded-2xl border border-slate-200 space-y-4 shadow-sm">
                  <div className="relative" ref={searchRef}>
                    <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Target Personnel (ID or Name)</label>
                    <div className="relative">
                       <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                       <input
                          type="text"
                          required
                          className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-4 focus:ring-blue-50 focus:border-blue-500 outline-none font-black text-sm transition-all"
                          placeholder="Type Employee ID or Name..."
                          value={employeeSearchQuery}
                          onChange={e => {
                            setEmployeeSearchQuery(e.target.value);
                            setShowEmployeeResults(true);
                            if (!e.target.value) setEmployeeId('');
                          }}
                          onFocus={() => setShowEmployeeResults(true)}
                          autoComplete="off"
                        />
                        {showEmployeeResults && filteredEmployees.length > 0 && (
                          <div className="absolute z-50 top-full left-0 right-0 mt-1 bg-white rounded-xl shadow-2xl border border-slate-200 overflow-hidden animate-in fade-in slide-in-from-top-1">
                            {filteredEmployees.map(emp => (
                              <button
                                key={emp.id}
                                type="button"
                                onClick={() => {
                                  setEmployeeId(emp.id);
                                  setEmployeeSearchQuery(`${emp.id} - ${emp.name}`);
                                  setShowEmployeeResults(false);
                                }}
                                className="w-full px-4 py-3 text-left hover:bg-blue-50 flex items-center justify-between border-b last:border-0 border-slate-100 group transition-colors"
                              >
                                <div>
                                  <p className="text-xs font-black text-slate-900 group-hover:text-blue-700">{emp.id} — {emp.name}</p>
                                  <p className="text-[9px] text-slate-400 font-bold uppercase">{emp.department} • {emp.designation}</p>
                                </div>
                                <ChevronRight className="w-4 h-4 text-slate-200 group-hover:text-blue-500" />
                              </button>
                            ))}
                          </div>
                        )}
                    </div>
                  </div>
               </div>
            )}

            <div className="space-y-4">
               <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest">Assigned Material(s)</label>

               <div className="space-y-4">
                  {toolItems.map((item, index) => (
                    <div 
                      key={index} 
                      ref={el => toolRefs.current[index] = el}
                      className="p-5 bg-white border border-slate-200 rounded-2xl shadow-sm group relative space-y-4"
                    >
                       <div className="grid grid-cols-12 gap-3">
                          <div className="col-span-12 sm:col-span-6">
                              <label className="block text-[8px] font-black text-slate-400 uppercase mb-1">Search Tools Catalog</label>
                              <div className="relative">
                                <Wrench className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-300" />
                                <input
                                  type="text"
                                  required
                                  autoComplete="off"
                                  className="w-full pl-8 pr-3 py-2.5 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-xs font-bold transition-all"
                                  placeholder="Start typing tool name..."
                                  value={item.searchQuery}
                                  onFocus={() => updateToolItem(index, { showDropdown: true })}
                                  onChange={e => {
                                    const val = e.target.value;
                                    const match = masterToolList.find(t => t.toLowerCase() === val.toLowerCase());
                                    updateToolItem(index, { 
                                      searchQuery: val, 
                                      showDropdown: true,
                                      toolName: match || ''
                                    });
                                  }}
                                />

                                {item.showDropdown && (
                                  <div className="absolute z-[60] top-full left-0 right-0 mt-1 bg-white rounded-xl shadow-2xl border border-slate-200 overflow-hidden max-h-60 overflow-y-auto animate-in fade-in duration-150">
                                    {getFilteredTools(item.searchQuery).length > 0 ? (
                                      getFilteredTools(item.searchQuery).map(toolName => (
                                        <button
                                          key={toolName}
                                          type="button"
                                          onClick={() => selectTool(index, toolName)}
                                          className="w-full px-4 py-2.5 text-left hover:bg-blue-50 border-b last:border-0 border-slate-100 flex items-center justify-between group transition-colors"
                                        >
                                          <span className="text-[11px] font-black text-slate-700 group-hover:text-blue-700">{toolName}</span>
                                          <ChevronRight className="w-3 h-3 text-slate-200 group-hover:text-blue-500" />
                                        </button>
                                      ))
                                    ) : (
                                      <div className="px-4 py-3 text-center">
                                        <p className="text-[10px] text-slate-400 font-bold uppercase italic">No items found</p>
                                      </div>
                                    )}
                                  </div>
                                )}

                                {item.toolName && (
                                  <div className="absolute right-2 top-1/2 -translate-y-1/2 flex items-center gap-1 bg-green-50 px-1.5 py-0.5 rounded text-[8px] font-black text-green-600 border border-green-100 uppercase">
                                    <CheckCircle2 className="w-2.5 h-2.5" /> Selected
                                  </div>
                                )}
                              </div>
                          </div>

                          <div className="col-span-6 sm:col-span-3">
                              <label className="block text-[8px] font-black text-slate-400 uppercase mb-1">Qty</label>
                              <div className="relative">
                                <Hash className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-300" />
                                <input
                                  type="number"
                                  min="1"
                                  required
                                  className="w-full pl-8 pr-3 py-2.5 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none font-black text-xs"
                                  value={item.quantity}
                                  onChange={e => updateToolItem(index, { quantity: parseInt(e.target.value) || 0 })}
                                />
                              </div>
                          </div>

