export const requestEmployeePasswordChange = async (empId: string, newPassword: string): Promise<{ success: boolean, message?: string }> => {
  if (!GOOGLE_SCRIPT_URL) return { success: false, message: "Server URL Not Configured" };

  try {
    const payload = {
      action: 'requestPasswordChange',
      payload: { id: empId, newPassword }
    };

    const response = await fetch(GOOGLE_SCRIPT_URL, {
      method: 'POST',
      headers: HEADERS, 
      body: JSON.stringify(payload),
      redirect: 'follow',
      mode: 'cors'
    });

    if (!response.ok) {
      return { success: false, message: `Server error: ${response.status}` };
    }

    const text = await response.text();
    try {
      const result = JSON.parse(text);
      return { 
        success: result.status === 'success', 
        message: result.message || (result.status === 'success' ? 'Sent' : 'Rejected')
      };
    } catch (e) {
      console.error("GAS returned non-JSON:", text);
      return { success: false, message: "System failure: Invalid response format from server." };
    }
  } catch (error) {
    console.error("CORS or Network Error:", error);
    return { success: false, message: "Connection Interrupted. Check your network or VPN settings." };
  }
};

