            className={`flex flex-col items-center gap-1.5 p-3 rounded-2xl transition-all active:scale-90 ${activeTab === tab.id ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50'}`}
          >
