import React, { useState, useMemo, useEffect, useCallback, useRef } from 'react';
import { 
  LogOut, 
  Search, 
  Plus, 
  FileSpreadsheet, 
  Users, 
  Package, 
  RefreshCw,
  Download,
  ShieldCheck,
  ChevronRight,
  Edit2,
  UserPlus,
  Trash2,
  X as CloseIcon,
  Lock,
  CheckCircle,
  Clock,
  Key,
  ShieldAlert,
  History,
  LayoutDashboard,
  Wrench,
  Tags,
  Menu,
  X
} from 'lucide-react';
import { USERS, LOGO_URL } from './constants';
import { User, Transaction, ToolDefinition } from './types';
import ToolModal from './components/ToolModal';
import AdminModal from './components/AdminModal';
import EmployeeModal from './components/EmployeeModal';
import ToolCatalogModal from './components/ToolCatalogModal';
import AIChat from './components/AIChat';
import Login from './components/Login';
import EmployeeDashboard from './components/EmployeeDashboard';
import { fetchSheetData, saveTransactionToSheet, saveAdminToSheet, deleteAdminFromSheet, saveEmployeeToSheet, updateEmployeeStatusInSheet, approveEmployeePasswordChange, saveToolToCatalog, updateToolInCatalog, SheetData } from './services/sheetService';
import { generateEmployeePDF } from './services/pdfService';

type Tab = 'employee' | 'directory' | 'daily' | 'stock' | 'admins' | 'catalog';

const CACHE_KEY = 'sarbs_inventory_cache_v3';
const USER_SESSION_KEY = 'sarbs_auth_session_v3';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(() => {
    try {
      const saved = localStorage.getItem(USER_SESSION_KEY);
      return saved ? JSON.parse(saved) : null;
    } catch (e) {
      return null;
    }
  });

  const [allTransactions, setAllTransactions] = useState<Transaction[]>([]);
  const [fullEmployeeDirectory, setFullEmployeeDirectory] = useState<any[]>([]);
  const [availableTools, setAvailableTools] = useState<string[]>([]);
  const [toolCatalog, setToolCatalog] = useState<ToolDefinition[]>([]);
  const [sheetAdmins, setSheetAdmins] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [loadingStage, setLoadingStage] = useState(1);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSync, setLastSync] = useState<string>('');
  const [activeTab, setActiveTab] = useState<Tab>('employee');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedEmployee, setSelectedEmployee] = useState<any>(null);
  const [showSearchResults, setShowSearchResults] = useState(false);
  const [lookupViewMode, setLookupViewMode] = useState<'summary' | 'history'>('summary');
  const searchRef = useRef<HTMLDivElement>(null);

  const [selectedDeptFilter, setSelectedDeptFilter] = useState<string>('');
  const [catalogDeptFilter, setCatalogDeptFilter] = useState<string>('');
  const [directoryDeptFilter, setDirectoryDeptFilter] = useState<string>('');
  const [directorySearchQuery, setDirectorySearchQuery] = useState<string>('');

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [isEmployeeModalOpen, setIsEmployeeModalOpen] = useState(false);
  const [isAdminModalOpen, setIsAdminModalOpen] = useState(false);
  const [isCatalogModalOpen, setIsCatalogModalOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [editingAdmin, setEditingAdmin] = useState<User | null>(null);
  const [editingTool, setEditingTool] = useState<ToolDefinition | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  useEffect(() => {
    if (user) {
      localStorage.setItem(USER_SESSION_KEY, JSON.stringify(user));
    } else {
      localStorage.removeItem(USER_SESSION_KEY);
    }
  }, [user]);

  const loadData = useCallback(async (isBackground = false) => {
    const hasExistingData = allTransactions.length > 0 || fullEmployeeDirectory.length > 0;
    if (!isBackground && !hasExistingData) setIsLoading(true);
    else setIsSyncing(true);

    try {
      const data = await fetchSheetData();
      setAllTransactions(data.transactions || []);
      setFullEmployeeDirectory(data.employees || []);
      setAvailableTools(data.tools || []);
      setToolCatalog(data.catalog || []);
      setSheetAdmins(data.admins || []);

      const timeStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      setLastSync(timeStr);

      localStorage.setItem(CACHE_KEY, JSON.stringify({
        ...data,
        cachedAt: timeStr,
        timestamp: Date.now()
      }));
    } catch (e) {
      console.error("Error loading data", e);
    } finally {
      setTimeout(() => setIsLoading(false), hasExistingData ? 0 : 3500);
      setTimeout(() => setIsSyncing(false), 800);
    }
  }, [allTransactions.length, fullEmployeeDirectory.length]);

  useEffect(() => {
    if (isLoading) {
      const timer = setTimeout(() => setLoadingStage(2), 1800);
      return () => clearTimeout(timer);
    }
  }, [isLoading]);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const cached = localStorage.getItem(CACHE_KEY);
    if (cached) {
      try {
        const parsed: SheetData & { cachedAt: string } = JSON.parse(cached);
        setAllTransactions(parsed.transactions || []);
        setFullEmployeeDirectory(parsed.employees || []);
        setAvailableTools(parsed.tools || []);
        setToolCatalog(parsed.catalog || []);
        setSheetAdmins(parsed.admins || []);
        setLastSync(parsed.cachedAt || '');
        setIsLoading(false);
        loadData(true);
      } catch (e) { loadData(false); }
    } else { loadData(false); }

    const handleClickOutside = (event: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(event.target as Node)) {
        setShowSearchResults(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const isSuperAdmin = useMemo(() => {
    if (!user) return false;
    const normalizedRole = user.role.toLowerCase().replace(/[\s_]/g, '');
    return normalizedRole === 'superadmin' || normalizedRole === 'super_admin';
  }, [user]);

  const isAdmin = useMemo(() => {
     if (!user) return false;
     return user.role === 'dept_admin' || isSuperAdmin;
  }, [user, isSuperAdmin]);

  const departments = useMemo(() => {
    const depts = new Set<string>();
    fullEmployeeDirectory.forEach(emp => { if (emp.department) depts.add(emp.department); });
    sheetAdmins.forEach(admin => { if (admin.department && admin.department !== 'All') depts.add(admin.department); });
    toolCatalog.forEach(tool => { if (tool.department && tool.department !== 'All') depts.add(tool.department); });
    return Array.from(depts).sort();
  }, [fullEmployeeDirectory, sheetAdmins, toolCatalog]);

  const visibleEmployees = useMemo(() => {
    if (!user) return [];
    if (isSuperAdmin) return fullEmployeeDirectory;
    return fullEmployeeDirectory.filter(emp => emp.department === user.department);
  }, [user, isSuperAdmin, fullEmployeeDirectory]);

  const filteredDirectory = useMemo(() => {
    let list = visibleEmployees;
    if (isSuperAdmin && directoryDeptFilter) {
      list = list.filter(emp => emp.department === directoryDeptFilter);
    }
    if (directorySearchQuery.trim()) {
      const q = directorySearchQuery.toLowerCase().trim();
      list = list.filter(emp => 
        String(emp.id).toLowerCase().includes(q) || 
        String(emp.name).toLowerCase().includes(q) ||
        String(emp.designation).toLowerCase().includes(q)
      );
    }
    return list;
  }, [visibleEmployees, isSuperAdmin, directoryDeptFilter, directorySearchQuery]);

  const filteredCatalog = useMemo(() => {
    if (!catalogDeptFilter) return toolCatalog;
    return toolCatalog.filter(tool => tool.department === catalogDeptFilter || tool.department === 'All');
  }, [toolCatalog, catalogDeptFilter]);

  const toolsForCurrentAdmin = useMemo(() => {
    if (!user) return [];
    if (isSuperAdmin) {
      return Array.from(new Set(toolCatalog.map(t => t.name))).sort();
    }
    const allowedTools = toolCatalog
      .filter(t => t.department === user.department || t.department === 'All')
      .map(t => t.name);
    return Array.from(new Set(allowedTools)).sort();
  }, [user, isSuperAdmin, toolCatalog]);

  const visibleTransactions = useMemo(() => {
    if (!user) return [];
    if (isSuperAdmin) return allTransactions;
    return allTransactions.filter(trx => trx.department === user.department);
  }, [user, isSuperAdmin, allTransactions]);

  const searchResults = useMemo(() => {
    if (!searchQuery.trim()) return [];
    const query = searchQuery.toLowerCase().trim();
    return visibleEmployees.filter(emp => 
      String(emp.id).toLowerCase().includes(query) || 
      String(emp.name).toLowerCase().includes(query)
    ).slice(0, 10); 
  }, [searchQuery, visibleEmployees]);

  const handleSaveTransactions = async (transactions: Transaction[], employeeDetails?: any) => {
    if (!user) return;
    setIsSyncing(true);
    try {
      for (const trx of transactions) {
        await saveTransactionToSheet(trx, employeeDetails || { department: user.department });
      }
      alert("Inventory update committed successfully.");
      await loadData(true);
    } catch (err) {
      alert("Error saving entries to cloud hub.");
    } finally {
      setIsSyncing(false);
    }
  };

  const handleSaveEmployee = async (employeeData: any) => {
     setIsSyncing(true);
     const success = await saveEmployeeToSheet(employeeData);
     if (success) {
        alert("Personnel registered successfully.");
        setIsEmployeeModalOpen(false);
        loadData(true);
     } else {
        alert("Failed to save personnel to hub.");
        setIsSyncing(false);
     }
  };

  const handleSaveToolToCatalog = async (toolData: ToolDefinition & { oldName?: string }) => {
    setIsSyncing(true);
    try {
      let success = false;
      if (toolData.oldName) {
        success = await updateToolInCatalog(toolData as ToolDefinition & { oldName: string });
      } else {
        success = await saveToolToCatalog(toolData as ToolDefinition);
      }

      if (success) {
        alert(toolData.oldName ? "Tool record successfully updated." : "New tool successfully registered in catalog.");
        setIsCatalogModalOpen(false);
        setEditingTool(null);
        await loadData(true);
      } else {
        alert("Server failed to commit tool to catalog. Please check your connection.");
      }
    } catch (err) {
      console.error(err);
      alert("Network error: Could not reach Cloud Hub.");
    } finally {
      setIsSyncing(false);
    }
  };

  const handleUpdateEmployeeStatus = async (empId: string, newStatus: string) => {
    setIsSyncing(true);
    const success = await updateEmployeeStatusInSheet(empId, newStatus);
    if (success) loadData(true);
    else { alert("Failed to update status."); setIsSyncing(false); }
  };

  const handleApprovePasswordChange = async (empId: string) => {
    if (!isSuperAdmin) return;
    setIsSyncing(true);
    const success = await approveEmployeePasswordChange(empId);
    if (success) {
      loadData(true);
    } else {
      alert("Failed to approve request. Connection may have timed out.");
      setIsSyncing(false);
    }
  };

  const handleSaveAdmin = async (adminData: User) => {
    setIsSyncing(true);
    const success = await saveAdminToSheet(adminData);
    if (success) {
      setIsAdminModalOpen(false);
      setEditingAdmin(null);
      loadData(true);
    } else {
      alert("Failed to save administrator.");
      setIsSyncing(false);
    }
  };

  const handleDeleteAdmin = async (adminId: string, role: string) => {
    const normalizedRole = role.toLowerCase().replace(/[\s_]/g, '');
    if (normalizedRole === 'superadmin' || normalizedRole === 'super_admin') {
      alert("Security Protocol: Super Admin accounts cannot be deleted."); return;
    }
    if (!confirm(`Revoke access for ID: ${adminId}?`)) return;
    setIsSyncing(true);
    const success = await deleteAdminFromSheet(adminId);
    if (success) loadData(true);
    else { alert("Failed to remove admin."); setIsSyncing(false); }
  };

  const handleLogin = (u: { id: string, password?: string }) => {
    const inputId = String(u.id || '').trim();
    const inputPass = String(u.password || '').trim();
    if (!inputId) return alert("Please enter ID.");

    const sheetAdmin = sheetAdmins.find(admin => 
      String(admin.id).trim() === inputId && String(admin.password).trim() === inputPass
    );
    if (sheetAdmin) {
      const rawRole = sheetAdmin.role.toLowerCase().replace(/[\s_]/g, '');
      const loggedUser = { ...sheetAdmin, role: (rawRole === 'superadmin' || rawRole === 'super_admin') ? 'super_admin' : 'dept_admin' } as User;
      setUser(loggedUser);
      return;
    }

    const sheetEmp = fullEmployeeDirectory.find(e => String(e.id).trim() === inputId);
    if (sheetEmp && (sheetEmp.password || '12345') === inputPass) {
      const loggedUser = {
        id: String(sheetEmp.id).trim(),
        name: sheetEmp.name,
        role: 'employee',
        designation: sheetEmp.designation,
        department: sheetEmp.department,
        typeOfEmployee: sheetEmp.typeOfEmployee
      } as User;
      setUser(loggedUser);
      return;
    }

    const foundFallback = USERS.find(existing => String(existing.id).trim() === inputId && String(existing.password).trim() === inputPass);
    if (foundFallback) {
      setUser(foundFallback);
      return;
    }

    alert(`Authentication Failed. ID or Password may be incorrect.`);
  };

  const employeeToolsData = useMemo(() => {
    if (!selectedEmployee) return [];
    const empTrx = visibleTransactions.filter(t => t.employeeId === selectedEmployee.id);
    const toolsMap = new Map<string, any>();

    toolsForCurrentAdmin.forEach(name => {
       toolsMap.set(name, { name, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0, remarks: '' });
    });

    empTrx.forEach(t => {
      let tool = toolsMap.get(t.toolName);
      if (!tool) {
         tool = { name: t.toolName, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0, remarks: '' };
         toolsMap.set(t.toolName, tool);
      }
      if (t.entryType === 'Distribute') tool.distributed += t.quantity;
      if (t.entryType === 'Return') tool.returned += t.quantity;
      if (t.entryType === 'Faulty Return') tool.faulty += t.quantity;
      if (t.entryType === 'Damage') tool.damage += t.quantity;
      if (t.entryType === 'Lost') tool.lost += t.quantity;
      if (t.remarks) tool.remarks = t.remarks;
    });

    return Array.from(toolsMap.values()).filter(t => t.distributed > 0);
  }, [selectedEmployee, visibleTransactions, toolsForCurrentAdmin]);

  const employeeHistory = useMemo(() => {
    if (!selectedEmployee) return [];
    return visibleTransactions
      .filter(t => t.employeeId === selectedEmployee.id)
      .reverse();
  }, [selectedEmployee, visibleTransactions]);

  const stockSummaryData = useMemo(() => {
    let targetTrx = allTransactions;
    if (!isSuperAdmin) targetTrx = visibleTransactions;
    else if (selectedDeptFilter !== '') targetTrx = allTransactions.filter(t => t.department === selectedDeptFilter);
    const allNames = toolsForCurrentAdmin;
    return allNames.map(name => {
      const toolTrx = targetTrx.filter(t => t.toolName === name);
      let purchase = 0, distributed = 0, returned = 0, faulty = 0, damage = 0, lost = 0;
      toolTrx.forEach(t => {
        if (t.entryType === 'Stock IN') purchase += t.quantity;
        if (t.entryType === 'Distribute') distributed += t.quantity;
        if (t.entryType === 'Return') returned += t.quantity;
        if (t.entryType === 'Faulty Return') faulty += t.quantity;
        if (t.entryType === 'Damage') damage += t.quantity;
        if (t.entryType === 'Lost') lost += t.quantity;
      });
      return {
        name, purchase, distributed, returned, faulty, damage, lost,
        stockNow: purchase - distributed + returned
      };
    }).filter(tool => tool.purchase > 0 || tool.distributed > 0);
  }, [allTransactions, visibleTransactions, toolsForCurrentAdmin, isSuperAdmin, selectedDeptFilter]);

  const navigationTabs = useMemo(() => [
    { id: 'employee', label: 'LOOKUP', icon: Search },
    { id: 'directory', label: 'DIR', icon: Users },
    { id: 'catalog', label: 'CATALOG', icon: Wrench, adminOnly: true },
    { id: 'daily', label: 'LOGS', icon: FileSpreadsheet },
    { id: 'stock', label: 'STOCK', icon: Package },
    ...(isSuperAdmin ? [{ id: 'admins', label: 'ADMIN', icon: ShieldCheck }] : [])
  ].filter(tab => !tab.adminOnly || isSuperAdmin), [isSuperAdmin]);

  if (isLoading) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-10 text-center animate-in fade-in duration-500">
        <div className="flex flex-col items-center">
           <img src={LOGO_URL} alt="SARBS Logo" className="w-56 h-56 md:w-80 md:h-80 object-contain" />
           <div className={`mt-10 transition-all duration-1000 ease-out ${loadingStage === 2 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-8'}`}>
              <h1 className="text-slate-900 font-black text-2xl md:text-3xl tracking-tight uppercase">SARBS Communications Ltd.</h1>
              <p className="text-slate-500 text-[10px] md:text-xs font-bold uppercase tracking-[0.4em] animate-pulse mt-4">Accessing Cloud Hub</p>
           </div>
        </div>
      </div>
    );
  }

  if (!user) return <Login onLogin={handleLogin} isSyncing={isSyncing} lastSync={lastSync} onRefresh={() => loadData(true)} isOnline={isOnline} installPrompt={null} onInstall={() => {}} />;

  if (user.role === 'employee') {
    return <EmployeeDashboard user={user} transactions={visibleTransactions} onLogout={() => { setUser(null); localStorage.removeItem(USER_SESSION_KEY); }} isSyncing={isSyncing} />;
  }

  return (
    <div className="min-h-screen bg-[#F0F4F8] font-sans text-slate-900 pb-32 md:pb-20 safe-top">
      {!isOnline && (
        <div className="bg-red-600 text-white text-[10px] font-black uppercase py-2 text-center sticky top-0 z-50 animate-pulse">
          Connection Interrupted
        </div>
      )}

      {/* Desktop Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm hidden lg:block">
        <div className="max-w-7xl mx-auto px-4 sm:px-6">
          <div className="flex items-center justify-between h-16 md:h-20">
            <div className="flex-shrink-0 flex items-center gap-3">
              <img src={LOGO_URL} alt="SARBS" className="w-10 h-10 md:w-12 md:h-12 object-contain" />
              <div className="hidden lg:block">
                <h1 className="text-sm font-black text-slate-900 leading-tight uppercase">SARBS</h1>
                <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">Inventory</p>
              </div>
            </div>

            <div className="flex items-center justify-center flex-1 mx-4 space-x-1 lg:space-x-4">
              {navigationTabs.map((tab) => (
                <button 
                  key={tab.id} 
                  onClick={() => setActiveTab(tab.id as Tab)} 
                  className={`px-3 py-6 text-[10px] lg:text-xs font-black transition-all flex items-center gap-2 border-b-4 h-full ${activeTab === tab.id ? 'border-slate-900 text-slate-900' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
                >
                  <tab.icon className="w-3.5 h-3.5" /> <span className="hidden sm:inline">{tab.label}</span>
                </button>
              ))}
            </div>

            <div className="flex-shrink-0 flex items-center gap-2 md:gap-4">
               <button onClick={() => loadData(true)} className={`p-2 rounded-full hover:bg-slate-100 ${isSyncing ? 'animate-spin text-blue-500' : 'text-slate-400'}`}>
                 <RefreshCw className="w-4 h-4 md:w-5 md:h-5" />
               </button>
               <div className="flex items-center gap-2 bg-[#0F172A] px-3 md:px-5 py-2 rounded-full text-white shadow-lg">
                  <ShieldCheck className="w-3 h-3 md:w-4 md:h-4 text-blue-400" />
                  <span className="text-[10px] font-black uppercase tracking-wider">{isSuperAdmin ? 'Super' : 'Admin'}</span>
               </div>
               <button onClick={() => { setUser(null); localStorage.removeItem(USER_SESSION_KEY); }} className="p-1.5 md:p-2 text-slate-400 hover:text-red-600">
                 <LogOut className="w-5 h-5 md:w-6 md:h-6" />
               </button>
            </div>
          </div>
        </div>
      </header>

      {/* Mobile/Tablet Top Bar */}
      <div className="lg:hidden bg-white border-b border-slate-200 sticky top-0 z-40 p-4 flex items-center justify-between shadow-sm">
        <div className="flex items-center gap-3">
          <button onClick={() => setIsMobileMenuOpen(true)} className="p-2 -ml-2 text-slate-600 hover:bg-slate-50 rounded-xl transition-colors">
            <Menu className="w-6 h-6" />
          </button>
          <div className="flex items-center gap-2">
            <img src={LOGO_URL} alt="SARBS" className="w-8 h-8 object-contain" />
            <h1 className="text-xs font-black text-slate-900 uppercase">SARBS Inventory</h1>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => loadData(true)} className={`p-1.5 rounded-lg ${isSyncing ? 'animate-spin text-blue-500' : 'text-slate-400'}`}>
            <RefreshCw className="w-5 h-5" />
          </button>
          <button onClick={() => { setUser(null); localStorage.removeItem(USER_SESSION_KEY); }} className="p-1.5 text-slate-400">
            <LogOut className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* Mobile/Tablet Navigation Drawer */}
      {isMobileMenuOpen && (
        <div className="lg:hidden fixed inset-0 z-[100] animate-in fade-in duration-300">
          <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={() => setIsMobileMenuOpen(false)} />
          <nav className="absolute top-0 left-0 bottom-0 w-72 bg-white shadow-2xl flex flex-col animate-in slide-in-from-left duration-300">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-900 text-white">
              <div className="flex items-center gap-2">
                <img src={LOGO_URL} alt="SARBS" className="w-8 h-8 object-contain" />
                <span className="font-black uppercase text-xs tracking-widest">Navigation</span>
              </div>
              <button onClick={() => setIsMobileMenuOpen(false)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-5 h-5" />
