                  {user.name.charAt(0)}
                </div>
                <div className="flex-1 overflow-hidden">
                  <p className="font-black text-[10px] text-slate-900 uppercase truncate">{user.name}</p>
                  <p className="font-bold text-[8px] text-slate-400 uppercase">{user.role.replace('_', ' ')}</p>
                </div>
              </div>
              <button 
                onClick={() => { setUser(null); localStorage.removeItem(USER_SESSION_KEY); }}
