    // Calculation for Final Qty held by employee
    const finalQty = dist - (ret + faulty + damage + lost);

    return [
      tool.name,
      dist > 0 ? dist : '-',
      ret > 0 ? ret : '-',
      faulty > 0 ? faulty : '-',
      damage > 0 ? damage : '-',
      lost > 0 ? lost : '-',
      finalQty,
      tool.remarks || '-'
    ];
  });

  // Table Configuration
  doc.autoTable({
    startY: 78,
    head: [[
      'Tools Name', 
      'Dist. Qty', 
      'Ret. Qty', 
      'Faulty Ret.', 
      'Damage', 
      'Lost', 
      'Final Qty', 
