/**
 * Helper to convert a remote image URL to a Base64 string.
 * Uses canvas as a fallback if fetch fails due to CORS, 
 * provided the server allows anonymous cross-origin.
 */
const getBase64ImageFromUrl = async (url: string): Promise<string | null> => {
  try {
    const response = await fetch(url, { mode: 'cors' });
    const blob = await response.blob();
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(reader.result as string);
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  } catch (error) {
    console.warn("Fetch method failed for PDF logo, attempting Canvas fallback...", error);

    // Fallback using Canvas and Image object
    return new Promise((resolve) => {
      const img = new Image();
      img.setAttribute('crossOrigin', 'anonymous');
      img.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0);
          // Auto-detect extension or default to PNG as the user updated to a .png file
          const format = url.toLowerCase().endsWith('.png') ? 'image/png' : 'image/jpeg';
          const dataURL = canvas.toDataURL(format);
          resolve(dataURL);
        } else {
          resolve(null);
        }
      };
      img.onerror = () => {
        console.error("Canvas fallback also failed for logo URL");
        resolve(null);
      };
      img.src = url;
    });
  }
};

