/**
 * Helper to convert a remote image URL to a Base64 string.
 * This function attempts multiple methods to bypass CORS restrictions:
 * 1. Fetch API with CORS mode
 * 2. HTML Canvas with anonymous crossOrigin
 */
const getBase64ImageFromUrl = async (url: string): Promise<string | null> => {
  // Method 1: Standard Fetch
  try {
    const response = await fetch(url, { 
      mode: 'cors',
      cache: 'no-cache' 
    });
    if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
    const blob = await response.blob();
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(reader.result as string);
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  } catch (error) {
    console.warn("PDF Service: Fetch method failed for logo. Trying Canvas fallback...", error);

    // Method 2: Canvas Fallback
    return new Promise((resolve) => {
      const img = new Image();
      // This is the critical line for CORS-protected images on Canvas
      img.setAttribute('crossOrigin', 'anonymous');

      img.onload = () => {
        try {
          const canvas = document.createElement('canvas');
          canvas.width = img.width;
          canvas.height = img.height;
          const ctx = canvas.getContext('2d');
          if (ctx) {
            ctx.drawImage(img, 0, 0);
            const format = url.toLowerCase().endsWith('.png') ? 'image/png' : 'image/jpeg';
            const dataURL = canvas.toDataURL(format);
            resolve(dataURL);
          } else {
            resolve(null);
          }
        } catch (e) {
          console.error("PDF Service: Canvas toDataURL failed (likely CORS tainted canvas)", e);
          resolve(null);
        }
      };

      img.onerror = () => {
        console.error("PDF Service: Image object failed to load logo from URL:", url);
        resolve(null);
      };

      // Append a cache-buster if the fetch failed, as the image might be cached without CORS headers
      img.src = `${url}${url.includes('?') ? '&' : '?'}t=${Date.now()}`;
    });
  }
};

