import React, { useState, useMemo, useEffect, useCallback, useRef } from 'react';
import { 
  LogOut, 
  Search, 
  Plus, 
  FileSpreadsheet, 
  Users, 
  Package, 
  RefreshCw,
  Download,
  ShieldCheck,
  ChevronRight,
  Edit2,
  UserPlus,
  Trash2,
  X as CloseIcon,
  Lock,
  CheckCircle,
  Clock,
  Key,
  ShieldAlert,
