import React, { useState, useEffect } from 'react';
import { Lock, User as UserIcon, RefreshCw, Wifi, WifiOff, Smartphone, CheckCircle2, Share, Info } from 'lucide-react';
import { LOGO_URL } from '../constants';

interface LoginProps {
  onLogin: (credentials: { id: string, password?: string }) => void;
  isSyncing: boolean;
  lastSync: string;
  onRefresh: () => void;
  isOnline: boolean;
  installPrompt: any;
  onInstall: () => void;
  isStandalone: boolean;
}

const Login: React.FC<LoginProps> = ({ 
  onLogin, 
  isSyncing, 
  lastSync, 
  onRefresh, 
  isOnline,
  installPrompt,
  onInstall,
  isStandalone
}) => {
  const [id, setId] = useState('');
  const [password, setPassword] = useState('');
  const [showSuccess, setShowSuccess] = useState(false);
  const [isIOS, setIsIOS] = useState(false);
  const [showInstallGuide, setShowInstallGuide] = useState(false);

  useEffect(() => {
    // Detect iOS to show specific instructions
    const userAgent = window.navigator.userAgent.toLowerCase();
    setIsIOS(/iphone|ipad|ipod/.test(userAgent));

    if (!isSyncing && lastSync) {
      setShowSuccess(true);
      const timer = setTimeout(() => setShowSuccess(false), 3000);
      return () => clearTimeout(timer);
    }
  }, [isSyncing, lastSync]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    onLogin({ id, password });
  };

  const currentYear = new Date().getFullYear();

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center p-4 font-sans">
      <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden border border-slate-200">

