              <img src={LOGO_URL} alt="SARBS Logo" className="w-16 h-16 object-contain" />
            </div>
            <h1 className="text-2xl font-black text-white mb-1 uppercase tracking-tight">SARBS Communications Ltd.</h1>
            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Tools Inventory Management System</p>
          </div>
        </div>

        {/* Sync Status Bar */}
        <div className="bg-slate-50 border-b border-slate-100 px-6 py-3 flex items-center justify-between">
          <div className="flex items-center gap-2">
            {isOnline ? (
              <span className="flex items-center gap-1 text-[10px] font-black text-green-600 bg-green-100 px-2 py-0.5 rounded-full">
                <Wifi className="w-2.5 h-2.5" /> ONLINE
              </span>
            ) : (
              <span className="flex items-center gap-1 text-[10px] font-black text-red-600 bg-red-100 px-2 py-0.5 rounded-full">
                <WifiOff className="w-2.5 h-2.5" /> OFFLINE
