            )}
            <span className="text-[10px] text-slate-400 font-bold uppercase">Sync: {lastSync || 'Never'}</span>
          </div>

          <div className="flex items-center gap-2">
            {showSuccess && !isSyncing && (
              <span className="flex items-center gap-1 text-[9px] font-black text-blue-600 animate-bounce">
                <CheckCircle2 className="w-3 h-3" /> UPDATED!
              </span>
            )}
            <button 
              onClick={onRefresh}
              disabled={isSyncing || !isOnline}
              className={`flex items-center gap-1.5 text-[10px] font-black uppercase tracking-tighter transition-all px-2 py-1 rounded-lg ${isSyncing ? 'text-blue-500 bg-blue-50' : 'text-slate-500 hover:bg-slate-200 active:scale-95'}`}
            >
              <RefreshCw className={`w-3 h-3 ${isSyncing ? 'animate-spin text-blue-500' : ''}`} />
              {isSyncing ? 'Pulling...' : 'Refresh Cloud'}
            </button>
          </div>
        </div>

        <div className="p-8">
          <form onSubmit={handleLogin} className="space-y-5">
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Official Personnel ID</label>
              <div className="relative group">
                <UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-300 group-focus-within:text-blue-500 transition-colors" />
