                  type="text"
                  required
                  className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-50 focus:border-blue-500 outline-none transition-all font-bold text-slate-800"
                  placeholder="Office ID"
                  value={id}
                  onChange={(e) => setId(e.target.value)}
                />
              </div>
            </div>

            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Security Password</label>
              <div className="relative group">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-300 group-focus-within:text-blue-500 transition-colors" />
                <input 
                  type="password"
                  required
                  className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-50 focus:border-blue-500 outline-none transition-all font-bold text-slate-800"
                  placeholder="••••••••"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
              </div>
            </div>

            <button 
              type="submit"
              disabled={isSyncing}
              className={`w-full py-4 font-black rounded-2xl shadow-xl transition-all active:scale-[0.97] uppercase tracking-widest text-xs ${isSyncing ? 'bg-slate-400 cursor-not-allowed' : 'bg-slate-900 hover:bg-black text-white shadow-slate-200'}`}
            >
              {isSyncing ? 'Syncing...' : 'Secure Login'}
            </button>
          </form>

          {/* Smart Install Prompt Logic - Optimized for final v1 */}
          {!isStandalone && (
            <div className="mt-6 border-t border-slate-100 pt-6">
              {installPrompt ? (
                <button 
                  onClick={onInstall}
                  className="w-full py-4 bg-blue-600 text-white font-black rounded-2xl shadow-lg shadow-blue-200 transition-all flex items-center justify-center gap-3 text-[11px] uppercase tracking-[0.2em] hover:bg-blue-700 active:scale-95"
                >
                  <Smartphone className="w-5 h-5 animate-pulse" />
                  Install SARBS App
                </button>
              ) : (
                <div className="space-y-3">
                   <button 
                    onClick={() => setShowInstallGuide(!showInstallGuide)}
                    className="w-full py-3 bg-slate-50 text-slate-500 font-black rounded-xl border border-slate-200 transition-all flex items-center justify-center gap-2 text-[10px] uppercase tracking-widest hover:bg-white"
                  >
                    <Info className="w-4 h-4" />
                    How to Install on Mobile
                  </button>

                  {showInstallGuide && (
                    <div className="bg-blue-50 p-4 rounded-2xl border border-blue-200 flex flex-col items-center gap-3 animate-in fade-in slide-in-from-top-2">
                      <p className="text-[10px] font-black text-blue-700 uppercase tracking-tight text-center">Setup SARBS as Home Screen App:</p>
                      {isIOS ? (
                        <div className="flex flex-col items-center gap-2 text-[9px] font-bold text-blue-600 uppercase">
                          <span className="flex items-center gap-1 px-3 py-1 bg-white rounded-lg shadow-sm border border-blue-100">1. Tap the Share icon <Share className="w-3.5 h-3.5 inline ml-1" /></span>
                          <span className="flex items-center gap-1 px-3 py-1 bg-white rounded-lg shadow-sm border border-blue-100">2. Select 'Add to Home Screen'</span>
                        </div>
                      ) : (
                        <div className="flex flex-col items-center gap-2 text-[9px] font-bold text-blue-600 uppercase">
                          <span className="flex items-center gap-1 px-3 py-1 bg-white rounded-lg shadow-sm border border-blue-100">1. Tap Browser Menu (⋮)</span>
                          <span className="flex items-center gap-1 px-3 py-1 bg-white rounded-lg shadow-sm border border-blue-100">2. Select 'Install App' or 'Add to Home'</span>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              )}
            </div>
          )}

          <div className="mt-8 text-center">
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter">
              Authorized Access Only <br/>
              <span className="text-slate-300">© {currentYear} SARBS Communications Ltd.</span>
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

// Standard PWA Service Worker Registration
// Using a relative path is most reliable for sandbox origin mapping
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('./sw.js')
      .then(registration => {
        console.log('SARBS PWA: ServiceWorker active on scope:', registration.scope);
      })
      .catch(error => {
        console.error('SARBS PWA: Registration failed:', error);
      });
  });
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

