import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

/**
 * Robust PWA Service Worker Registration
 * Fixes the 'origin mismatch' error by explicitly calculating the full URL 
 * based on the current sandbox location.
 */
const registerServiceWorker = async () => {
  if ('serviceWorker' in navigator) {
    try {
      // Use the current window location as the base to ensure the SW is 
      // registered on the correct sandbox origin.
      const swUrl = new URL('sw.js', window.location.href).href;
      const registration = await navigator.serviceWorker.register(swUrl, { scope: './' });
      console.log('SARBS PWA: ServiceWorker registered successfully on scope:', registration.scope);
    } catch (error) {
      console.error('SARBS PWA: ServiceWorker registration failed:', error);

      // Fallback: try standard relative registration if the explicit one fails
      navigator.serviceWorker.register('./sw.js').catch(e => {
        console.error('SARBS PWA: Final fallback registration failed:', e);
      });
    }
  }
};

window.addEventListener('load', registerServiceWorker);

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

const CACHE_NAME = 'sarbs-pwa-v6';
const ASSETS_TO_CACHE = [
  './',
  './index.html',
  './manifest.json',
  './index.tsx',
  './App.tsx',
  './constants.ts',
  './types.ts'
];

self.addEventListener('install', (event) => {
  self.skipWaiting();
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      console.log('SARBS SW: Pre-caching core assets');
      return cache.addAll(ASSETS_TO_CACHE);
    })
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME) {
            console.log('SARBS SW: Cleaning old cache:', cacheName);
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
  return self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  // Only handle GET requests for caching
  if (event.request.method !== 'GET') return;

  event.respondWith(
    caches.match(event.request).then((cachedResponse) => {
      if (cachedResponse) {
        return cachedResponse;
      }

      return fetch(event.request).then((response) => {
        // Don't cache if not a valid success response
        if (!response || response.status !== 200 || response.type !== 'basic') {
          return response;
        }

        const responseToCache = response.clone();
        caches.open(CACHE_NAME).then((cache) => {
          cache.put(event.request, responseToCache);
        });

        return response;
      }).catch(() => {
        // Offline fallback if needed could go here
        return null;
      });
    })
  );
});

