import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

/**
 * Robust PWA Service Worker Registration
 * Handles sandbox environment quirks like invalid location protocols and origin mismatches.
 */
const registerServiceWorker = async () => {
  if (!('serviceWorker' in navigator)) return;

  // Ensure we are in a hierarchical URL context (http/https)
  // Sandbox previews sometimes use 'blob:' or 'about:blank' initially, which causes 'Invalid URL' errors.
  const protocol = window.location.protocol;
  const isHierarchical = protocol.startsWith('http');

  if (!isHierarchical) {
    console.debug('SARBS PWA: Non-hierarchical protocol detected, skipping ServiceWorker registration.');
    return;
  }

  try {
    // Construct the Service Worker URL explicitly from the current origin and path.
    // This prevents relative paths from incorrectly resolving to the parent frame origin (e.g., ai.studio).
    const currentDir = window.location.href.substring(0, window.location.href.lastIndexOf('/') + 1);
    const swUrl = new URL('sw.js', currentDir).href;

    const registration = await navigator.serviceWorker.register(swUrl, { scope: './' });
    console.log('SARBS PWA: ServiceWorker registered successfully on scope:', registration.scope);
  } catch (error: any) {
    // If explicit registration fails, fallback to standard relative path.
    // In many sandboxed environments, SW registration is restricted; we catch this to prevent app instability.
    console.warn('SARBS PWA: Standard SW registration failed, attempting basic relative path fallback...', error.message);

    navigator.serviceWorker.register('sw.js').catch(fallbackError => {
      console.debug('SARBS PWA: ServiceWorker registration not supported or blocked in this environment:', fallbackError.message);
    });
  }
};

// Register the Service Worker after the page has fully loaded
window.addEventListener('load', registerServiceWorker);

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

