import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

/**
 * Robust PWA Service Worker Registration
 */
const registerServiceWorker = async () => {
  if (!('serviceWorker' in navigator)) return;

  const protocol = window.location.protocol;
  const isHierarchical = protocol.startsWith('http');

  if (!isHierarchical) {
    return;
  }

  try {
    // Determine the base path for registration
    const swPath = './sw.js';
    const registration = await navigator.serviceWorker.register(swPath, { scope: './' });
    console.log('SARBS PWA: ServiceWorker registered successfully on scope:', registration.scope);
  } catch (error: any) {
    console.warn('SARBS PWA: Standard SW registration failed:', error.message);

    // Fallback: simple path if scope adjustment is blocked
    navigator.serviceWorker.register('sw.js').catch(fallbackError => {
      console.debug('SARBS PWA: ServiceWorker blocked in this context.');
    });
  }
};

window.addEventListener('load', registerServiceWorker);

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

