                              <td className="px-4 py-4 border-l border-slate-100 text-amber-500 font-bold">{row.faulty || '0'}</td>
                              <td className="px-4 py-4 border-l border-slate-100 text-red-500 font-bold">{row.damage || '0'}</td>
