                  >
                    <DownloadCloud className="w-5 h-5" />
                    Install SARBS App
                  </button>
                </div>
              )}
            </div>
            <div className="p-6 border-t border-slate-100 bg-slate-50">
              <div className="flex items-center gap-3 mb-6">
                <div className="bg-blue-600 text-white w-8 h-8 rounded-full flex items-center justify-center font-black text-xs">
                  {user.name.charAt(0)}
