                     </div>
                   )}
                </div>
                {isAdmin && (
                  <button onClick={() => setIsModalOpen(true)} className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-8 py-4 rounded-2xl font-black text-xs transition-all uppercase tracking-widest w-full md:w-auto justify-center shadow-lg active:scale-95">
                    <Plus className="w-5 h-5" /> COMMIT ENTRY
                  </button>
                )}
             </div>

             {selectedEmployee ? (
               <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
