      {/* Mobile Bottom Navigation */}
      <nav className="lg:hidden fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-md border-t border-slate-200 z-[90] flex items-center justify-around p-2 pb-8 shadow-[0_-8px_20px_rgba(0,0,0,0.08)]">
        {navigationTabs.map((tab) => (
