                          <th className="px-2 py-5 border-r border-slate-200">Stock IN</th>
                          <th className="px-2 py-5 border-r border-slate-200">Dist.</th>
                          <th className="px-2 py-5 border-r border-slate-200">Returned</th>
                          <th className="px-2 py-5 border-r border-slate-200 text-amber-600">Faulty</th>
                          <th className="px-2 py-5 border-r border-slate-200 text-red-500">Damage</th>
                          <th className="px-2 py-5 border-r border-slate-200 text-red-700">Lost</th>
                          <th className="px-4 py-5 bg-slate-900 text-white font-black">Current Stock</th>
