/**
 * SARBS Communications Ltd. - Inventory Hub Backend
 * Synchronized with 'Tools Name List' sheet
 */

function doGet(e) {
  try {
    const transactions = getTransactions();
    const metadata = getMetadata();
    const admins = getAdmins();

    return createJSONOutput({ 
      status: 'success',
      transactions: transactions,
      employees: metadata.employees,
      tools: metadata.tools, 
      catalog: metadata.catalog, // Structured data from 'Tools Name List'
      admins: admins
    });

  } catch (error) {
    console.error("Critical doGet Error: " + error.toString());
    return createJSONOutput({ status: 'error', message: error.toString() });
  }
}

function doPost(e) {
  const lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    const requestData = JSON.parse(e.postData.contents);
    const p = requestData.payload;

    if (requestData.action === 'addTransaction') {
      const sheet = getSheet("Daily Entry");
      sheet.appendRow([
        p.date,
        p.employeeId || '',
        p.employeeName || '',
        p.designation || '',
        p.department || '',
        p.typeOfEmployee || '',
        p.toolName,
        p.entryType,
        p.quantity,
        p.condition,
        p.remarks || ''
      ]);
      return createJSONOutput({ status: 'success' });
    }

    if (requestData.action === 'addEmployee') {
      const sheet = getSheet("Data Validation");
      const data = sheet.getDataRange().getValues();
      const targetId = String(p.id).trim().toLowerCase();

      let rowIndex = -1;
      for (let i = 1; i < data.length; i++) {
        if (String(data[i][0]).trim().toLowerCase() === targetId) {
          rowIndex = i + 1;
          break;
        }
      }

      if (rowIndex !== -1) {
        // Update existing employee (Columns B, C, D, E)
        sheet.getRange(rowIndex, 2).setValue(p.name);
        sheet.getRange(rowIndex, 3).setValue(p.designation);
        sheet.getRange(rowIndex, 4).setValue(p.department);
        sheet.getRange(rowIndex, 5).setValue(p.typeOfEmployee);
      } else {
        // Append new employee
        sheet.appendRow([
          p.id,
          p.name,
          p.designation,
          p.department,
          p.typeOfEmployee,
          '12345', 
          '',      
          ''       
        ]);
      }
      return createJSONOutput({ status: 'success' });
    }

    if (requestData.action === 'addToolToCatalog') {
      const sheet = getSheet("Tools Name List");
      sheet.appendRow([
        p.name,
        p.brand || 'N/A',
        p.department || 'All'
      ]);
      return createJSONOutput({ status: 'success' });
    }

    if (requestData.action === 'updateToolInCatalog') {
      const sheet = getSheet("Tools Name List");
      const data = sheet.getDataRange().getValues();
      const oldName = String(p.oldName).trim().toLowerCase();

      for (let i = 1; i < data.length; i++) {
        if (String(data[i][0]).trim().toLowerCase() === oldName) {
          sheet.getRange(i + 1, 1, 1, 3).setValues([[
            p.name,
            p.brand || 'N/A',
            p.department || 'All'
          ]]);
          return createJSONOutput({ status: 'success' });
        }
      }
      return createJSONOutput({ status: 'error', message: 'Tool not found in catalog' });
    }

    if (requestData.action === 'updateEmployeeStatus') {
      const sheet = getSheet("Data Validation");
      const data = sheet.getDataRange().getValues();
      const targetId = String(p.id).trim().toLowerCase();

      for (let i = 1; i < data.length; i++) {
        if (String(data[i][0]).trim().toLowerCase() === targetId) {
          sheet.getRange(i + 1, 5).setValue(p.status);
          return createJSONOutput({ status: 'success' });
        }
      }
      return createJSONOutput({ status: 'error', message: 'Employee not found' });
    }

    if (requestData.action === 'requestPasswordChange') {
      const sheet = getSheet("Data Validation");
      const data = sheet.getDataRange().getValues();
      const targetId = String(p.id).trim().toLowerCase();
      for (let i = 1; i < data.length; i++) {
        if (String(data[i][0]).trim().toLowerCase() === targetId) {
          sheet.getRange(i + 1, 7).setValue(String(p.newPassword).trim());
          return createJSONOutput({ status: 'success' });
        }
      }
      return createJSONOutput({ status: 'error', message: 'Employee Record Not Found for ID: ' + p.id });
    }

    if (requestData.action === 'approvePasswordChange') {
      const sheet = getSheet("Data Validation");
      const data = sheet.getDataRange().getValues();
      const targetId = String(p.id).trim().toLowerCase();
      for (let i = 1; i < data.length; i++) {
        if (String(data[i][0]).trim().toLowerCase() === targetId) {
          const requested = data[i][6]; 
          if (requested) {
            sheet.getRange(i + 1, 6).setValue(requested); 
            sheet.getRange(i + 1, 7).setValue('');         
            return createJSONOutput({ status: 'success' });
          }
        }
      }
      return createJSONOutput({ status: 'error', message: 'No Pending Request Found' });
    }

    if (requestData.action === 'upsertAdmin') {
      const sheet = getSheet("Admins");
      const currentAdmins = getAdmins();
      const targetId = String(p.id).trim().toLowerCase();

      let rowIndex = -1;
      for (let i = 0; i < currentAdmins.length; i++) {
        if (currentAdmins[i].id.toLowerCase() === targetId) {
          rowIndex = i;
          break;
        }
      }

      const rowValues = [p.id, p.name, p.password, p.role, p.department, p.designation];
      if (rowIndex !== -1) {
        sheet.getRange(rowIndex + 2, 1, 1, 6).setValues([rowValues]);
      } else {
        sheet.appendRow(rowValues);
      }
      return createJSONOutput({ status: 'success' });
    }

    if (requestData.action === 'deleteAdmin') {
      const sheet = getSheet("Admins");
      const data = sheet.getDataRange().getValues();
      const targetId = String(p.id).trim().toLowerCase();

      for (let i = 1; i < data.length; i++) {
        if (String(data[i][0]).trim().toLowerCase() === targetId) {
          sheet.deleteRow(i + 1);
          return createJSONOutput({ status: 'success' });
        }
      }
      return createJSONOutput({ status: 'error', message: 'Admin not found' });
    }

    return createJSONOutput({ status: 'error', message: 'Unknown action: ' + requestData.action });

  } catch (error) {
    console.error("Critical doPost Error: " + error.toString());
    return createJSONOutput({ status: 'error', message: error.toString() });
  } finally {
    lock.releaseLock();
  }
}

function getAdmins() {
  const sheet = getSheet("Admins");
  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return [];
  const data = sheet.getRange(2, 1, lastRow - 1, 6).getDisplayValues();

  return data.map(function(row) {
    return {
      id: String(row[0] || '').trim(),
      name: String(row[1] || '').trim(),
      password: String(row[2] || '').trim(),
      role: String(row[3] || '').trim(),
      department: String(row[4] || '').trim(),
      designation: String(row[5] || '').trim()
    };
  }).filter(function(admin) {
    return admin.id !== "" && admin.id.toUpperCase() !== "ID";
  });
}

function getTransactions() {
  const sheet = getSheet("Daily Entry");
  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return [];
  const data = sheet.getDataRange().getDisplayValues();
  const rows = data.slice(1); 

  return rows.map(function(row, index) {
    return {
      id: 'row-' + (index + 2),
      date: String(row[0] || '').trim(),
      employeeId: String(row[1] || '').trim(),
      employeeName: String(row[2] || '').trim(),
      designation: String(row[3] || '').trim(),
      department: String(row[4] || '').trim(),
      typeOfEmployee: String(row[5] || '').trim(),
      toolName: String(row[6] || '').trim(),
      entryType: String(row[7] || '').trim(),
      quantity: Number(row[8] || 0),
      condition: String(row[9] || '').trim(),
      remarks: String(row[10] || '').trim()
    };
  }).filter(function(trx) {
    return trx.employeeId.toUpperCase() !== "ID" && trx.date.toUpperCase() !== "DATE";
  });
}

function getMetadata() {
  const validationSheet = getSheet("Data Validation");
  const catalogSheet = getSheet("Tools Name List");

  const vLastRow = validationSheet.getLastRow();
  const cLastRow = catalogSheet.getLastRow();

  const employees = [];
  const addedEmpIds = {};

  if (vLastRow >= 2) {
    const vRange = validationSheet.getRange(2, 1, vLastRow - 1, 8).getDisplayValues();
    for (let i = 0; i < vRange.length; i++) {
      const row = vRange[i];
      const empId = String(row[0] || '').trim();
      const empName = String(row[1] || '').trim();
      if (empId && empId.toUpperCase() !== 'ID' && empName.toUpperCase() !== 'NAME' && !addedEmpIds[empId]) {
        employees.push({
          id: empId,
          name: empName,
          designation: String(row[2] || '').trim(),
          department: String(row[3] || '').trim(),
          typeOfEmployee: String(row[4] || '').trim(),
          password: String(row[5] || '12345').trim(),
          passwordRequest: String(row[6] || '').trim()
        });
        addedEmpIds[empId] = true;
      }
    }
  }

  const catalog = [];
  const toolsNamesOnly = [];

  if (cLastRow >= 2) {
    const cRange = catalogSheet.getRange(2, 1, cLastRow - 1, 3).getDisplayValues();
    for (let i = 0; i < cRange.length; i++) {
      const row = cRange[i];
      const name = String(row[0] || '').trim();
      if (name && name.toUpperCase() !== 'TOOL NAME' && name.toUpperCase() !== 'NAME') {
        catalog.push({
          name: name,
          brand: String(row[1] || 'N/A').trim(),
          department: String(row[2] || 'All').trim()
        });
        toolsNamesOnly.push(name);
      }
    }
  }

  return { employees: employees, catalog: catalog, tools: toolsNamesOnly };
}

function getSheet(name) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
    if (name === "Admins") {
      sheet.appendRow(["ID", "Name", "Password", "Role", "Department", "Designation"]);
    } else if (name === "Daily Entry") {
      sheet.appendRow(["Date", "ID", "Name", "Designation", "Department", "Type", "Item Name", "Entry Type", "Quantity", "Condition", "Remarks"]);
    } else if (name === "Data Validation") {
       sheet.appendRow(["ID", "Name", "Designation", "Department", "Type of Employee", "Password", "Password Request", "Tool Name"]);
    } else if (name === "Tools Name List") {
       sheet.appendRow(["Tool Name", "Brand Name", "Department Access"]);
    }
  }
  return sheet;
}

function createJSONOutput(data) {
  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

