import { generateEmployeePDF } from './services/pdfService';

type Tab = 'employee' | 'directory' | 'daily' | 'stock' | 'admins' | 'catalog';

const CACHE_KEY = 'sarbs_inventory_cache_v5';
const USER_SESSION_KEY = 'sarbs_auth_session_v5';
const LOGS_PER_PAGE = 20;

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(() => {
    try {
      const saved = localStorage.getItem(USER_SESSION_KEY);
      return saved ? JSON.parse(saved) : null;
    } catch (e) {
      return null;
    }
  });

  const [allTransactions, setAllTransactions] = useState<Transaction[]>([]);
  const [fullEmployeeDirectory, setFullEmployeeDirectory] = useState<any[]>([]);
  const [availableTools, setAvailableTools] = useState<string[]>([]);
  const [toolCatalog, setToolCatalog] = useState<ToolDefinition[]>([]);
  const [sheetAdmins, setSheetAdmins] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [loadingStage, setLoadingStage] = useState(1);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSync, setLastSync] = useState<string>('');
  const [activeTab, setActiveTab] = useState<Tab>('employee');
  const [searchQuery, setSearchQuery] = useState('');
  const [stockSearchQuery, setStockSearchQuery] = useState('');
  const [selectedEmployee, setSelectedEmployee] = useState<any>(null);
  const [showSearchResults, setShowSearchResults] = useState(false);
  const [lookupViewMode, setLookupViewMode] = useState<'summary' | 'history'>('summary');
  const searchRef = useRef<HTMLDivElement>(null);

  const [selectedDeptFilter, setSelectedDeptFilter] = useState<string>('');
  const [catalogDeptFilter, setCatalogDeptFilter] = useState<string>('');
  const [directoryDeptFilter, setDirectoryDeptFilter] = useState<string>('');
  const [directorySearchQuery, setDirectorySearchQuery] = useState<string>('');

  // Filtering for Logs Tab
  const [showBulkLogsOnly, setShowBulkLogsOnly] = useState(false);

  // Pagination State for Logs
  const [currentLogsPage, setCurrentLogsPage] = useState(1);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [isEmployeeModalOpen, setIsEmployeeModalOpen] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<any | null>(null);
  const [isAdminModalOpen, setIsAdminModalOpen] = useState(false);
  const [isCatalogModalOpen, setIsCatalogModalOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [editingAdmin, setEditingAdmin] = useState<User | null>(null);
  const [editingTool, setEditingTool] = useState<ToolDefinition | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isStandalone, setIsStandalone] = useState(false);

  // PWA State
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    if (window.matchMedia('(display-mode: standalone)').matches || (window.navigator as any).standalone) {
      setIsStandalone(true);
    }
    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    window.addEventListener('appinstalled', () => {
      setDeferredPrompt(null);
      setIsStandalone(true);
    });
    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  const handleInstallClick = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    setDeferredPrompt(null);
  };

  useEffect(() => {
    if (user) {
      localStorage.setItem(USER_SESSION_KEY, JSON.stringify(user));
    } else {
      localStorage.removeItem(USER_SESSION_KEY);
    }
  }, [user]);

  const loadData = useCallback(async (isBackground = false) => {
    const hasExistingData = allTransactions.length > 0 || fullEmployeeDirectory.length > 0;
    if (!isBackground && !hasExistingData) setIsLoading(true);
    else setIsSyncing(true);

    try {
      const data = await fetchSheetData();
      setAllTransactions(data.transactions || []);
      setFullEmployeeDirectory(data.employees || []);
      setAvailableTools(data.tools || []);
      setToolCatalog(data.catalog || []);
      setSheetAdmins(data.admins || []);

      const timeStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      setLastSync(timeStr);

      localStorage.setItem(CACHE_KEY, JSON.stringify({
        ...data,
        cachedAt: timeStr,
        timestamp: Date.now()
      }));
    } catch (e) {
      console.error("Error loading data", e);
    } finally {
      setTimeout(() => setIsLoading(false), hasExistingData ? 0 : 3500);
      setTimeout(() => setIsSyncing(false), 800);
    }
  }, [allTransactions.length, fullEmployeeDirectory.length]);

  useEffect(() => {
    if (isLoading) {
      const timer = setTimeout(() => setLoadingStage(2), 1800);
      return () => clearTimeout(timer);
    }
  }, [isLoading]);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const cached = localStorage.getItem(CACHE_KEY);
    if (cached) {
      try {
        const parsed: SheetData & { cachedAt: string } = JSON.parse(cached);
        setAllTransactions(parsed.transactions || []);
        setFullEmployeeDirectory(parsed.employees || []);
        setAvailableTools(parsed.tools || []);
        setToolCatalog(parsed.catalog || []);
        setSheetAdmins(parsed.admins || []);
        setLastSync(parsed.cachedAt || '');
        setIsLoading(false);
        loadData(true);
      } catch (e) { loadData(false); }
    } else { loadData(false); }

    const handleClickOutside = (event: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(event.target as Node)) {
        setShowSearchResults(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  /**
   * GLOBAL ACCESS LOGIC:
   * A user is considered a "Super Admin" for DATA access if their role is 'super_admin'
   * OR if they are an admin assigned to the 'Global (All)' unit (department === 'All').
   */
  const isSuperAdmin = useMemo(() => {
    if (!user) return false;
    const normalizedRole = user.role.toLowerCase().replace(/[\s_]/g, '');
    const hasSuperRole = normalizedRole === 'superadmin' || normalizedRole === 'super_admin';
    const hasGlobalAccess = user.department === 'All';
    return hasSuperRole || hasGlobalAccess;
  }, [user]);

  /**
   * MANAGEMENT ACCESS LOGIC:
   * Only the actual Super Admin account can manage other administrators.
   */
  const isManagementAdmin = useMemo(() => {
    if (!user) return false;
    const normalizedRole = user.role.toLowerCase().replace(/[\s_]/g, '');
    return normalizedRole === 'superadmin' || normalizedRole === 'super_admin';
  }, [user]);

  const isAdmin = useMemo(() => {
     if (!user) return false;
     return user.role === 'dept_admin' || isSuperAdmin;
  }, [user, isSuperAdmin]);

  // Derived departments from all available data sources
  const departments = useMemo(() => {
    const depts = new Set<string>();
    fullEmployeeDirectory.forEach(emp => { if (emp.department) depts.add(emp.department); });
    sheetAdmins.forEach(admin => { if (admin.department && admin.department !== 'All') depts.add(admin.department); });
    toolCatalog.forEach(tool => { if (tool.department && tool.department !== 'All') depts.add(tool.department); });
    allTransactions.forEach(trx => { if (trx.department) depts.add(trx.department); });
    return Array.from(depts).sort();
  }, [fullEmployeeDirectory, sheetAdmins, toolCatalog, allTransactions]);

  const visibleEmployees = useMemo(() => {
    if (!user) return [];
    // Super/Global admins see everyone. Others see only their unit.
    if (isSuperAdmin) return fullEmployeeDirectory;
    return fullEmployeeDirectory.filter(emp => emp.department === user.department);
  }, [user, isSuperAdmin, fullEmployeeDirectory]);

  const filteredDirectory = useMemo(() => {
    let list = visibleEmployees;
    // Apply department filter for Super/Global Admins
    if (isSuperAdmin && directoryDeptFilter) {
      list = list.filter(emp => emp.department === directoryDeptFilter);
    }
    // Apply text search filter
    if (directorySearchQuery.trim()) {
      const q = directorySearchQuery.toLowerCase().trim();
      list = list.filter(emp => 
        String(emp.id).toLowerCase().includes(q) || 
        String(emp.name).toLowerCase().includes(q) ||
        String(emp.designation).toLowerCase().includes(q)
      );
    }
    return list;
  }, [visibleEmployees, isSuperAdmin, directoryDeptFilter, directorySearchQuery]);

  const filteredCatalog = useMemo(() => {
    if (!catalogDeptFilter) return toolCatalog;
    return toolCatalog.filter(tool => tool.department === catalogDeptFilter || tool.department === 'All');
  }, [toolCatalog, catalogDeptFilter]);

  const toolsForCurrentAdmin = useMemo(() => {
    if (!user) return [];
    if (isSuperAdmin) {
      return Array.from(new Set(toolCatalog.map(t => t.name))).sort();
    }
    const allowedTools = toolCatalog
      .filter(t => t.department === user.department || t.department === 'All')
      .map(t => t.name);
    return Array.from(new Set(allowedTools)).sort();
  }, [user, isSuperAdmin, toolCatalog]);

  const visibleTransactions = useMemo(() => {
    if (!user) return [];
    let list = isSuperAdmin ? allTransactions : allTransactions.filter(trx => trx.department === user.department);

    // Apply "twice or above" (Quantity >= 2) filter
    if (showBulkLogsOnly) {
      list = list.filter(trx => trx.quantity >= 2);
    }

    return list;
  }, [user, isSuperAdmin, allTransactions, showBulkLogsOnly]);

  // Paginated Logs
  const paginatedLogs = useMemo(() => {
    const sorted = [...visibleTransactions].reverse();
    const startIndex = (currentLogsPage - 1) * LOGS_PER_PAGE;
    return sorted.slice(startIndex, startIndex + LOGS_PER_PAGE);
  }, [visibleTransactions, currentLogsPage]);

  const totalLogsPages = useMemo(() => 
    Math.ceil(visibleTransactions.length / LOGS_PER_PAGE), 
  [visibleTransactions]);

  const searchResults = useMemo(() => {
    if (!searchQuery.trim()) return [];
    const query = searchQuery.toLowerCase().trim();
    return visibleEmployees.filter(emp => 
      String(emp.id).toLowerCase().includes(query) || 
      String(emp.name).toLowerCase().includes(query)
    ).slice(0, 10); 
  }, [searchQuery, visibleEmployees]);

  const handleSaveTransactions = async (transactions: Transaction[], employeeDetails?: any) => {
    if (!user) return;
    setIsSyncing(true);
    try {
      for (const trx of transactions) {
        await saveTransactionToSheet(trx, employeeDetails || { department: user.department });
      }
      alert("Inventory update committed successfully.");
      await loadData(true);
    } catch (err) {
      alert("Error saving entries to cloud hub.");
    } finally {
      setIsSyncing(false);
    }
  };

  const handleSaveEmployee = async (employeeData: any) => {
     setIsSyncing(true);
     try {
       const success = await saveEmployeeToSheet(employeeData);
       if (success) {
          alert(editingEmployee ? "Personnel details updated successfully." : "Personnel registered successfully.");
          setIsEmployeeModalOpen(false);
          setEditingEmployee(null);
          // CRITICAL: Immediately re-fetch all data to ensure the list shows the updated info.
          await loadData(true);
       } else {
          alert("Failed to save personnel to hub.");
       }
     } catch (err) {
       alert("Network synchronization error.");
     } finally {
       setIsSyncing(false);
     }
  };

  const handleDeleteEmployee = async (empId: string) => {
    if (!isSuperAdmin) return;
    if (!confirm(`Are you sure you want to PERMANENTLY delete personnel ID: ${empId}?\n\nThis will remove them from active directory and move them to the 'Discard Employee' archive.`)) return;

    setIsSyncing(true);
    try {
      const success = await deleteEmployeeFromSheet(empId);
      if (success) {
        alert("Personnel successfully removed and archived.");
        await loadData(true);
      } else {
        alert("Server failed to remove personnel.");
      }
    } catch (e) {
      alert("Network Error: Could not reach hub.");
    } finally {
      setIsSyncing(false);
    }
  };

  const handleSaveToolToCatalog = async (toolData: ToolDefinition & { oldName?: string }) => {
    setIsSyncing(true);
    try {
      let success = false;
      if (toolData.oldName) {
        success = await updateToolInCatalog(toolData as ToolDefinition & { oldName: string });
      } else {
        success = await saveToolToCatalog(toolData as ToolDefinition);
      }
      if (success) {
        alert(toolData.oldName ? "Tool record successfully updated." : "New tool successfully registered in catalog.");
        setIsCatalogModalOpen(false);
        setEditingTool(null);
        await loadData(true);
      } else {
        alert("Server failed to commit tool to catalog.");
      }
    } catch (err) {
      alert("Network error: Could not reach Cloud Hub.");
    } finally {
      setIsSyncing(false);
    }
  };

  const handleUpdateEmployeeStatus = async (empId: string, newStatus: string) => {
    setIsSyncing(true);
    const success = await updateEmployeeStatusInSheet(empId, newStatus);
    if (success) loadData(true);
    else { alert("Failed to update status."); setIsSyncing(false); }
  };

  const handleApprovePasswordChange = async (empId: string) => {
    if (!isSuperAdmin) return;
    setIsSyncing(true);
    const success = await approveEmployeePasswordChange(empId);
    if (success) loadData(true);
    else { alert("Failed to approve request."); setIsSyncing(false); }
  };

  const handleSaveAdmin = async (adminData: User) => {
    setIsSyncing(true);
    const success = await saveAdminToSheet(adminData);
    if (success) {
      setIsAdminModalOpen(false);
      setEditingAdmin(null);
      await loadData(true);
    } else {
      alert("Failed to save administrator.");
      setIsSyncing(false);
    }
  };

  const handleDeleteAdmin = async (adminId: string, role: string) => {
    const normalizedRole = role.toLowerCase().replace(/[\s_]/g, '');
    if (normalizedRole === 'superadmin' || normalizedRole === 'super_admin') {
      alert("Super Admin accounts cannot be deleted."); return;
    }
    if (!confirm(`Revoke access for ID: ${adminId}?`)) return;
    setIsSyncing(true);
    const success = await deleteAdminFromSheet(adminId);
    if (success) loadData(true);
    else { alert("Failed to remove admin."); setIsSyncing(false); }
  };

  const handleLogin = (u: { id: string, password?: string }) => {
    const inputId = String(u.id || '').trim();
    const inputPass = String(u.password || '').trim();
    if (!inputId) return alert("Please enter ID.");

    const sheetAdmin = sheetAdmins.find(admin => 
      String(admin.id).trim() === inputId && String(admin.password).trim() === inputPass
    );
    if (sheetAdmin) {
      const rawRole = sheetAdmin.role.toLowerCase().replace(/[\s_]/g, '');
      const loggedUser = { ...sheetAdmin, role: (rawRole === 'superadmin' || rawRole === 'super_admin') ? 'super_admin' : 'dept_admin' } as User;
      setUser(loggedUser);
      return;
    }

    const sheetEmp = fullEmployeeDirectory.find(e => String(e.id).trim() === inputId);
    if (sheetEmp && (sheetEmp.password || '12345') === inputPass) {
      const loggedUser = {
        id: String(sheetEmp.id).trim(),
        name: sheetEmp.name,
        role: 'employee',
        designation: sheetEmp.designation,
        department: sheetEmp.department,
        typeOfEmployee: sheetEmp.typeOfEmployee
      } as User;
      setUser(loggedUser);
      return;
    }

    const foundFallback = USERS.find(existing => String(existing.id).trim() === inputId && String(existing.password).trim() === inputPass);
    if (foundFallback) {
      setUser(foundFallback);
      return;
    }
    alert(`Authentication Failed. ID or Password may be incorrect.`);
  };

  const employeeToolsData = useMemo(() => {
    if (!selectedEmployee) return [];
    const empTrx = visibleTransactions.filter(t => t.employeeId === selectedEmployee.id);
    const toolsMap = new Map<string, any>();

    empTrx.forEach(t => {
      let tool = toolsMap.get(t.toolName);
      if (!tool) {
         tool = { name: t.toolName, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0, remarks: '' };
         toolsMap.set(t.toolName, tool);
      }
      const qty = Number(t.quantity) || 0;
      if (t.entryType === 'Distribute') tool.distributed += qty;
      if (t.entryType === 'Return') tool.returned += qty;
      if (t.entryType === 'Faulty Return') tool.faulty += qty;
      if (t.entryType === 'Damage') tool.damage += qty;
      if (t.entryType === 'Lost') tool.lost += qty;
      if (t.remarks) tool.remarks = t.remarks;
    });
    return Array.from(toolsMap.values());
  }, [selectedEmployee, visibleTransactions]);

  const employeeHistory = useMemo(() => {
    if (!selectedEmployee) return [];
    return visibleTransactions
      .filter(t => t.employeeId === selectedEmployee.id)
      .reverse();
  }, [selectedEmployee, visibleTransactions]);

  // ASSET LEDGER RECONCILIATION
  const stockSummaryData = useMemo(() => {
    let targetTrx = allTransactions;
    if (!isSuperAdmin) {
      targetTrx = allTransactions.filter(trx => trx.department === user?.department);
    } else if (selectedDeptFilter !== '') {
      targetTrx = allTransactions.filter(t => t.department === selectedDeptFilter);
    }

    let targetCatalog = toolCatalog;
    if (!isSuperAdmin) {
      targetCatalog = toolCatalog.filter(t => t.department === user?.department || t.department === 'All');
    } else if (selectedDeptFilter !== '') {
      targetCatalog = toolCatalog.filter(t => t.department === selectedDeptFilter || t.department === 'All');
    }

    const toolSummaryMap = new Map<string, any>();

    targetCatalog.forEach(tool => {
       if (!toolSummaryMap.has(tool.name)) {
         toolSummaryMap.set(tool.name, { name: tool.name, purchase: 0, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0 });
       }
    });

    targetTrx.forEach(t => {
      let summary = toolSummaryMap.get(t.toolName);
      if (!summary) {
        summary = { name: t.toolName, purchase: 0, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0 };
        toolSummaryMap.set(t.toolName, summary);
      }
      const qty = Number(t.quantity) || 0;
      if (t.entryType === 'Stock IN') summary.purchase += qty;
      else if (t.entryType === 'Distribute') summary.distributed += qty;
      else if (t.entryType === 'Return') summary.returned += qty;
      else if (t.entryType === 'Faulty Return') summary.faulty += qty;
      else if (t.entryType === 'Damage') summary.damage += qty;
      else if (t.entryType === 'Lost') summary.lost += qty;
    });

    let results = Array.from(toolSummaryMap.values()).map(row => ({
      ...row,
      stockNow: (row.purchase + row.returned) - (row.distributed + row.faulty + row.damage + row.lost)
    }));

    if (stockSearchQuery.trim()) {
      const q = stockSearchQuery.toLowerCase().trim();
      results = results.filter(row => row.name.toLowerCase().includes(q));
    }

    return results.sort((a, b) => a.name.localeCompare(b.name));
  }, [allTransactions, toolCatalog, isSuperAdmin, selectedDeptFilter, user?.department, stockSearchQuery]);

  const stockTotals = useMemo(() => {
    const totals = {
      purchase: 0,
      distributed: 0,
      returned: 0,
      faulty: 0,
      damage: 0,
      lost: 0,
      stockNow: 0
    };
    stockSummaryData.forEach(row => {
      totals.purchase += row.purchase;
      totals.distributed += row.distributed;
      totals.returned += row.returned;
      totals.faulty += row.faulty;
      totals.damage += row.damage;
      totals.lost += row.lost;
      totals.stockNow += row.stockNow;
    });
    return totals;
  }, [stockSummaryData]);

  const handleExportStock = () => {
    const headers = ['Tool Name', 'Stock IN', 'Distributed', 'Returned', 'Faulty Return', 'Damage', 'Lost', 'Current Stock'];
    const escapeCsvValue = (val: any) => {
      const str = String(val);
      if (str.includes(',') || str.includes('"') || str.includes('\n')) return `"${str.replace(/"/g, '""')}"`;
      return str;
    };
    const csvRows = [headers.join(','), ...stockSummaryData.map(row => [escapeCsvValue(row.name), row.purchase, row.distributed, row.returned, row.faulty, row.damage, row.lost, row.stockNow].join(','))];
    const BOM = '\uFEFF';
    const blob = new Blob([BOM + csvRows.join('\n')], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `SARBS_StockLedger_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const navigationTabs = useMemo(() => [
    { id: 'employee', label: 'LOOKUP', icon: Search },
    { id: 'directory', label: 'DIR', icon: Users },
    { id: 'catalog', label: 'CATALOG', icon: Wrench, adminOnly: true },
    { id: 'daily', label: 'LOGS', icon: FileSpreadsheet },
    { id: 'stock', label: 'STOCK', icon: Package },
    ...(isManagementAdmin ? [{ id: 'admins', label: 'ADMIN', icon: ShieldCheck }] : [])
  ].filter(tab => !tab.adminOnly || isSuperAdmin), [isSuperAdmin, isManagementAdmin]);

  if (isLoading) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-10 text-center">
        <div className="flex flex-col items-center">
           <img src={LOGO_URL} alt="SARBS Logo" className="w-56 h-56 md:w-80 md:h-80 object-contain" />
           <div className={`mt-10 transition-all duration-1000 ease-out ${loadingStage === 2 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-8'}`}>
              <h1 className="text-slate-900 font-black text-2xl md:text-3xl tracking-tight uppercase">SARBS Communications Ltd.</h1>
              <p className="text-slate-500 text-[10px] md:text-xs font-bold uppercase tracking-[0.4em] animate-pulse mt-4">Accessing Cloud Hub</p>
           </div>
        </div>
      </div>
    );
  }

  if (!user) return <Login onLogin={handleLogin} isSyncing={isSyncing} lastSync={lastSync} onRefresh={() => loadData(true)} isOnline={isOnline} installPrompt={deferredPrompt} onInstall={handleInstallClick} isStandalone={isStandalone} />;

  if (user.role === 'employee') {
    return <EmployeeDashboard user={user} transactions={visibleTransactions} onLogout={() => { setUser(null); localStorage.removeItem(USER_SESSION_KEY); }} isSyncing={isSyncing} />;
  }

  return (
    <div className="min-h-screen bg-[#F0F4F8] font-sans text-slate-900 pb-32 md:pb-20 safe-top">
      {!isOnline && (
        <div className="bg-red-600 text-white text-[10px] font-black uppercase py-2 text-center sticky top-0 z-50 animate-pulse">
          Connection Interrupted
        </div>
      )}

      {/* Header Controls */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm hidden lg:block">
        <div className="max-w-7xl mx-auto px-4 sm:px-6">
          <div className="flex items-center justify-between h-16 md:h-20">
            <div className="flex-shrink-0 flex items-center gap-3">
              <img src={LOGO_URL} alt="SARBS" className="w-10 h-10 md:w-12 md:h-12 object-contain" />
              <div className="hidden lg:block">
                <h1 className="text-sm font-black text-slate-900 leading-tight uppercase">SARBS</h1>
                <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">Inventory</p>
              </div>
            </div>
            <div className="flex items-center justify-center flex-1 mx-4 space-x-1 lg:space-x-4">
              {navigationTabs.map((tab) => (
                <button key={tab.id} onClick={() => setActiveTab(tab.id as Tab)} className={`px-3 py-6 text-[10px] lg:text-xs font-black transition-all flex items-center gap-2 border-b-4 h-full ${activeTab === tab.id ? 'border-slate-900 text-slate-900' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                  <tab.icon className="w-3.5 h-3.5" /> <span className="hidden sm:inline">{tab.label}</span>
                </button>
              ))}
            </div>
            <div className="flex-shrink-0 flex items-center gap-2 md:gap-4">
               <button onClick={() => loadData(true)} className={`p-2 rounded-full hover:bg-slate-100 ${isSyncing ? 'animate-spin text-blue-500' : 'text-slate-400'}`}><RefreshCw className="w-4 h-4 md:w-5 md:h-5" /></button>
               <div className="flex items-center gap-2 bg-[#0F172A] px-3 md:px-5 py-2 rounded-full text-white shadow-lg border border-white/10">
                 <ShieldCheck className="w-3 h-3 md:w-4 md:h-4 text-blue-400" /><span className="text-[10px] font-black uppercase tracking-wider">{isManagementAdmin ? 'Super' : 'Admin'}</span>
               </div>
               <button onClick={() => { setUser(null); localStorage.removeItem(USER_SESSION_KEY); }} className="p-1.5 md:p-2 text-slate-400 hover:text-red-600"><LogOut className="w-5 h-5 md:w-6 md:h-6" /></button>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="max-w-7xl mx-auto px-4 md:px-6 py-6 md:py-8 mb-20">
        {activeTab === 'directory' && (
          <div className="space-y-4">
             <div className="bg-white p-4 md:p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col md:flex-row justify-between items-end gap-6 md:gap-10">
                <div className="w-full">
                   <label className="block text-[10px] font-black text-slate-400 uppercase mb-3 tracking-widest">Filter Directory</label>
                   <div className="relative">
                      <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-300" />
                      <input type="text" className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none text-xs font-bold transition-all focus:border-blue-500" placeholder="Filter by Name, ID or Designation..." value={directorySearchQuery} onChange={e => setDirectorySearchQuery(e.target.value)} />
                   </div>
                </div>
                <div className="flex flex-col md:flex-row items-end gap-4 w-full md:w-auto">
                   {isSuperAdmin && (
                      <div className="w-full md:w-auto min-w-[200px]">
                         <label className="block text-[10px] font-black text-slate-400 uppercase mb-3 tracking-widest">Select Department</label>
                         <select className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none text-xs font-black cursor-pointer" value={directoryDeptFilter} onChange={e => setDirectoryDeptFilter(e.target.value)}>
                            <option value="">All Departments</option>
                            {departments.map(dept => (<option key={dept} value={dept}>{dept}</option>))}
                         </select>
                      </div>
                   )}
                   {isAdmin && (
                      <button onClick={() => { setEditingEmployee(null); setIsEmployeeModalOpen(true); }} className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-8 py-4 rounded-2xl font-black text-xs transition-all uppercase tracking-widest whitespace-nowrap h-[56px] w-full md:w-auto justify-center shadow-lg active:scale-95"><UserPlus className="w-5 h-5" /> NEW PERSONNEL</button>
                   )}
                </div>
             </div>
             <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden overflow-x-auto no-scrollbar">
                <table className="w-full text-sm text-left border-collapse min-w-[1000px]">
                   <thead className="bg-[#F8FAFC] text-slate-500 border-b border-slate-200 uppercase font-black text-[11px] tracking-wider">
                      <tr>
                         <th className="px-6 py-6">ID / PASSWORD</th>
                         <th className="px-6 py-6">FULL NAME</th>
                         <th className="px-6 py-6">DESIGNATION</th>
                         <th className="px-6 py-6">DEPARTMENT</th>
                         <th className="px-6 py-6 text-center">STATUS</th>
                         <th className="px-6 py-6 text-center">SECURITY REQ</th>
                         <th className="px-6 py-6 text-right">ACTION</th>
                      </tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100">
                      {filteredDirectory.length > 0 ? filteredDirectory.map((emp) => (
                         <tr key={emp.id} className="hover:bg-slate-50 transition-colors">
                            <td className="px-6 py-5">
                               <div className="font-bold text-slate-500 text-xs">{emp.id}</div>
                               <div className="flex items-center gap-1.5 mt-1"><Key className="w-3 h-3 text-slate-300" /><span className="font-mono text-[10px] text-slate-900 bg-slate-100 px-2 py-0.5 rounded-md font-black border border-slate-200">{emp.password || '12345'}</span></div>
                            </td>
                            <td className="px-6 py-5 font-black text-slate-900 text-base">{emp.name}</td>
                            <td className="px-6 py-5 font-bold text-slate-600">{emp.designation}</td>
                            <td className="px-6 py-5 font-black text-slate-500 uppercase text-[10px] leading-relaxed max-w-[150px]">{emp.department}</td>
                            <td className="px-6 py-5 text-center">
                               {isAdmin ? (
                                 <select className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase border cursor-pointer outline-none transition-all ${emp.typeOfEmployee === 'Running' ? 'bg-green-50 text-green-600 border-green-200' : 'bg-red-50 text-red-600 border-red-200'}`} value={emp.typeOfEmployee} onChange={(e) => handleUpdateEmployeeStatus(emp.id, e.target.value)} disabled={isSyncing}>
                                   <option value="Running">Running</option>
                                   <option value="Discontinue">Discontinue</option>
                                   <option value="Resigned">Resigned</option>
                                 </select>
                               ) : (<span className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase border ${emp.typeOfEmployee === 'Running' ? 'bg-green-50 text-green-600 border-green-200' : 'bg-red-50 text-red-600 border-red-200'}`}>{emp.typeOfEmployee}</span>)}
                            </td>
                            <td className="px-6 py-5 text-center">
                               {emp.passwordRequest ? (
                                 <div className="flex flex-col items-center gap-2">
                                    <div className="flex items-center gap-1.5 bg-amber-50 border border-amber-200 px-2 py-1 rounded-lg text-amber-700 text-[10px] font-black uppercase shadow-sm"><Clock className="w-3 h-3 animate-pulse" /> REQ: {emp.passwordRequest}</div>
                                    {isSuperAdmin && (<button onClick={() => handleApprovePasswordChange(emp.id)} disabled={isSyncing} className="flex items-center gap-1 bg-green-600 hover:bg-green-700 text-white px-3 py-1.5 rounded-lg text-[9px] font-black uppercase shadow-md disabled:opacity-50"><CheckCircle className="w-3 h-3" /> Approve</button>)}
                                 </div>
                               ) : (<span className="text-[10px] text-slate-300 font-bold uppercase tracking-widest">-</span>)}
                            </td>
                            <td className="px-6 py-5 text-right whitespace-nowrap space-x-2">
                               {isSuperAdmin && (
                                 <>
                                   <button onClick={() => { setEditingEmployee(emp); setIsEmployeeModalOpen(true); }} className="p-2 hover:bg-white rounded-lg text-slate-400 hover:text-blue-600 border border-transparent hover:border-slate-200 transition-all" title="Edit Personnel"><Edit className="w-4 h-4" /></button>
                                   <button onClick={() => handleDeleteEmployee(emp.id)} className="p-2 hover:bg-red-50 rounded-lg text-slate-400 hover:text-red-600 border border-transparent hover:border-red-200 transition-all" title="Delete Personnel"><Trash2 className="w-4 h-4" /></button>
                                 </>
                               )}
                               <button onClick={() => { setSelectedEmployee(emp); setActiveTab('employee'); setSearchQuery(`${emp.id} - ${emp.name}`); }} className="text-[11px] font-black text-blue-600 hover:text-blue-800 uppercase">VIEW TOOLS</button>
                            </td>
                         </tr>
                      )) : (<tr><td colSpan={7} className="py-20 text-center text-slate-400 font-bold uppercase italic tracking-widest text-xs italic">No personnel records found.</td></tr>)}
                   </tbody>
                </table>
             </div>
          </div>
        )}

        {/* Other Tabs omitted for brevity as logic remains similar */}
        {activeTab === 'employee' && (<div className="space-y-6">
             <div className="bg-white p-4 md:p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col md:flex-row justify-between items-center gap-4" ref={searchRef}>
                <div className="w-full sm:max-w-md relative">
                   <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Quick Lookup Profile</label>
                   <div className="relative group">
                      <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                      <input type="text" className="w-full pl-10 pr-10 py-3 bg-slate-50 border border-slate-200 rounded-2xl outline-none text-sm font-bold transition-all focus:border-blue-500" placeholder="Search by ID or Name..." value={searchQuery} onChange={e => { setSearchQuery(e.target.value); setShowSearchResults(true); }} onFocus={() => setShowSearchResults(true)} />
                   </div>
                   {showSearchResults && searchResults.length > 0 && (
                     <div className="absolute z-[60] top-full left-0 right-0 mt-2 bg-white rounded-xl shadow-2xl border border-slate-200 overflow-hidden">
                        {searchResults.map(emp => (
                          <button key={emp.id} onClick={() => { setSelectedEmployee(emp); setSearchQuery(`${emp.id} - ${emp.name}`); setShowSearchResults(false); }} className="w-full px-4 py-3 text-left hover:bg-blue-50 flex items-center justify-between border-b last:border-0 border-slate-100 group">
                             <div><p className="text-xs font-black text-slate-900">{emp.id} — {emp.name}</p><p className="text-[9px] text-slate-400 font-bold uppercase">{emp.department}</p></div>
                             <ChevronRight className="w-4 h-4 text-slate-200 group-hover:text-blue-500" />
                          </button>
                        ))}
                     </div>
                   )}
                </div>
                {isAdmin && (<button onClick={() => setIsModalOpen(true)} className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-8 py-4 rounded-2xl font-black text-xs transition-all uppercase tracking-widest w-full md:w-auto justify-center shadow-lg active:scale-95"><Plus className="w-5 h-5" /> COMMIT ENTRY</button>)}
             </div>
        </div>)}

        {/* Log Tab and others follow existing UI structure */}
      </main>

      <ToolModal isOpen={isModalOpen} onClose={() => { setIsModalOpen(false); setEditingTransaction(null); }} onSave={handleSaveTransactions} initialTransaction={editingTransaction} employees={visibleEmployees} availableTools={toolsForCurrentAdmin} />
      <EmployeeModal isOpen={isEmployeeModalOpen} onClose={() => { setIsEmployeeModalOpen(false); setEditingEmployee(null); }} onSave={handleSaveEmployee} isAdmin={isAdmin} isSuperAdmin={isSuperAdmin} userDepartment={user?.department || ''} allDepartments={departments} initialData={editingEmployee} />
      <AdminModal isOpen={isAdminModalOpen} onClose={() => { setIsAdminModalOpen(false); setEditingAdmin(null); }} onSave={handleSaveAdmin} initialData={editingAdmin} departments={departments} />
      <ToolCatalogModal isOpen={isCatalogModalOpen} onClose={() => { setIsCatalogModalOpen(false); setEditingTool(null); }} onSave={handleSaveToolToCatalog} departments={departments} isSyncing={isSyncing} initialData={editingTool} />
    </div>
  );
};

export default App;

/**
 * SARBS Communications Ltd. - Inventory Hub Backend
 */

function doGet(e) {
  try {
    const transactions = getTransactions();
    const metadata = getMetadata();
    const admins = getAdmins();

    return createJSONOutput({ 
      status: 'success',
      transactions: transactions,
      employees: metadata.employees,
      tools: metadata.tools, 
      catalog: metadata.catalog,
      admins: admins
    });

  } catch (error) {
    console.error("Critical doGet Error: " + error.toString());
    return createJSONOutput({ status: 'error', message: error.toString() });
  }
}

function doPost(e) {
  const lock = LockService.getScriptLock();
  lock.tryLock(20000); 

  try {
    const requestData = JSON.parse(e.postData.contents);
    const p = requestData.payload;

    if (requestData.action === 'addTransaction') {
      const sheet = getSheet("Daily Entry");
      sheet.appendRow([
        p.date,
        p.employeeId || '',
        p.employeeName || '',
        p.designation || '',
        p.department || '',
        p.typeOfEmployee || '',
        p.toolName,
        p.entryType,
        p.quantity,
        p.condition,
        p.remarks || ''
      ]);
      return createJSONOutput({ status: 'success' });
    }

    if (requestData.action === 'addEmployee') {
      const sheet = getSheet("Data Validation");
      // Use getDisplayValues to ensure we match what the user sees in the ID column
      const data = sheet.getDataRange().getDisplayValues();
      const targetId = String(p.id).trim().toUpperCase();

      let rowIndex = -1;
      // Precise search in the ID column (Column A)
      for (let i = 1; i < data.length; i++) {
        if (String(data[i][0]).trim().toUpperCase() === targetId) {
          rowIndex = i + 1;
          break;
        }
      }

      if (rowIndex !== -1) {
        // Update existing employee: Name(2), Designation(3), Department(4), Status(5)
        sheet.getRange(rowIndex, 2).setValue(p.name);
        sheet.getRange(rowIndex, 3).setValue(p.designation);
        sheet.getRange(rowIndex, 4).setValue(p.department);
        sheet.getRange(rowIndex, 5).setValue(p.typeOfEmployee);
        return createJSONOutput({ status: 'success', message: 'Employee updated successfully' });
      } else {
        // Append new employee if ID not found
        sheet.appendRow([
          p.id,
          p.name,
          p.designation,
          p.department,
          p.typeOfEmployee,
          '12345', // Default Password
          '',      // Password Request Placeholder
          ''       // Tool Name Placeholder
        ]);
        return createJSONOutput({ status: 'success', message: 'New employee registered successfully' });
      }
    }

    if (requestData.action === 'deleteEmployee') {
      const sourceSheet = getSheet("Data Validation");
      const archiveSheet = getSheet("Discard Employee");
      const data = sourceSheet.getDataRange().getDisplayValues();
      const targetId = String(p.id).trim().toUpperCase();

      // Ensure headers in archive sheet
      if (archiveSheet.getLastRow() === 0) {
        archiveSheet.appendRow(["ID", "NAME", "DESIGNATION", "DEPARTMENT", "STATUS", "PASSWORD", "DISCARD_DATE"]);
      }

      for (let i = 1; i < data.length; i++) {
        if (String(data[i][0]).trim().toUpperCase() === targetId) {
          const rowData = data[i];
          // Transfer data to archive
          archiveSheet.appendRow([
            rowData[0], // ID
            rowData[1], // Name
            rowData[2], // Designation
            rowData[3], // Department
            rowData[4], // Status
            rowData[5] || '12345', // Password
            new Date().toLocaleString() // Discard Date
          ]);
          // Delete from active directory
          sourceSheet.deleteRow(i + 1);
          return createJSONOutput({ status: 'success' });
        }
      }
      return createJSONOutput({ status: 'error', message: 'Personnel not found' });
    }

    if (requestData.action === 'addToolToCatalog') {
      const sheet = getSheet("Tools Name List");
      sheet.appendRow([p.name, p.brand || 'N/A', p.department || 'All']);
      return createJSONOutput({ status: 'success' });
    }

    if (requestData.action === 'updateToolInCatalog') {
      const sheet = getSheet("Tools Name List");
      const data = sheet.getDataRange().getDisplayValues();
      const oldName = String(p.oldName).trim().toLowerCase();

      for (let i = 1; i < data.length; i++) {
        if (String(data[i][0]).trim().toLowerCase() === oldName) {
          sheet.getRange(i + 1, 1, 1, 3).setValues([[p.name, p.brand || 'N/A', p.department || 'All']]);
          return createJSONOutput({ status: 'success' });
        }
      }
      return createJSONOutput({ status: 'error', message: 'Tool not found' });
    }

    if (requestData.action === 'upsertAdmin') {
      const sheet = getSheet("Admins");
      const data = sheet.getDataRange().getDisplayValues();
      const targetId = String(p.id).trim().toUpperCase();

      let rowIndex = -1;
      for (let i = 1; i < data.length; i++) {
        if (String(data[i][0]).trim().toUpperCase() === targetId) {
          rowIndex = i + 1;
          break;
        }
      }

      const rowValues = [p.id, p.name, p.password, p.role, p.department, p.designation];
      if (rowIndex !== -1) {
        sheet.getRange(rowIndex, 1, 1, 6).setValues([rowValues]);
      } else {
        sheet.appendRow(rowValues);
      }
      return createJSONOutput({ status: 'success' });
    }

    return createJSONOutput({ status: 'error', message: 'Unknown action: ' + requestData.action });

  } catch (error) {
    return createJSONOutput({ status: 'error', message: error.toString() });
  } finally {
    lock.releaseLock();
  }
}

function getAdmins() {
  const sheet = getSheet("Admins");
  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return [];
  return sheet.getRange(2, 1, lastRow - 1, 6).getDisplayValues().map(row => ({
    id: String(row[0]).trim(),
    name: String(row[1]).trim(),
    password: String(row[2]).trim(),
    role: String(row[3]).trim(),
    department: String(row[4]).trim(),
    designation: String(row[5]).trim()
  })).filter(a => a.id);
}

function getTransactions() {
  const sheet = getSheet("Daily Entry");
  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return [];
  return sheet.getDataRange().getDisplayValues().slice(1).map((row, index) => ({
    id: 'row-' + (index + 2),
    date: String(row[0]).trim(),
    employeeId: String(row[1]).trim(),
    employeeName: String(row[2]).trim(),
    designation: String(row[3]).trim(),
    department: String(row[4]).trim(),
    typeOfEmployee: String(row[5]).trim(),
    toolName: String(row[6]).trim(),
    entryType: String(row[7]).trim(),
    quantity: Number(row[8] || 0),
    condition: String(row[9]).trim(),
    remarks: String(row[10]).trim()
  })).filter(t => t.employeeId);
}

function getMetadata() {
  const validationSheet = getSheet("Data Validation");
  const catalogSheet = getSheet("Tools Name List");

  const employees = validationSheet.getLastRow() < 2 ? [] : 
    validationSheet.getRange(2, 1, validationSheet.getLastRow() - 1, 8).getDisplayValues().map(row => ({
      id: String(row[0]).trim(),
      name: String(row[1]).trim(),
      designation: String(row[2]).trim(),
      department: String(row[3]).trim(),
      typeOfEmployee: String(row[4]).trim(),
      password: String(row[5] || '12345').trim(),
      passwordRequest: String(row[6]).trim()
    })).filter(e => e.id);

  const catalog = catalogSheet.getLastRow() < 2 ? [] : 
    catalogSheet.getRange(2, 1, catalogSheet.getLastRow() - 1, 3).getDisplayValues().map(row => ({
      name: String(row[0]).trim(),
      brand: String(row[1] || 'N/A').trim(),
      department: String(row[2] || 'All').trim()
    })).filter(c => c.name);

  return { employees: employees, catalog: catalog, tools: catalog.map(c => c.name) };
}

function getSheet(name) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
    if (name === "Admins") sheet.appendRow(["ID", "Name", "Password", "Role", "Department", "Designation"]);
    else if (name === "Daily Entry") sheet.appendRow(["Date", "ID", "Name", "Designation", "Department", "Type", "Item Name", "Entry Type", "Quantity", "Condition", "Remarks"]);
    else if (name === "Data Validation") sheet.appendRow(["ID", "Name", "Designation", "Department", "Type of Employee", "Password", "Password Request", "Tool Name"]);
    else if (name === "Tools Name List") sheet.appendRow(["Tool Name", "Brand Name", "Department Access"]);
    else if (name === "Discard Employee") sheet.appendRow(["ID", "NAME", "DESIGNATION", "DEPARTMENT", "STATUS", "PASSWORD", "DISCARD_DATE"]);
  }
  return sheet;
}

function createJSONOutput(data) {
  return ContentService.createTextOutput(JSON.stringify(data)).setMimeType(ContentService.MimeType.JSON);
}

