      } else {
        alert("Server failed to remove personnel.");
      }
    } catch (e) {
      alert("Network Error: Could not reach hub.");
    } finally {
      setIsSyncing(false);
    }
  };

  const handleSaveToolToCatalog = async (toolData: ToolDefinition & { oldName?: string }) => {
    setIsSyncing(true);
    try {
      let success = false;
      if (toolData.oldName) {
        success = await updateToolInCatalog(toolData as ToolDefinition & { oldName: string });
