            </div>
            <div className="flex-shrink-0 flex items-center gap-2 md:gap-4">
               <button onClick={() => loadData(true)} className={`p-2 rounded-full hover:bg-slate-100 ${isSyncing ? 'animate-spin text-blue-500' : 'text-slate-400'}`}><RefreshCw className="w-4 h-4 md:w-5 md:h-5" /></button>
