               <button onClick={() => { setUser(null); localStorage.removeItem(USER_SESSION_KEY); }} className="p-1.5 md:p-2 text-slate-400 hover:text-red-600"><LogOut className="w-5 h-5 md:w-6 md:h-6" /></button>
