              <div><h2 className="text-sm font-black uppercase">Activity Log</h2><button onClick={() => setShowBulkLogsOnly(!showBulkLogsOnly)} className={`text-[9px] font-black uppercase mt-1 ${showBulkLogsOnly ? 'text-amber-600' : 'text-slate-400'}`}>Bulk Filter: {showBulkLogsOnly ? 'Active' : 'Off'}</button></div>
              <button onClick={() => setIsModalOpen(true)} className="bg-slate-900 text-white px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl">New Entry</button>
            </div>
            <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden overflow-x-auto">
              <table className="w-full text-[11px] text-left min-w-[800px]">
