                  <tr><th className="px-6 py-4">Date</th><th className="px-6 py-4">Personnel</th><th className="px-6 py-4">Item</th><th className="px-4 py-4 text-center">Type</th><th className="px-4 py-4 text-center">Qty</th><th className="px-6 py-4">Remarks</th></tr>
