            </div>
            <table className="w-full text-xs text-left min-w-[800px]">
              <thead className="bg-[#F8FAFC] text-slate-400 uppercase font-black tracking-widest">
                <tr><th className="px-8 py-5">ID</th><th className="px-8 py-5">Name</th><th className="px-8 py-5">Role</th><th className="px-8 py-5">Unit</th><th className="px-8 py-5 text-center">Action</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {sheetAdmins.map(a => (
                  <tr key={a.id} className="hover:bg-indigo-50/50 transition-colors">
                    <td className="px-8 py-4 font-mono font-black text-slate-500">{a.id}</td>
                    <td className="px-8 py-4 font-black text-slate-900">{a.name}</td>
                    <td className="px-8 py-4"><span className={`px-2 py-1 rounded text-[9px] font-black uppercase ${a.role.includes('super') ? 'bg-indigo-900 text-white' : 'bg-white text-amber-600 border'}`}>{a.role}</span></td>
                    <td className="px-8 py-4 font-black text-slate-600">{a.department}</td>
                    <td className="px-8 py-4 text-center space-x-2">
                      <button onClick={() => { setEditingAdmin(a); setIsAdminModalOpen(true); }} className="p-2 text-slate-300 hover:text-indigo-600"><Edit2 className="w-4 h-4" /></button>
                      <button onClick={() => handleDeleteAdmin(a.id, a.role)} className="p-2 text-slate-300 hover:text-red-600"><Trash2 className="w-4 h-4" /></button>
                    </td>
