                  <tr><th className="px-10 py-6 text-left">Asset Nomenclature</th><th className="px-5 py-6">Stock IN</th><th className="px-5 py-6">Distributed</th><th className="px-5 py-6">Returned</th><th className="px-5 py-6 text-amber-400">Faulty</th><th className="px-5 py-6 text-red-400">Damaged</th><th className="px-5 py-6 text-red-500">Lost</th><th className="px-10 py-6 bg-blue-600">Current Stock</th></tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {stockSummaryData.map(r => (
                    <tr key={r.name} className="hover:bg-slate-50 transition-colors">
                      <td className="px-10 py-5 text-left font-black text-slate-800 text-sm">{r.name}</td>
                      <td className="px-5 py-5 text-slate-500 font-black">{r.purchase}</td>
                      <td className="px-5 py-5 text-slate-500 font-black">{r.distributed}</td>
                      <td className="px-5 py-5 text-slate-500 font-black">{r.returned}</td>
                      <td className="px-5 py-5 text-amber-600 font-black bg-amber-50/30">{r.faulty}</td>
                      <td className="px-5 py-5 text-red-500 font-black bg-red-50/30">{r.damage}</td>
                      <td className="px-5 py-5 text-red-700 font-black bg-red-100/30">{r.lost}</td>
