              <button onClick={() => { setEditingTool(null); setIsCatalogModalOpen(true); }} className="bg-slate-900 text-white px-8 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl active:scale-95 transition-all">Register New Item</button>
            </div>
            <table className="w-full text-xs text-left min-w-[700px]">
              <thead className="bg-[#F8FAFC] text-slate-400 uppercase font-black tracking-widest border-b">
                <tr><th className="px-10 py-6">Official Name</th><th className="px-10 py-6">Brand / Model</th><th className="px-10 py-6">Unit Permissions</th><th className="px-10 py-6 text-right">Update</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {toolCatalog.map(t => (
                  <tr key={t.name} className="hover:bg-slate-50">
                    <td className="px-10 py-5 font-black text-slate-900 text-sm">{t.name}</td>
                    <td className="px-10 py-5 font-bold text-slate-400 italic text-xs">{t.brand}</td>
                    <td className="px-10 py-5"><span className="bg-blue-50 text-blue-700 px-4 py-1.5 rounded-xl text-[9px] font-black uppercase border border-blue-100">{t.department}</span></td>
                    <td className="px-10 py-5 text-right"><button onClick={() => { setEditingTool(t); setIsCatalogModalOpen(true); }} className="p-3 bg-slate-50 text-slate-400 hover:text-blue-600 hover:bg-white rounded-xl border border-transparent hover:border-slate-200 transition-all"><Edit2 className="w-4 h-4" /></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'admins' && (
          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden overflow-x-auto no-scrollbar">
            <div className="p-8 border-b flex justify-between items-center bg-indigo-50/30">
              <h2 className="text-sm font-black uppercase tracking-widest flex items-center gap-2 text-indigo-900"><ShieldCheck className="w-6 h-6" /> Access Control Matrix</h2>
              <button onClick={() => { setEditingAdmin(null); setIsAdminModalOpen(true); }} className="bg-indigo-600 text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-2xl hover:bg-indigo-700 active:scale-95 transition-all">Grant New Privileges</button>
            </div>
            <table className="w-full text-xs text-left min-w-[850px]">
              <thead className="bg-[#F8FAFC] text-slate-400 uppercase font-black tracking-widest">
                <tr><th className="px-10 py-6">Unique Access ID</th><th className="px-10 py-6">Admin Name</th><th className="px-10 py-6">Permission Role</th><th className="px-10 py-6">Managed Unit</th><th className="px-10 py-6 text-center">Protocol</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {sheetAdmins.map(a => (
                  <tr key={a.id} className="hover:bg-indigo-50/50 transition-colors">
                    <td className="px-10 py-5 font-mono font-black text-slate-500 text-sm">{a.id}</td>
                    <td className="px-10 py-5 font-black text-slate-900 text-base">{a.name}</td>
                    <td className="px-10 py-5"><span className={`px-3 py-1.5 rounded-xl text-[9px] font-black uppercase shadow-sm border ${a.role.includes('super') ? 'bg-indigo-900 text-white border-indigo-950' : 'bg-white text-amber-600 border-amber-200'}`}>{a.role}</span></td>
                    <td className="px-10 py-5 font-black text-slate-600 uppercase text-[11px]">{a.department}</td>
                    <td className="px-10 py-5 text-center space-x-3 whitespace-nowrap">
                      <button onClick={() => { setEditingAdmin(a); setIsAdminModalOpen(true); }} className="p-3 bg-white text-slate-400 hover:text-indigo-600 rounded-xl border border-slate-100 hover:border-indigo-200 shadow-sm transition-all"><Edit2 className="w-4 h-4" /></button>
                      <button onClick={() => handleDeleteAdmin(a.id, a.role)} className="p-3 bg-white text-slate-300 hover:text-red-600 rounded-xl border border-slate-100 hover:border-red-200 shadow-sm transition-all"><Trash2 className="w-4 h-4" /></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </main>

      {/* Mobile Sticky Bottom Navigation with Icons */}
      <footer className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 px-4 py-3 flex items-center justify-between z-40 shadow-[0_-10px_30px_rgba(0,0,0,0.05)] safe-bottom">
        {navigationTabs.map(tab => (
          <button key={tab.id} onClick={() => setActiveTab(tab.id as Tab)} className={`flex flex-col items-center gap-1.5 px-3 py-1 transition-all ${activeTab === tab.id ? 'text-blue-600' : 'text-slate-400'}`}>
            <tab.icon className={`w-5 h-5 ${activeTab === tab.id ? 'stroke-[2.5px]' : 'stroke-[1.5px]'}`} />
            <span className="text-[9px] font-black uppercase tracking-tight">{tab.label}</span>
          </button>
        ))}
      </footer>

      {/* Modals & AI Chat */}
      <ToolModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSave={async (trx, details) => { 
          setIsSyncing(true); 
          for(const t of trx) {
            const transactionWithAdminDept = {
              ...t,
              department: isSuperAdmin ? (details?.department || user?.department) : user?.department
            };
            await saveTransactionToSheet(transactionWithAdminDept, details);
          }
          await loadData(true); 
          setIsModalOpen(false); 
        }} 
        employees={visibleEmployees} 
        availableTools={availableTools} 
      />
      <EmployeeModal isOpen={isEmployeeModalOpen} onClose={() => setIsEmployeeModalOpen(false)} onSave={handleSaveEmployee} isAdmin={isAdmin} isSuperAdmin={isSuperAdmin} userDepartment={user?.department || ''} allDepartments={departments} initialData={editingEmployee} />
      <AdminModal isOpen={isAdminModalOpen} onClose={() => setIsAdminModalOpen(false)} onSave={async (data) => { setIsSyncing(true); await saveAdminToSheet(data); await loadData(true); setIsAdminModalOpen(false); }} initialData={editingAdmin} departments={departments} />
      <ToolCatalogModal isOpen={isCatalogModalOpen} onClose={() => setIsCatalogModalOpen(false)} onSave={async (data) => { setIsSyncing(true); data.oldName ? await updateToolInCatalog(data as any) : await saveToolToCatalog(data); await loadData(true); setIsCatalogModalOpen(false); }} departments={departments} isSyncing={isSyncing} initialData={editingTool} />
      <AIChat inventory={stockSummaryData as any} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useCallback, useRef } from 'react';
import { 
  LogOut, Search, Plus, FileSpreadsheet, Users, Package, RefreshCw, Download, 
  ShieldCheck, ChevronRight, ChevronLeft, Edit2, UserPlus, Trash2, Lock, CheckCircle, 
  Clock, Key, History, LayoutDashboard, Wrench, Tags, Menu, X, DownloadCloud, FileDown, 
  Filter, Calculator, Edit, AlertTriangle
} from 'lucide-react';
import { USERS, LOGO_URL } from './constants';
import { User, Transaction, ToolDefinition } from './types';
import ToolModal from './components/ToolModal';
import AdminModal from './components/AdminModal';
import EmployeeModal from './components/EmployeeModal';
import ToolCatalogModal from './components/ToolCatalogModal';
import Login from './components/Login';
import EmployeeDashboard from './components/EmployeeDashboard';
import AIChat from './components/AIChat';
import { 
  fetchSheetData, saveTransactionToSheet, saveAdminToSheet, deleteAdminFromSheet, 
  saveEmployeeToSheet, deleteEmployeeFromSheet, updateEmployeeStatusInSheet, 
  approveEmployeePasswordChange, saveToolToCatalog, updateToolInCatalog, SheetData 
} from './services/sheetService';
import { generateEmployeePDF } from './services/pdfService';

type Tab = 'employee' | 'directory' | 'daily' | 'stock' | 'admins' | 'catalog';

const CACHE_KEY = 'sarbs_inventory_cache_v5';
const USER_SESSION_KEY = 'sarbs_auth_session_v5';
const LOGS_PER_PAGE = 20;

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(() => {
    try {
      const saved = localStorage.getItem(USER_SESSION_KEY);
      return saved ? JSON.parse(saved) : null;
    } catch (e) { return null; }
  });

  const [allTransactions, setAllTransactions] = useState<Transaction[]>([]);
  const [fullEmployeeDirectory, setFullEmployeeDirectory] = useState<any[]>([]);
  const [availableTools, setAvailableTools] = useState<string[]>([]);
  const [toolCatalog, setToolCatalog] = useState<ToolDefinition[]>([]);
  const [sheetAdmins, setSheetAdmins] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSync, setLastSync] = useState<string>('');
  const [activeTab, setActiveTab] = useState<Tab>('employee');
  const [searchQuery, setSearchQuery] = useState('');
  const [stockSearchQuery, setStockSearchQuery] = useState('');
  const [logsSearchQuery, setLogsSearchQuery] = useState(''); // New search query for logs
  const [selectedEmployee, setSelectedEmployee] = useState<any>(null);
  const [showSearchResults, setShowSearchResults] = useState(false);
  const [lookupViewMode, setLookupViewMode] = useState<'summary' | 'history'>('summary');
  const searchRef = useRef<HTMLDivElement>(null);
  const [selectedDeptFilter, setSelectedDeptFilter] = useState<string>('');
  const [directoryDeptFilter, setDirectoryDeptFilter] = useState<string>('');
  const [directorySearchQuery, setDirectorySearchQuery] = useState<string>('');
  const [showBulkLogsOnly, setShowBulkLogsOnly] = useState(false);
  const [currentLogsPage, setCurrentLogsPage] = useState(1);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEmployeeModalOpen, setIsEmployeeModalOpen] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<any | null>(null);
  const [isAdminModalOpen, setIsAdminModalOpen] = useState(false);
  const [isCatalogModalOpen, setIsCatalogModalOpen] = useState(false);
  const [editingAdmin, setEditingAdmin] = useState<User | null>(null);
  const [editingTool, setEditingTool] = useState<ToolDefinition | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  const loadData = useCallback(async (isBackground = false) => {
    if (!isBackground && allTransactions.length === 0) setIsLoading(true);
    else setIsSyncing(true);
    try {
      const data = await fetchSheetData();
      setAllTransactions(data.transactions || []);
      setFullEmployeeDirectory(data.employees || []);
      setAvailableTools(data.tools || []);
      setToolCatalog(data.catalog || []);
      setSheetAdmins(data.admins || []);
      const timeStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      setLastSync(timeStr);
      localStorage.setItem(CACHE_KEY, JSON.stringify({ ...data, cachedAt: timeStr }));
    } catch (e) { console.error("Sync Failed", e); }
    finally { setTimeout(() => setIsLoading(false), 2000); setTimeout(() => setIsSyncing(false), 500); }
  }, [allTransactions.length]);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    const cached = localStorage.getItem(CACHE_KEY);
    if (cached) {
      const parsed = JSON.parse(cached);
      setAllTransactions(parsed.transactions || []);
      setFullEmployeeDirectory(parsed.employees || []);
      setToolCatalog(parsed.catalog || []);
      setSheetAdmins(parsed.admins || []);
      setIsLoading(false);
      loadData(true);
    } else { loadData(false); }
    return () => { window.removeEventListener('online', handleOnline); window.removeEventListener('offline', handleOffline); };
  }, [loadData]);

  const isSuperAdmin = useMemo(() => {
    if (!user) return false;
    const role = user.role.toLowerCase().replace(/[\s_]/g, '');
    const isGlobalUnit = user.department === 'All' || user.department === 'Global (All)';
    return role === 'superadmin' || role === 'super_admin' || isGlobalUnit;
  }, [user]);

  const isManagementAdmin = useMemo(() => {
    return isSuperAdmin;
  }, [isSuperAdmin]);

  const isAdmin = useMemo(() => user?.role === 'dept_admin' || isSuperAdmin, [user, isSuperAdmin]);

  const departments = useMemo(() => {
    const depts = new Set<string>();
    fullEmployeeDirectory.forEach(e => depts.add(e.department));
    toolCatalog.forEach(t => depts.add(t.department || 'All'));
    return Array.from(depts).filter(d => d && d !== 'All' && d !== 'Global (All)').sort();
  }, [fullEmployeeDirectory, toolCatalog]);

  const navigationTabs = useMemo(() => [
    { id: 'employee', label: 'LOOKUP', icon: Search },
    { id: 'directory', label: 'DIR', icon: Users },
    { id: 'catalog', label: 'CATALOG', icon: Wrench, adminOnly: true },
    { id: 'daily', label: 'LOGS', icon: FileSpreadsheet },
    { id: 'stock', label: 'STOCK', icon: Package },
    ...(isManagementAdmin ? [{ id: 'admins', label: 'ADMIN', icon: ShieldCheck }] : [])
  ].filter(tab => !tab.adminOnly || isSuperAdmin), [isSuperAdmin, isManagementAdmin]);

  const visibleEmployees = useMemo(() => 
    isSuperAdmin ? fullEmployeeDirectory : fullEmployeeDirectory.filter(e => e.department === user?.department),
  [isSuperAdmin, fullEmployeeDirectory, user]);

  const filteredDirectory = useMemo(() => {
    let list = visibleEmployees;
    if (isSuperAdmin && directoryDeptFilter) list = list.filter(e => e.department === directoryDeptFilter);
    if (directorySearchQuery.trim()) {
      const q = directorySearchQuery.toLowerCase();
      list = list.filter(e => String(e.id).toLowerCase().includes(q) || String(e.name).toLowerCase().includes(q));
    }
    return list;
  }, [visibleEmployees, isSuperAdmin, directoryDeptFilter, directorySearchQuery]);

  const visibleTransactions = useMemo(() => {
    let list = isSuperAdmin ? allTransactions : allTransactions.filter(t => t.department === user?.department);

    // Filter by Logs Search Query (Tool name, Employee name, or ID)
    if (logsSearchQuery.trim()) {
      const q = logsSearchQuery.toLowerCase().trim();
      list = list.filter(t => 
        t.toolName.toLowerCase().includes(q) || 
        (t.employeeName && t.employeeName.toLowerCase().includes(q)) ||
        (t.employeeId && String(t.employeeId).toLowerCase().includes(q))
      );
    }

    if (showBulkLogsOnly) list = list.filter(t => t.quantity >= 2);
    return list;
  }, [isSuperAdmin, allTransactions, user, showBulkLogsOnly, logsSearchQuery]);

  const paginatedLogs = useMemo(() => {
    const sorted = [...visibleTransactions].reverse();
    return sorted.slice((currentLogsPage - 1) * LOGS_PER_PAGE, currentLogsPage * LOGS_PER_PAGE);
  }, [visibleTransactions, currentLogsPage]);

  const totalLogsPages = useMemo(() => Math.ceil(visibleTransactions.length / LOGS_PER_PAGE), [visibleTransactions]);

  const stockSummaryData = useMemo(() => {
    const map = new Map<string, any>();
    let baseTrx = allTransactions;
    if (!isSuperAdmin) {
      baseTrx = allTransactions.filter(t => t.department === user?.department);
    } else if (selectedDeptFilter !== '') {
      baseTrx = allTransactions.filter(t => t.department === selectedDeptFilter);
    }

    const catalog = isSuperAdmin ? toolCatalog : toolCatalog.filter(t => t.department === user?.department || t.department === 'All');
    catalog.forEach(t => map.set(t.name, { name: t.name, purchase: 0, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0 }));

    baseTrx.forEach(t => {
      let row = map.get(t.toolName);
      if (!row) { row = { name: t.toolName, purchase: 0, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0 }; map.set(t.toolName, row); }
      const q = Number(t.quantity);
      if (t.entryType === 'Stock IN') row.purchase += q;
      else if (t.entryType === 'Distribute') row.distributed += q;
      else if (t.entryType === 'Return') row.returned += q;
      else if (t.entryType === 'Faulty Return') row.faulty += q;
      else if (t.entryType === 'Damage') row.damage += q;
      else if (t.entryType === 'Lost') row.lost += q;
    });

    let results = Array.from(map.values()).map(r => ({ ...r, stockNow: (r.purchase + r.returned) - (r.distributed + r.faulty + r.damage + r.lost) }));
    if (stockSearchQuery.trim()) results = results.filter(r => r.name.toLowerCase().includes(stockSearchQuery.toLowerCase()));
    return results.sort((a, b) => a.name.localeCompare(b.name));
  }, [allTransactions, toolCatalog, isSuperAdmin, user, stockSearchQuery, selectedDeptFilter]);

  const employeeToolsData = useMemo(() => {
    if (!selectedEmployee) return [];
    const map = new Map<string, any>();
    allTransactions.filter(t => t.employeeId === selectedEmployee.id).forEach(t => {
      let row = map.get(t.toolName);
      if (!row) { row = { name: t.toolName, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0, remarks: '' }; map.set(t.toolName, row); }
      const q = Number(t.quantity);
      if (t.entryType === 'Distribute') row.distributed += q;
      else if (t.entryType === 'Return') row.returned += q;
      else if (t.entryType === 'Faulty Return') row.faulty += q;
      else if (t.entryType === 'Damage') row.damage += q;
      else if (t.entryType === 'Lost') row.lost += q;
      if (t.remarks) row.remarks = t.remarks;
    });
    return Array.from(map.values()).sort((a, b) => a.name.localeCompare(b.name));
  }, [selectedEmployee, allTransactions]);

  const employeeHistory = useMemo(() => {
    if (!selectedEmployee) return [];
    return allTransactions.filter(t => t.employeeId === selectedEmployee.id).reverse();
  }, [selectedEmployee, allTransactions]);

  const handleExportStock = () => {
    const headers = ['Tool Name', 'Stock IN', 'Dist.', 'Ret.', 'Faulty', 'Damage', 'Lost', 'Current Stock'];
    const csvContent = [headers.join(','), ...stockSummaryData.map(r => [`"${r.name}"`, r.purchase, r.distributed, r.returned, r.faulty, r.damage, r.lost, r.stockNow].join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `SARBS_Stock_${new Date().getTime()}.csv`;
    link.click();
  };

  const handleSaveEmployee = async (data: any) => {
    setIsSyncing(true);
    if (await saveEmployeeToSheet(data)) {
      alert("Profile Committed.");
      setIsEmployeeModalOpen(false);
      setEditingEmployee(null);
      await loadData(true);
    } else { alert("Failed to save."); setIsSyncing(false); }
  };

  const handleDeleteEmployee = async (id: string) => {
    if (!confirm("Permanently archive this personnel to Discard list?")) return;
    setIsSyncing(true);
    if (await deleteEmployeeFromSheet(id)) {
      alert("Personnel Archived.");
      await loadData(true);
    } else { alert("Error."); setIsSyncing(false); }
  };

  const handleDeleteAdmin = async (id: string, role: string) => {
    if (role.toLowerCase().includes('super')) return alert("Super Admin accounts are protected.");
    if (!confirm(`Delete admin access for ID: ${id}?`)) return;
    setIsSyncing(true);
    if (await deleteAdminFromSheet(id)) {
      alert("Access Revoked.");
      await loadData(true);
    } else { alert("Error."); setIsSyncing(false); }
  };

  if (isLoading) return (
    <div className="min-h-screen bg-white flex flex-col items-center justify-center p-10 text-center animate-fade-in">
      <img src={LOGO_URL} alt="Logo" className="w-56 h-56 object-contain" />
      <h1 className="text-slate-900 font-black text-2xl uppercase mt-8">SARBS HUB</h1>
      <p className="text-slate-400 text-xs font-bold uppercase tracking-[0.4em] animate-pulse mt-4">Connecting to Cloud Assets...</p>
    </div>
  );

  if (!user) return <Login onLogin={(u) => {
    const admin = sheetAdmins.find(a => a.id === u.id && a.password === u.password);
    if (admin) { setUser(admin); localStorage.setItem(USER_SESSION_KEY, JSON.stringify(admin)); return; }
    const emp = fullEmployeeDirectory.find(e => e.id === u.id && (e.password || '12345') === u.password);
    if (emp) { const uObj = { ...emp, role: 'employee' }; setUser(uObj); localStorage.setItem(USER_SESSION_KEY, JSON.stringify(uObj)); return; }
    alert("Invalid Credentials");
  }} isSyncing={isSyncing} lastSync={lastSync} onRefresh={() => loadData(true)} isOnline={isOnline} installPrompt={null} onInstall={() => {}} isStandalone={false} />;

  if (user.role === 'employee') return <EmployeeDashboard user={user} transactions={allTransactions} onLogout={() => { setUser(null); localStorage.removeItem(USER_SESSION_KEY); }} isSyncing={isSyncing} />;

  return (
    <div className="min-h-screen bg-[#F0F4F8] font-sans pb-24 md:pb-6">
      {/* Desktop Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm hidden md:flex items-center justify-between px-8 h-20">
        <div className="flex items-center gap-3">
          <img src={LOGO_URL} alt="Logo" className="w-12 h-12 object-contain" />
          <div>
            <h1 className="text-sm font-black text-slate-900 uppercase">SARBS Inventory</h1>
            <p className="text-[9px] text-blue-600 font-bold uppercase tracking-widest">{user.department} Administration</p>
          </div>
        </div>
        <nav className="flex items-center gap-2">
          {navigationTabs.map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as Tab)} className={`px-5 py-2.5 rounded-xl text-[11px] font-black uppercase transition-all flex items-center gap-2 ${activeTab === tab.id ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100'}`}>
              <tab.icon className="w-4 h-4" /> {tab.label}
            </button>
          ))}
        </nav>
        <div className="flex items-center gap-4">
          <button onClick={() => loadData(true)} className={`p-2 rounded-full hover:bg-slate-100 ${isSyncing ? 'animate-spin text-blue-500' : 'text-slate-400'}`}><RefreshCw className="w-5 h-5" /></button>
          <button onClick={() => { setUser(null); localStorage.removeItem(USER_SESSION_KEY); }} className="p-2 rounded-full hover:bg-red-50 text-slate-400 hover:text-red-600 transition-colors"><LogOut className="w-6 h-6" /></button>
        </div>
      </header>

      {/* Mobile Sticky Top Header */}
      <div className="md:hidden bg-white border-b border-slate-200 h-16 sticky top-0 z-30 flex items-center justify-between px-4">
        <div className="flex items-center gap-2">
           <img src={LOGO_URL} alt="Logo" className="w-8 h-8 object-contain" />
           <span className="text-[10px] font-black uppercase text-slate-900">SARBS Inventory</span>
        </div>
        <button onClick={() => loadData(true)} className={`p-2 ${isSyncing ? 'animate-spin text-blue-500' : 'text-slate-400'}`}><RefreshCw className="w-5 h-5" /></button>
      </div>

      <main className="max-w-7xl mx-auto p-4 md:p-8 space-y-6">
        {activeTab === 'employee' && (
          <div className="space-y-6">
            <div className="bg-white p-5 md:p-8 rounded-3xl shadow-sm border border-slate-100 flex flex-col sm:flex-row gap-4 justify-between items-center" ref={searchRef}>
              <div className="w-full max-w-md relative">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Target Lookup</label>
                <div className="relative group">
                  <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                  <input type="text" className="w-full pl-11 pr-4 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl outline-none text-sm font-bold focus:border-blue-500 transition-all shadow-inner" placeholder="Personnel ID or Name..." value={searchQuery} onChange={(e) => { setSearchQuery(e.target.value); setShowSearchResults(true); }} />
                </div>
                {showSearchResults && searchQuery && (
                  <div className="absolute z-50 left-0 right-0 mt-2 bg-white rounded-2xl shadow-2xl border border-slate-200 overflow-hidden animate-in fade-in duration-200">
                    {visibleEmployees.filter(e => String(e.id).includes(searchQuery) || e.name.toLowerCase().includes(searchQuery.toLowerCase())).slice(0, 5).map(e => (
                      <button key={e.id} onClick={() => { setSelectedEmployee(e); setShowSearchResults(false); setSearchQuery(`${e.id} - ${e.name}`); }} className="w-full px-5 py-4 text-left border-b last:border-0 hover:bg-blue-50 flex items-center justify-between group">
                        <div><p className="text-sm font-black text-slate-900 group-hover:text-blue-700">{e.id} - {e.name}</p><p className="text-[9px] text-slate-400 uppercase font-bold">{e.department}</p></div>
                        <ChevronRight className="w-5 h-5 text-slate-200 group-hover:text-blue-500" />
                      </button>
                    ))}
                  </div>
                )}
              </div>
              {isAdmin && <button onClick={() => setIsModalOpen(true)} className="w-full sm:w-auto bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl flex items-center justify-center gap-3 transition-transform active:scale-95"><Plus className="w-5 h-5" /> Commit Entry</button>}
            </div>

            {selectedEmployee ? (
              <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
                <div className="grid grid-cols-2 md:grid-cols-4 gap-px bg-slate-100 border-b">
                  <div className="bg-white p-6 text-center"><p className="text-[9px] font-black text-slate-400 uppercase mb-1">Name</p><p className="font-black text-slate-900">{selectedEmployee.name}</p></div>
                  <div className="bg-white p-6 text-center"><p className="text-[9px] font-black text-slate-400 uppercase mb-1">Unit</p><p className="font-black text-blue-600 uppercase text-[11px]">{selectedEmployee.department}</p></div>
                  <div className="bg-white p-6 text-center"><p className="text-[9px] font-black text-slate-400 uppercase mb-1">Rank</p><p className="font-bold text-slate-500">{selectedEmployee.designation}</p></div>
                  <div className="bg-white p-6 flex items-center justify-center gap-3">
                    <button onClick={() => setLookupViewMode(prev => prev === 'summary' ? 'history' : 'summary')} className={`p-3 rounded-xl transition-all border ${lookupViewMode === 'history' ? 'bg-slate-900 text-white border-slate-900' : 'bg-slate-50 text-slate-400 border-slate-100'}`} title="History Toggle"><History className="w-5 h-5" /></button>
                    <button onClick={() => generateEmployeePDF(selectedEmployee, employeeToolsData)} className="bg-slate-100 hover:bg-blue-600 hover:text-white text-slate-900 px-5 py-3 rounded-xl text-[10px] font-black uppercase transition-all shadow-sm">PDF Report</button>
                  </div>
                </div>

                {lookupViewMode === 'summary' ? (
                  <div className="overflow-x-auto no-scrollbar">
                    <table className="w-full text-xs text-left min-w-[900px]">
                      <thead className="bg-[#F8FAFC] border-b text-slate-500 uppercase font-black tracking-widest">
                        <tr><th className="px-8 py-5">Tool Name</th><th className="px-5 py-5 text-center">Dist.</th><th className="px-5 py-5 text-center">Ret.</th><th className="px-5 py-5 text-center text-amber-600">Faulty</th><th className="px-5 py-5 text-center text-red-500">Dmg</th><th className="px-5 py-5 text-center text-red-700">Lost</th><th className="px-6 py-5 text-center bg-green-50 text-green-900">Balance</th><th className="px-8 py-5">Recent Remark</th></tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {employeeToolsData.map(r => (
                          <tr key={r.name} className="hover:bg-slate-50">
                            <td className="px-8 py-4 font-black text-slate-800 text-sm">{r.name}</td>
                            <td className="px-5 py-4 text-center font-bold">{r.distributed}</td>
                            <td className="px-5 py-4 text-center font-bold">{r.returned}</td>
                            <td className="px-5 py-4 text-center text-amber-600 font-bold">{r.faulty}</td>
                            <td className="px-5 py-4 text-center text-red-500 font-bold">{r.damage}</td>
                            <td className="px-5 py-4 text-center text-red-700 font-bold">{r.lost}</td>
                            <td className="px-6 py-4 text-center font-black bg-green-50/50 text-green-700 text-base">{r.distributed - r.returned - r.faulty - r.damage - r.lost}</td>
                            <td className="px-8 py-4 text-slate-400 italic text-[10px] truncate max-w-[200px]">{r.remarks || '-'}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                ) : (
                  <div className="overflow-x-auto no-scrollbar">
                    <table className="w-full text-[10px] text-left min-w-[800px]">
                      <thead className="bg-[#F8FAFC] border-b text-slate-500 uppercase font-black">
                        <tr><th className="px-8 py-5">Date</th><th className="px-8 py-5">Asset Description</th><th className="px-5 py-5 text-center">Entry Type</th><th className="px-5 py-5 text-center">Qty</th><th className="px-8 py-5">Administrative Remarks</th></tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {employeeHistory.map(h => (
                          <tr key={h.id} className="hover:bg-slate-50">
                            <td className="px-8 py-4 font-mono text-slate-400">{h.date}</td>
                            <td className="px-8 py-4 font-black text-slate-800">{h.toolName}</td>
                            <td className="px-5 py-4 text-center"><span className={`px-2.5 py-1 rounded-md text-[9px] font-black uppercase ${h.entryType === 'Distribute' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>{h.entryType}</span></td>
                            <td className="px-5 py-4 text-center font-black text-slate-900">{h.quantity}</td>
                            <td className="px-8 py-4 text-slate-400 italic">{h.remarks}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            ) : (
              <div className="py-24 text-center bg-white rounded-[3rem] border-2 border-dashed border-slate-200 text-slate-300 font-black uppercase tracking-[0.3em] text-xs">
                Enter ID or Name to Access Profile Data
              </div>
            )}
          </div>
        )}

        {activeTab === 'directory' && (
          <div className="space-y-4">
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col md:flex-row gap-4 justify-between items-end">
              <div className="w-full max-sm"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Unit Directory Search</label><input type="text" className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl outline-none text-sm font-bold shadow-inner focus:border-blue-500" placeholder="Search Names or IDs..." value={directorySearchQuery} onChange={e => setDirectorySearchQuery(e.target.value)} /></div>
              {isAdmin && <button onClick={() => { setEditingEmployee(null); setIsEmployeeModalOpen(true); }} className="w-full sm:w-auto bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl flex items-center justify-center gap-3"><UserPlus className="w-5 h-5" /> New Personnel</button>}
            </div>
            <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden overflow-x-auto no-scrollbar">
              <table className="w-full text-xs text-left min-w-[1000px]">
                <thead className="bg-[#F8FAFC] border-b text-slate-500 uppercase font-black tracking-widest">
                  <tr><th className="px-8 py-6">ID / Security Key</th><th className="px-8 py-6">Full Legal Name</th><th className="px-8 py-6">Designation</th><th className="px-8 py-6">Unit</th><th className="px-8 py-6 text-center">Hub Status</th><th className="px-8 py-6 text-right">Actions</th></tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {filteredDirectory.map(e => (
                    <tr key={e.id} className="hover:bg-slate-50 group">
                      <td className="px-8 py-5">
                         <div className="font-mono font-black text-slate-400 text-[11px] mb-1">ID: {e.id}</div>
                         <div className="flex items-center gap-1.5"><Key className="w-3 h-3 text-blue-300" /><span className="bg-blue-50 px-2 py-0.5 rounded text-[10px] font-black text-blue-700 uppercase border border-blue-100">{e.password || '12345'}</span></div>
                      </td>
                      <td className="px-8 py-5 font-black text-slate-900 text-base">{e.name}</td>
                      <td className="px-8 py-5 font-bold text-slate-500">{e.designation}</td>
                      <td className="px-8 py-5 text-blue-600 font-black uppercase text-[10px]">{e.department}</td>
                      <td className="px-8 py-5 text-center"><span className={`px-3 py-1.5 rounded-xl text-[9px] font-black uppercase border ${e.typeOfEmployee === 'Running' ? 'bg-green-50 text-green-600 border-green-200' : 'bg-red-50 text-red-600 border-red-200'}`}>{e.typeOfEmployee}</span></td>
                      <td className="px-8 py-5 text-right space-x-2 whitespace-nowrap">
                        <button onClick={() => { setEditingEmployee(e); setIsEmployeeModalOpen(true); }} className="p-2.5 bg-slate-50 text-slate-400 hover:text-blue-600 hover:bg-white rounded-xl border border-transparent hover:border-slate-200 transition-all shadow-sm"><Edit className="w-4 h-4" /></button>
                        {isSuperAdmin && <button onClick={() => handleDeleteEmployee(e.id)} className="p-2.5 bg-slate-50 text-slate-400 hover:text-red-600 hover:bg-white rounded-xl border border-transparent hover:border-red-200 transition-all shadow-sm"><Trash2 className="w-4 h-4" /></button>}
                        <button onClick={() => { setSelectedEmployee(e); setActiveTab('employee'); setSearchQuery(`${e.id} - ${e.name}`); }} className="text-[10px] font-black text-blue-600 hover:underline uppercase px-2">View History</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'daily' && (
          <div className="space-y-4">
            <div className="flex flex-col lg:flex-row justify-between items-end bg-white p-6 rounded-3xl shadow-sm border border-slate-100 gap-6">
              <div className="w-full flex-1 space-y-4">
                <div className="flex items-center justify-between">
                  <h2 className="text-sm font-black uppercase tracking-widest flex items-center gap-2"><FileSpreadsheet className="w-4 h-4 text-blue-500" /> Operational Activity Log</h2>
                  <button onClick={() => setShowBulkLogsOnly(!showBulkLogsOnly)} className={`text-[9px] font-black uppercase flex items-center gap-1.5 ${showBulkLogsOnly ? 'text-amber-600' : 'text-slate-400'}`}><Filter className="w-3 h-3" /> Bulk Filter (Qty 2+): {showBulkLogsOnly ? 'ACTIVE' : 'OFF'}</button>
                </div>

                {/* Search Bar for Logs */}
                <div className="relative">
                  <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                  <input 
                    type="text" 
                    className="w-full pl-12 pr-4 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold shadow-inner focus:border-blue-500 outline-none transition-all" 
                    placeholder="Search logs by Tool Name, Employee Name, or ID..." 
                    value={logsSearchQuery} 
                    onChange={e => {
                      setLogsSearchQuery(e.target.value);
                      setCurrentLogsPage(1); // Reset to first page on search
                    }} 
                  />
                  {logsSearchQuery && (
                    <button 
                      onClick={() => {setLogsSearchQuery(''); setCurrentLogsPage(1);}}
                      className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                    >
                      <X className="w-4 h-4" />
                    </button>
                  )}
                </div>
              </div>

              <button onClick={() => setIsModalOpen(true)} className="w-full lg:w-auto bg-slate-900 text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-2xl flex items-center justify-center gap-3 active:scale-95 transition-all"><Plus className="w-5 h-5" /> New Log Entry</button>
            </div>

            <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden overflow-x-auto no-scrollbar">
              <table className="w-full text-[11px] text-left min-w-[900px]">
                <thead className="bg-[#F8FAFC] border-b text-slate-500 uppercase font-black tracking-widest">
                  <tr><th className="px-8 py-5">Timestamp</th><th className="px-8 py-5">Personnel Name</th><th className="px-8 py-5">Asset Description</th><th className="px-5 py-5 text-center">Entry Type</th><th className="px-5 py-5 text-center">Qty</th><th className="px-8 py-5">Admin Remarks</th></tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {paginatedLogs.length > 0 ? paginatedLogs.map(t => (
                    <tr key={t.id} className="hover:bg-slate-50 transition-colors">
                      <td className="px-8 py-4 font-mono text-[10px] text-slate-400 whitespace-nowrap">{t.date}</td>
                      <td className="px-8 py-4 font-black text-slate-900">
                        <div className="flex flex-col">
                          <span>{t.employeeName || 'GLOBAL_SYSTEM'}</span>
                          <span className="text-[9px] text-slate-400 font-bold uppercase">ID: {t.employeeId || 'N/A'}</span>
                        </div>
                      </td>
                      <td className="px-8 py-4 font-bold text-slate-600">{t.toolName}</td>
                      <td className="px-5 py-4 text-center"><span className={`px-2.5 py-1 rounded-md text-[9px] font-black uppercase border ${t.entryType === 'Distribute' ? 'bg-green-500 text-white border-green-600' : t.entryType === 'Return' ? 'bg-blue-600 text-white border-blue-700' : 'bg-red-600 text-white border-red-700'}`}>{t.entryType}</span></td>
                      <td className={`px-5 py-4 text-center font-black ${t.quantity >= 2 ? 'text-amber-600 text-sm' : 'text-slate-900'}`}>{t.quantity}</td>
                      <td className="px-8 py-4 text-slate-400 italic text-[10px] truncate max-w-[200px]">{t.remarks}</td>
                    </tr>
                  )) : (
                    <tr>
                      <td colSpan={6} className="py-20 text-center text-slate-400 font-black uppercase italic tracking-widest">
                        {logsSearchQuery ? `No logs found matching "${logsSearchQuery}"` : 'No operational activity recorded.'}
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>

              {/* Numbered Pagination (1, 2, 3...) */}
              {totalLogsPages > 1 && (
                <div className="p-8 border-t border-slate-50 bg-slate-50/30 flex items-center justify-center gap-2">
                  <button onClick={() => setCurrentLogsPage(p => Math.max(1, p - 1))} disabled={currentLogsPage === 1} className="p-3 rounded-xl hover:bg-white text-slate-400 disabled:opacity-30 transition-all border border-transparent hover:border-slate-200"><ChevronLeft className="w-5 h-5" /></button>
                  {Array.from({ length: Math.min(5, totalLogsPages) }, (_, i) => {
                     const pageNum = i + 1;
                     return (
                       <button key={pageNum} onClick={() => setCurrentLogsPage(pageNum)} className={`w-12 h-12 rounded-2xl text-[11px] font-black transition-all shadow-sm ${currentLogsPage === pageNum ? 'bg-slate-900 text-white scale-110' : 'bg-white text-slate-400 hover:bg-slate-200'}`}>{pageNum}</button>
                     );
                  })}
                  <button onClick={() => setCurrentLogsPage(p => Math.min(totalLogsPages, p + 1))} disabled={currentLogsPage === totalLogsPages} className="p-3 rounded-xl hover:bg-white text-slate-400 disabled:opacity-30 transition-all border border-transparent hover:border-slate-200"><ChevronRight className="w-5 h-5" /></button>
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'stock' && (
          <div className="space-y-4">
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col lg:flex-row justify-between gap-6 items-end">
              <div className="flex flex-col sm:flex-row gap-4 w-full max-w-4xl">
                <div className="flex-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Inventory Ledger Search</label>
                  <div className="relative">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                    <input type="text" className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold shadow-inner focus:border-blue-500" placeholder="Filter by Tool Name..." value={stockSearchQuery} onChange={e => setStockSearchQuery(e.target.value)} />
                  </div>
                </div>
                {isSuperAdmin && (
                  <div className="w-full sm:w-80">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Global Unit Reconciliation</label>
                    <select className="w-full px-5 py-4 bg-white border border-slate-200 rounded-2xl text-xs font-black uppercase cursor-pointer shadow-sm outline-none focus:border-blue-500" value={selectedDeptFilter} onChange={e => setSelectedDeptFilter(e.target.value)}>
                      <option value="">ALL UNITS CONSOLIDATED</option>
                      {departments.map(d => <option key={d} value={d}>{d}</option>)}
                    </select>
                  </div>
                )}
              </div>
              <button onClick={handleExportStock} className="w-full lg:w-auto bg-green-600 text-white px-10 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-3 shadow-xl shadow-green-200 hover:bg-green-700 active:scale-95 transition-all"><FileDown className="w-5 h-5" /> Export Stock CSV</button>
            </div>
            <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden overflow-x-auto no-scrollbar">
              <table className="w-full text-[11px] text-center min-w-[950px]">
                <thead className="bg-slate-900 text-white uppercase font-black tracking-widest">
                  <tr><th className="px-10 py-6 text-left">Asset Nomenclature</th><th className="px-5 py-6">Stock IN</th><th className="px-5 py-6">Distributed</th><th className="px-5 py-6">Returned</th><th className="px-5 py-6 text-amber-400">Faulty</th><th className="px-5 py-6 text-red-400">Damaged</th><th className="px-5 py-6 text-red-500">Lost</th><th className="px-10 py-6 bg-blue-600">Current Stock</th></tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {stockSummaryData.map(r => (
                    <tr key={r.name} className="hover:bg-slate-50 transition-colors">
                      <td className="px-10 py-5 text-left font-black text-slate-800 text-sm">{r.name}</td>
                      <td className="px-5 py-5 text-slate-500 font-black">{r.purchase}</td>
                      <td className="px-5 py-5 text-slate-500 font-black">{r.distributed}</td>
                      <td className="px-5 py-5 text-slate-500 font-black">{r.returned}</td>
                      <td className="px-5 py-5 text-amber-600 font-black bg-amber-50/30">{r.faulty}</td>
                      <td className="px-5 py-5 text-red-500 font-black bg-red-50/30">{r.damage}</td>
                      <td className="px-5 py-5 text-red-700 font-black bg-red-100/30">{r.lost}</td>
                      <td className="px-10 py-5 bg-blue-50/50 text-lg font-black text-blue-900">{r.stockNow}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'catalog' && (
          <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden overflow-x-auto no-scrollbar">
            <div className="p-8 border-b flex justify-between items-center bg-slate-50/50">
              <h2 className="text-sm font-black uppercase tracking-widest flex items-center gap-2"><Wrench className="w-5 h-5 text-blue-500" /> Master Asset Catalog</h2>
              <button onClick={() => { setEditingTool(null); setIsCatalogModalOpen(true); }} className="bg-slate-900 text-white px-8 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl active:scale-95 transition-all">Register New Item</button>
            </div>
            <table className="w-full text-xs text-left min-w-[700px]">
              <thead className="bg-[#F8FAFC] text-slate-400 uppercase font-black tracking-widest border-b">
                <tr><th className="px-10 py-6">Official Name</th><th className="px-10 py-6">Brand / Model</th><th className="px-10 py-6">Unit Permissions</th><th className="px-10 py-6 text-right">Update</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {toolCatalog.map(t => (
                  <tr key={t.name} className="hover:bg-slate-50">
                    <td className="px-10 py-5 font-black text-slate-900 text-sm">{t.name}</td>
                    <td className="px-10 py-5 font-bold text-slate-400 italic text-xs">{t.brand}</td>
                    <td className="px-10 py-5"><span className="bg-blue-50 text-blue-700 px-4 py-1.5 rounded-xl text-[9px] font-black uppercase border border-blue-100">{t.department}</span></td>
                    <td className="px-10 py-5 text-right"><button onClick={() => { setEditingTool(t); setIsCatalogModalOpen(true); }} className="p-3 bg-slate-50 text-slate-400 hover:text-blue-600 hover:bg-white rounded-xl border border-transparent hover:border-slate-200 transition-all"><Edit2 className="w-4 h-4" /></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'admins' && (
          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden overflow-x-auto no-scrollbar">
            <div className="p-8 border-b flex justify-between items-center bg-indigo-50/30">
              <h2 className="text-sm font-black uppercase tracking-widest flex items-center gap-2 text-indigo-900"><ShieldCheck className="w-6 h-6" /> Access Control Matrix</h2>
              <button onClick={() => { setEditingAdmin(null); setIsAdminModalOpen(true); }} className="bg-indigo-600 text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-2xl hover:bg-indigo-700 active:scale-95 transition-all">Grant New Privileges</button>
            </div>
            <table className="w-full text-xs text-left min-w-[850px]">
              <thead className="bg-[#F8FAFC] text-slate-400 uppercase font-black tracking-widest">
                <tr><th className="px-10 py-6">Unique Access ID</th><th className="px-10 py-6">Admin Name</th><th className="px-10 py-6">Permission Role</th><th className="px-10 py-6">Managed Unit</th><th className="px-10 py-6 text-center">Protocol</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {sheetAdmins.map(a => (
                  <tr key={a.id} className="hover:bg-indigo-50/50 transition-colors">
                    <td className="px-10 py-5 font-mono font-black text-slate-500 text-sm">{a.id}</td>
                    <td className="px-10 py-5 font-black text-slate-900 text-base">{a.name}</td>
                    <td className="px-10 py-5"><span className={`px-3 py-1.5 rounded-xl text-[9px] font-black uppercase shadow-sm border ${a.role.includes('super') ? 'bg-indigo-900 text-white border-indigo-950' : 'bg-white text-amber-600 border-amber-200'}`}>{a.role}</span></td>
                    <td className="px-10 py-5 font-black text-slate-600 uppercase text-[11px]">{a.department}</td>
                    <td className="px-10 py-5 text-center space-x-3 whitespace-nowrap">
                      <button onClick={() => { setEditingAdmin(a); setIsAdminModalOpen(true); }} className="p-3 bg-white text-slate-400 hover:text-indigo-600 rounded-xl border border-slate-100 hover:border-indigo-200 shadow-sm transition-all"><Edit2 className="w-4 h-4" /></button>
                      <button onClick={() => handleDeleteAdmin(a.id, a.role)} className="p-3 bg-white text-slate-300 hover:text-red-600 rounded-xl border border-slate-100 hover:border-red-200 shadow-sm transition-all"><Trash2 className="w-4 h-4" /></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </main>

      {/* Mobile Sticky Bottom Navigation with Icons */}
      <footer className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 px-4 py-3 flex items-center justify-between z-40 shadow-[0_-10px_30px_rgba(0,0,0,0.05)] safe-bottom">
        {navigationTabs.map(tab => (
          <button key={tab.id} onClick={() => setActiveTab(tab.id as Tab)} className={`flex flex-col items-center gap-1.5 px-3 py-1 transition-all ${activeTab === tab.id ? 'text-blue-600' : 'text-slate-400'}`}>
            <tab.icon className={`w-5 h-5 ${activeTab === tab.id ? 'stroke-[2.5px]' : 'stroke-[1.5px]'}`} />
            <span className="text-[9px] font-black uppercase tracking-tight">{tab.label}</span>
          </button>
        ))}
      </footer>

      {/* Modals & AI Chat */}
      <ToolModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSave={async (trx, details) => { 
          setIsSyncing(true); 
          for(const t of trx) {
            const transactionWithAdminDept = {
              ...t,
              department: isSuperAdmin ? (details?.department || user?.department) : user?.department
            };
            await saveTransactionToSheet(transactionWithAdminDept, details);
          }
          await loadData(true); 
          setIsModalOpen(false); 
        }} 
        employees={visibleEmployees} 
        availableTools={availableTools} 
      />
      <EmployeeModal isOpen={isEmployeeModalOpen} onClose={() => setIsEmployeeModalOpen(false)} onSave={handleSaveEmployee} isAdmin={isAdmin} isSuperAdmin={isSuperAdmin} userDepartment={user?.department || ''} allDepartments={departments} initialData={editingEmployee} />
      <AdminModal isOpen={isAdminModalOpen} onClose={() => setIsAdminModalOpen(false)} onSave={async (data) => { setIsSyncing(true); await saveAdminToSheet(data); await loadData(true); setIsAdminModalOpen(false); }} initialData={editingAdmin} departments={departments} />
      <ToolCatalogModal isOpen={isCatalogModalOpen} onClose={() => setIsCatalogModalOpen(false)} onSave={async (data) => { setIsSyncing(true); data.oldName ? await updateToolInCatalog(data as any) : await saveToolToCatalog(data); await loadData(true); setIsCatalogModalOpen(false); }} departments={departments} isSyncing={isSyncing} initialData={editingTool} />
      <AIChat inventory={stockSummaryData as any} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useCallback, useRef } from 'react';
import { 
  LogOut, Search, Plus, FileSpreadsheet, Users, Package, RefreshCw, Download, 
  ShieldCheck, ChevronRight, ChevronLeft, Edit2, UserPlus, Trash2, Lock, CheckCircle, 
  Clock, Key, History, LayoutDashboard, Wrench, Tags, Menu, X, DownloadCloud, FileDown, 
  Filter, Calculator, Edit, AlertTriangle
} from 'lucide-react';
import { USERS, LOGO_URL } from './constants';
import { User, Transaction, ToolDefinition } from './types';
import ToolModal from './components/ToolModal';
import AdminModal from './components/AdminModal';
import EmployeeModal from './components/EmployeeModal';
import ToolCatalogModal from './components/ToolCatalogModal';
import Login from './components/Login';
import EmployeeDashboard from './components/EmployeeDashboard';
import AIChat from './components/AIChat';
import { 
  fetchSheetData, saveTransactionToSheet, saveAdminToSheet, deleteAdminFromSheet, 
  saveEmployeeToSheet, deleteEmployeeFromSheet, updateEmployeeStatusInSheet, 
  approveEmployeePasswordChange, saveToolToCatalog, updateToolInCatalog, SheetData 
} from './services/sheetService';
import { generateEmployeePDF } from './services/pdfService';

type Tab = 'employee' | 'directory' | 'daily' | 'stock' | 'admins' | 'catalog';

const CACHE_KEY = 'sarbs_inventory_cache_v5';
const USER_SESSION_KEY = 'sarbs_auth_session_v5';
const LOGS_PER_PAGE = 20;

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(() => {
    try {
      const saved = localStorage.getItem(USER_SESSION_KEY);
      return saved ? JSON.parse(saved) : null;
    } catch (e) { return null; }
  });

  const [allTransactions, setAllTransactions] = useState<Transaction[]>([]);
  const [fullEmployeeDirectory, setFullEmployeeDirectory] = useState<any[]>([]);
  const [availableTools, setAvailableTools] = useState<string[]>([]);
  const [toolCatalog, setToolCatalog] = useState<ToolDefinition[]>([]);
  const [sheetAdmins, setSheetAdmins] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSync, setLastSync] = useState<string>('');
  const [activeTab, setActiveTab] = useState<Tab>('employee');
  const [searchQuery, setSearchQuery] = useState('');
  const [stockSearchQuery, setStockSearchQuery] = useState('');
  const [logsSearchQuery, setLogsSearchQuery] = useState(''); // New search query for logs
  const [selectedEmployee, setSelectedEmployee] = useState<any>(null);
  const [showSearchResults, setShowSearchResults] = useState(false);
  const [lookupViewMode, setLookupViewMode] = useState<'summary' | 'history'>('summary');
  const searchRef = useRef<HTMLDivElement>(null);
  const [selectedDeptFilter, setSelectedDeptFilter] = useState<string>('');
  const [directoryDeptFilter, setDirectoryDeptFilter] = useState<string>('');
  const [directorySearchQuery, setDirectorySearchQuery] = useState<string>('');
  const [showBulkLogsOnly, setShowBulkLogsOnly] = useState(false);
  const [currentLogsPage, setCurrentLogsPage] = useState(1);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEmployeeModalOpen, setIsEmployeeModalOpen] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<any | null>(null);
  const [isAdminModalOpen, setIsAdminModalOpen] = useState(false);
  const [isCatalogModalOpen, setIsCatalogModalOpen] = useState(false);
  const [editingAdmin, setEditingAdmin] = useState<User | null>(null);
  const [editingTool, setEditingTool] = useState<ToolDefinition | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  const loadData = useCallback(async (isBackground = false) => {
    if (!isBackground && allTransactions.length === 0) setIsLoading(true);
    else setIsSyncing(true);
    try {
      const data = await fetchSheetData();
      setAllTransactions(data.transactions || []);
      setFullEmployeeDirectory(data.employees || []);
      setAvailableTools(data.tools || []);
      setToolCatalog(data.catalog || []);
      setSheetAdmins(data.admins || []);
      const timeStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      setLastSync(timeStr);
      localStorage.setItem(CACHE_KEY, JSON.stringify({ ...data, cachedAt: timeStr }));
    } catch (e) { console.error("Sync Failed", e); }
    finally { setTimeout(() => setIsLoading(false), 2000); setTimeout(() => setIsSyncing(false), 500); }
  }, [allTransactions.length]);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    const cached = localStorage.getItem(CACHE_KEY);
    if (cached) {
      const parsed = JSON.parse(cached);
      setAllTransactions(parsed.transactions || []);
      setFullEmployeeDirectory(parsed.employees || []);
      setToolCatalog(parsed.catalog || []);
      setSheetAdmins(parsed.admins || []);
      setIsLoading(false);
      loadData(true);
    } else { loadData(false); }
    return () => { window.removeEventListener('online', handleOnline); window.removeEventListener('offline', handleOffline); };
  }, [loadData]);

  const isSuperAdmin = useMemo(() => {
    if (!user) return false;
    const role = user.role.toLowerCase().replace(/[\s_]/g, '');
    const isGlobalUnit = user.department === 'All' || user.department === 'Global (All)';
    return role === 'superadmin' || role === 'super_admin' || isGlobalUnit;
  }, [user]);

  const isManagementAdmin = useMemo(() => {
    return isSuperAdmin;
  }, [isSuperAdmin]);

  const isAdmin = useMemo(() => user?.role === 'dept_admin' || isSuperAdmin, [user, isSuperAdmin]);

  const departments = useMemo(() => {
    const depts = new Set<string>();
    fullEmployeeDirectory.forEach(e => depts.add(e.department));
    toolCatalog.forEach(t => depts.add(t.department || 'All'));
    return Array.from(depts).filter(d => d && d !== 'All' && d !== 'Global (All)').sort();
  }, [fullEmployeeDirectory, toolCatalog]);

  const navigationTabs = useMemo(() => [
    { id: 'employee', label: 'LOOKUP', icon: Search },
    { id: 'directory', label: 'DIR', icon: Users },
    { id: 'catalog', label: 'CATALOG', icon: Wrench, adminOnly: true },
    { id: 'daily', label: 'LOGS', icon: FileSpreadsheet },
    { id: 'stock', label: 'STOCK', icon: Package },
    ...(isManagementAdmin ? [{ id: 'admins', label: 'ADMIN', icon: ShieldCheck }] : [])
  ].filter(tab => !tab.adminOnly || isSuperAdmin), [isSuperAdmin, isManagementAdmin]);

  const visibleEmployees = useMemo(() => 
    isSuperAdmin ? fullEmployeeDirectory : fullEmployeeDirectory.filter(e => e.department === user?.department),
  [isSuperAdmin, fullEmployeeDirectory, user]);

  const filteredDirectory = useMemo(() => {
    let list = visibleEmployees;
    if (isSuperAdmin && directoryDeptFilter) list = list.filter(e => e.department === directoryDeptFilter);
    if (directorySearchQuery.trim()) {
      const q = directorySearchQuery.toLowerCase();
      list = list.filter(e => String(e.id).toLowerCase().includes(q) || String(e.name).toLowerCase().includes(q));
    }
    return list;
  }, [visibleEmployees, isSuperAdmin, directoryDeptFilter, directorySearchQuery]);

  const visibleTransactions = useMemo(() => {
    let list = isSuperAdmin ? allTransactions : allTransactions.filter(t => t.department === user?.department);

    // Filter by Logs Search Query (Tool name, Employee name, or ID)
    if (logsSearchQuery.trim()) {
      const q = logsSearchQuery.toLowerCase().trim();
      list = list.filter(t => 
        t.toolName.toLowerCase().includes(q) || 
        (t.employeeName && t.employeeName.toLowerCase().includes(q)) ||
        (t.employeeId && String(t.employeeId).toLowerCase().includes(q))
      );
    }

    if (showBulkLogsOnly) list = list.filter(t => t.quantity >= 2);
    return list;
  }, [isSuperAdmin, allTransactions, user, showBulkLogsOnly, logsSearchQuery]);

  const paginatedLogs = useMemo(() => {
    const sorted = [...visibleTransactions].reverse();
    return sorted.slice((currentLogsPage - 1) * LOGS_PER_PAGE, currentLogsPage * LOGS_PER_PAGE);
  }, [visibleTransactions, currentLogsPage]);

  const totalLogsPages = useMemo(() => Math.ceil(visibleTransactions.length / LOGS_PER_PAGE), [visibleTransactions]);

  const stockSummaryData = useMemo(() => {
    const map = new Map<string, any>();
    let baseTrx = allTransactions;
    if (!isSuperAdmin) {
      baseTrx = allTransactions.filter(t => t.department === user?.department);
    } else if (selectedDeptFilter !== '') {
      baseTrx = allTransactions.filter(t => t.department === selectedDeptFilter);
    }

    const catalog = isSuperAdmin ? toolCatalog : toolCatalog.filter(t => t.department === user?.department || t.department === 'All');
    catalog.forEach(t => map.set(t.name, { name: t.name, purchase: 0, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0 }));

    baseTrx.forEach(t => {
      let row = map.get(t.toolName);
      if (!row) { row = { name: t.toolName, purchase: 0, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0 }; map.set(t.toolName, row); }
      const q = Number(t.quantity);
      if (t.entryType === 'Stock IN') row.purchase += q;
      else if (t.entryType === 'Distribute') row.distributed += q;
      else if (t.entryType === 'Return') row.returned += q;
      else if (t.entryType === 'Faulty Return') row.faulty += q;
      else if (t.entryType === 'Damage') row.damage += q;
      else if (t.entryType === 'Lost') row.lost += q;
    });

    let results = Array.from(map.values()).map(r => ({ ...r, stockNow: (r.purchase + r.returned) - (r.distributed + r.faulty + r.damage + r.lost) }));
    if (stockSearchQuery.trim()) results = results.filter(r => r.name.toLowerCase().includes(stockSearchQuery.toLowerCase()));
    return results.sort((a, b) => a.name.localeCompare(b.name));
  }, [allTransactions, toolCatalog, isSuperAdmin, user, stockSearchQuery, selectedDeptFilter]);

  const employeeToolsData = useMemo(() => {
    if (!selectedEmployee) return [];
    const map = new Map<string, any>();
    allTransactions.filter(t => t.employeeId === selectedEmployee.id).forEach(t => {
      let row = map.get(t.toolName);
      if (!row) { row = { name: t.toolName, distributed: 0, returned: 0, faulty: 0, damage: 0, lost: 0, remarks: '' }; map.set(t.toolName, row); }
      const q = Number(t.quantity);
      if (t.entryType === 'Distribute') row.distributed += q;
      else if (t.entryType === 'Return') row.returned += q;
      else if (t.entryType === 'Faulty Return') row.faulty += q;
      else if (t.entryType === 'Damage') row.damage += q;
      else if (t.entryType === 'Lost') row.lost += q;
      if (t.remarks) row.remarks = t.remarks;
    });
    return Array.from(map.values()).sort((a, b) => a.name.localeCompare(b.name));
  }, [selectedEmployee, allTransactions]);

  const employeeHistory = useMemo(() => {
    if (!selectedEmployee) return [];
    return allTransactions.filter(t => t.employeeId === selectedEmployee.id).reverse();
  }, [selectedEmployee, allTransactions]);

  const handleExportStock = () => {
    const headers = ['Tool Name', 'Stock IN', 'Dist.', 'Ret.', 'Faulty', 'Damage', 'Lost', 'Current Stock'];
    const csvContent = [headers.join(','), ...stockSummaryData.map(r => [`"${r.name}"`, r.purchase, r.distributed, r.returned, r.faulty, r.damage, r.lost, r.stockNow].join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `SARBS_Stock_${new Date().getTime()}.csv`;
    link.click();
  };

  const handleSaveEmployee = async (data: any) => {
    setIsSyncing(true);
    if (await saveEmployeeToSheet(data)) {
      alert("Profile Committed.");
      setIsEmployeeModalOpen(false);
      setEditingEmployee(null);
      await loadData(true);
    } else { alert("Failed to save."); setIsSyncing(false); }
  };

  const handleDeleteEmployee = async (id: string) => {
    if (!confirm("Permanently archive this personnel to Discard list?")) return;
    setIsSyncing(true);
    if (await deleteEmployeeFromSheet(id)) {
      alert("Personnel Archived.");
      await loadData(true);
    } else { alert("Error."); setIsSyncing(false); }
  };

  const handleDeleteAdmin = async (id: string, role: string) => {
    if (role.toLowerCase().includes('super')) return alert("Super Admin accounts are protected.");
    if (!confirm(`Delete admin access for ID: ${id}?`)) return;
    setIsSyncing(true);
    if (await deleteAdminFromSheet(id)) {
      alert("Access Revoked.");
      await loadData(true);
