  const handleExportStock = () => {
    // Row 1: Totals row with formulas for evaluation in Excel/Sheets
    // A1: Label, B1-H1: Subtotal Formulas (Sum of rows 3 to 1000)
    const totalRow = [
      '"Total Filtered Tools"', // A1
      '=SUBTOTAL(9,B3:B1000)',   // B1
      '=SUBTOTAL(9,C3:C1000)',   // C1
      '=SUBTOTAL(9,D3:D1000)',   // D1
      '=SUBTOTAL(9,E3:E1000)',   // E1
      '=SUBTOTAL(9,F3:F1000)',   // F1
      '=SUBTOTAL(9,G3:G1000)',   // G1
      '=SUBTOTAL(9,H3:H1000)'    // H1
    ].join(',');

    // Row 2: Headers
    const headers = ['Tool Name', 'Stock IN', 'Distributed', 'Returned', 'Faulty', 'Damage', 'Lost', 'Current Stock'];
    const headerRow = headers.map(h => `"${h}"`).join(',');

    // Row 3 onwards: Data rows
    const dataRows = stockSummaryData.map(r => [
      `"${r.name.replace(/"/g, '""')}"`, 
      r.purchase, 
      r.distributed, 
      r.returned, 
      r.faulty, 
      r.damage, 
      r.lost, 
      r.stockNow
    ].join(','));

    // Building full CSV content with UTF-8 BOM
    const csvContent = "\uFEFF" + [totalRow, headerRow, ...dataRows].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `SARBS_Stock_Ledger_${new Date().toISOString().slice(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

